def _convergence_test_mode_enabled() -> bool:
  raw = (os.getenv("CONVERGENCE_TEST_MODE") or "false").strip().lower()
  return raw not in {"", "0", "false", "no", "off"}


def _handle_convergence_test_mode_failure(
  quality_assessment: Optional[Dict[str, Any]],
) -> None:
  assessment = quality_assessment if isinstance(quality_assessment, dict) else {}
  strict_failure = (
    assessment.get("strict_failure")
    if isinstance(assessment.get("strict_failure"), dict)
    else {}
  )
  if not strict_failure:
    return
  terminal_message = str(strict_failure.get("terminal_message") or "").strip()
  detail = str(
    strict_failure.get("detail")
    or terminal_message
    or "unified_convergence_test_mode_failure"
  ).strip()
  if _convergence_test_mode_enabled():
    if terminal_message:
      print(terminal_message, flush=True)
      logger.error(terminal_message)
    raise RuntimeError(detail)
  if terminal_message:
    logger.warning(terminal_message)
  else:
    logger.warning(detail)


def _build_convergence_progress_failure_diagnostics(
  *,
  cycles_attempted: int,
  last_known_state: Optional[Dict[str, Any]],
  repeated_failure_pattern: Optional[Dict[str, Any]],
  planner_plan_status: str = "",
) -> Dict[str, Any]:
  state = last_known_state if isinstance(last_known_state, dict) else {}
  pattern = repeated_failure_pattern if isinstance(repeated_failure_pattern, dict) else {}
  return {
    "failure_stage": "convergence_progress",
    "failure_reason": "no_meaningful_progress",
    "cycles_attempted": int(_safe_float(cycles_attempted) or 0),
    "last_known_state": {
      "remaining_issue_count": int(_safe_float(state.get("remaining_issue_count")) or 0),
      "resolved_issue_count": int(_safe_float(state.get("resolved_issue_count")) or 0),
      "tolerated_issue_count": int(_safe_float(state.get("tolerated_issue_count")) or 0),
      "pre_solver_validation_flags": copy.deepcopy(pattern.get("pre_solver_validation_flags") or []),
    },
    "repeated_failure_pattern": {
      "planner_status": str(pattern.get("planner_status") or planner_plan_status or "").strip() or None,
      "solver_invoked": bool(pattern.get("solver_invoked")),
      "invalid_levers": copy.deepcopy(pattern.get("invalid_levers") or []),
      "pre_solver_validation_flags": copy.deepcopy(pattern.get("pre_solver_validation_flags") or []),
    },
    "convergence_test_mode": _convergence_test_mode_enabled(),
  }


def _build_unified_cycle_stall_assessment(
  *,
  consecutive_no_progress_cycles: int,
  latest_quality_assessment: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
  quality = latest_quality_assessment if isinstance(latest_quality_assessment, dict) else {}
  consecutive = max(0, int(consecutive_no_progress_cycles or 0))
  open_issue_codes = [
    str(item).strip().lower()
    for item in (quality.get("open_issue_codes_after") or quality.get("open_issue_codes_before") or [])
    if str(item).strip()
  ]
  structural_issue_codes = [
    code
    for code in open_issue_codes
    if code in _ISSUE_CODE_REGISTRY
  ]
  progress_detected = bool(quality.get("meaningful_progress"))
  same_issue_signature_without_progress = bool(quality.get("same_issue_signature_without_progress"))
  issue_count_regressed_without_progress = bool(
    quality.get("issue_count_regressed")
    and not progress_detected
  )
  unresolved_issue_plateau = bool(quality.get("unresolved_issue_plateau"))
  stalled = bool(
    consecutive >= 1
    or same_issue_signature_without_progress
    or quality.get("no_progress")
    or quality.get("insufficient_issue_progress")
    or quality.get("early_failure_detected")
    or issue_count_regressed_without_progress
    or unresolved_issue_plateau
    or quality.get("cash_only_viability_progress")
  )
  structurally_stalled = bool(
    consecutive >= 2
    or (structural_issue_codes and (unresolved_issue_plateau or consecutive >= 1))
  )
  return {
    "stalled": stalled,
    "consecutive_no_progress_cycles": consecutive,
    "force_material_tactic_change": stalled,
    "force_full_horizon_scope": False,
    "force_all_writable_levers": False,
    "force_structural_driver_changes": structurally_stalled,
    "minimum_new_lever_count": 3 if structurally_stalled else (2 if stalled else 0),
    "require_target_reframe_on_same_issue_state": same_issue_signature_without_progress,
    "open_issue_codes": copy.deepcopy(open_issue_codes),
    "structural_issue_codes": copy.deepcopy(structural_issue_codes),
    "required_change_type": "structural" if structurally_stalled else ("focused_reframe" if stalled else "none"),
    "latest_quality_assessment": copy.deepcopy(quality),
    "instruction": (
      "The convergence loop has stalled. The next attempt must materially change tactic within the current 20-quarter contract."
      if stalled
      else "No unified-cycle stall is currently detected."
    ),
  }


def _cash_strategy_fail_flags_from_review_payload(
  review_payload: Optional[Dict[str, Any]],
) -> List[str]:
  payload = review_payload if isinstance(review_payload, dict) else {}
  status = str(payload.get("status") or "").strip().lower()
  flags: List[str] = []
  if status != "completed":
    flags.append("cash_pass_not_executed")
  if status == "failed_parse":
    flags.append("cash_parse_failed")
  if status == "completed" and not bool(payload.get("prompt_trace")):
    flags.append("cash_prompt_trace_missing")
  if status == "completed" and not bool(payload.get("raw_openai_response")):
    flags.append("cash_raw_response_missing")
  if str(payload.get("decision_source") or "").strip().lower() not in {"", "gpt"}:
    flags.append("cash_non_gpt_fallback_used")
  return list(dict.fromkeys(flag for flag in flags if flag in _CASH_STRATEGY_TEST_MODE_FAIL_FLAGS))


def _cash_strategy_failure_stage(
  *,
  review_payload: Optional[Dict[str, Any]] = None,
  plan_payload: Optional[Dict[str, Any]] = None,
  result_payload: Optional[Dict[str, Any]] = None,
) -> str:
  review = review_payload if isinstance(review_payload, dict) else {}
  plan = plan_payload if isinstance(plan_payload, dict) else {}
  result = result_payload if isinstance(result_payload, dict) else {}
  if _cash_strategy_fail_flags_from_review_payload(review):
    return "review"
  if plan.get("translation_fail_flags"):
    return "translation"
  if result.get("fail_flags") or result.get("post_validation"):
    return "validation"
  return "translation"


def _cash_validation_errors_from_failure_payload(
  *,
  review_payload: Optional[Dict[str, Any]] = None,
  plan_payload: Optional[Dict[str, Any]] = None,
  result_payload: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
  review = review_payload if isinstance(review_payload, dict) else {}
  plan = plan_payload if isinstance(plan_payload, dict) else {}
  result = result_payload if isinstance(result_payload, dict) else {}
  errors: List[Dict[str, Any]] = []
  for warning in [str(item).strip() for item in (plan.get("translation_warnings") or []) if str(item).strip()]:
    errors.append(
      {
        "quarter": None,
        "lever": None,
        "expected": "cash adjustment inside deterministic cash bounds",
        "actual": warning,
        "reason": warning,
      }
    )
  post_validation = (
    result.get("post_validation")
    if isinstance(result.get("post_validation"), dict)
    else {}
  )
  for issue_code in [str(item).strip() for item in (post_validation.get("remaining_issue_codes") or []) if str(item).strip()]:
    errors.append(
      {
        "quarter": None,
        "lever": None,
        "expected": "all issues remain cleared after cash pass",
        "actual": issue_code,
        "reason": "cash_pass_reopened_issue",
      }
    )
  for rule_code in [str(item).strip() for item in (post_validation.get("failed_rule_codes") or []) if str(item).strip()]:
    errors.append(
      {
        "quarter": None,
        "lever": None,
        "expected": "all hard rules remain satisfied after cash pass",
        "actual": rule_code,
        "reason": "cash_pass_failed_hard_rule",
      }
    )
  for violation in [item for item in (post_validation.get("cash_buffer_violations") or []) if isinstance(item, dict)]:
    errors.append(
      {
        "quarter": int(_safe_float(violation.get("quarter_index")) or 0) or None,
        "lever": None,
        "expected": f"ending_cash >= {int(round(float(_safe_float(violation.get('buffer')) or 0.0)))}",
        "actual": f"{int(round(float(_safe_float(violation.get('ending_cash')) or 0.0)))}",
        "reason": "cash_buffer_violation",
      }
    )
  if (
    not errors
    and isinstance(review.get("detail"), str)
    and str(review.get("detail") or "").strip()
    and str(review.get("status") or "").strip().lower() != "completed"
  ):
    errors.append(
      {
        "quarter": None,
        "lever": None,
        "expected": "completed GPT cash review",
        "actual": str(review.get("status") or "").strip() or None,
        "reason": str(review.get("detail") or "").strip(),
      }
    )
  return errors


def _build_cash_strategy_failure_diagnostics(
  *,
  review_payload: Optional[Dict[str, Any]] = None,
  plan_payload: Optional[Dict[str, Any]] = None,
  result_payload: Optional[Dict[str, Any]] = None,
  extra_flags: Optional[List[str]] = None,
) -> Dict[str, Any]:
  review = review_payload if isinstance(review_payload, dict) else {}
  plan = plan_payload if isinstance(plan_payload, dict) else {}
  result = result_payload if isinstance(result_payload, dict) else {}
  flags = list(
    dict.fromkeys(
      [
        *[str(item).strip() for item in (_cash_strategy_fail_flags_from_review_payload(review) or []) if str(item).strip()],
        *[str(item).strip() for item in (plan.get("translation_fail_flags") or []) if str(item).strip()],
        *[str(item).strip() for item in (result.get("fail_flags") or []) if str(item).strip()],
        *[str(item).strip() for item in (extra_flags or []) if str(item).strip()],
      ]
    )
  )
  context_payload = (
    review.get("cash_strategy_review_context")
    if isinstance(review.get("cash_strategy_review_context"), dict)
    else {}
  )
  return {
    "cash_plan_fail_stage": _cash_strategy_failure_stage(
      review_payload=review,
      plan_payload=plan,
      result_payload=result,
    ),
    "cash_plan_fail_flags": flags,
    "cash_prompt_trace": copy.deepcopy(review.get("prompt_trace") or {}),
    "cash_raw_response": copy.deepcopy(review.get("raw_openai_response") or {}),
    "cash_review_decision": copy.deepcopy(review.get("decision") or {}),
    "cash_translated_plan": copy.deepcopy(plan or {}),
    "cash_bounds_context": {
      "selected_cash_strategy": str(review.get("selected_cash_strategy") or "").strip() or None,
      "allowed_quarters": copy.deepcopy(context_payload.get("allowed_quarters") or []),
      "lever_bounds": copy.deepcopy(context_payload.get("lever_bounds") or {}),
      "summary_metrics": copy.deepcopy(context_payload.get("summary_metrics") or {}),
      "cash_profile_summary": copy.deepcopy(context_payload.get("cash_profile_summary") or {}),
    },
    "cash_validation_errors": _cash_validation_errors_from_failure_payload(
      review_payload=review,
      plan_payload=plan,
      result_payload=result,
    ),
    "cash_result_payload": copy.deepcopy(result or {}),
  }


def _build_cash_strategy_test_mode_terminal_message(
  *,
  failure_payload: Optional[Dict[str, Any]],
) -> str:
  payload = failure_payload if isinstance(failure_payload, dict) else {}
  failure_diagnostics = (
    payload.get("cash_failure_diagnostics")
    if isinstance(payload.get("cash_failure_diagnostics"), dict)
    else {}
  )
  return "\n".join(
    [
      "STRICT FAILURE: cash strategy test mode triggered",
      f"cash_plan_fail_stage={str(failure_diagnostics.get('cash_plan_fail_stage') or 'unknown').strip() or 'unknown'}",
      f"selected_cash_strategy={str(payload.get('selected_cash_strategy') or '').strip() or 'unknown'}",
      f"status={str(payload.get('status') or '').strip() or 'unknown'}",
      f"selected_levers={', '.join([str(item).strip() for item in (payload.get('selected_lever_ids') or []) if str(item).strip()]) or 'none'}",
      f"flags={', '.join([str(item).strip() for item in (payload.get('flags') or []) if str(item).strip()]) or 'none'}",
      f"before_remaining_issue_count={int(_safe_float(payload.get('before_remaining_issue_count')) or 0)} after_remaining_issue_count={int(_safe_float(payload.get('after_remaining_issue_count')) or 0)}",
      f"before_all_cleared={bool(payload.get('before_all_cleared'))} after_all_cleared={bool(payload.get('after_all_cleared'))}",
    ]
  )


def _handle_cash_strategy_test_mode_failure(
  failure_payload: Optional[Dict[str, Any]],
) -> None:
  payload = failure_payload if isinstance(failure_payload, dict) else {}
  if not payload:
    return
  terminal_message = str(payload.get("terminal_message") or "").strip()
  detail = str(payload.get("detail") or terminal_message or "cash_strategy_test_mode_failure").strip()
  if _convergence_test_mode_enabled():
    if terminal_message:
      print(terminal_message, flush=True)
      logger.error(terminal_message)
    raise StructuredSystemRunFailure(
      detail=detail,
      diagnostics=copy.deepcopy(payload),
    )
  if terminal_message:
    logger.warning(terminal_message)
  else:
    logger.warning(detail)


def _build_cash_strategy_test_failure_payload(
  *,
  review_payload: Optional[Dict[str, Any]] = None,
  plan_payload: Optional[Dict[str, Any]] = None,
  result_payload: Optional[Dict[str, Any]] = None,
  before_controller_resolution_state: Optional[Dict[str, Any]] = None,
  after_controller_resolution_state: Optional[Dict[str, Any]] = None,
  extra_flags: Optional[List[str]] = None,
  detail: str = "",
) -> Dict[str, Any]:
  review = review_payload if isinstance(review_payload, dict) else {}
  plan = plan_payload if isinstance(plan_payload, dict) else {}
  result = result_payload if isinstance(result_payload, dict) else {}
  before_state = before_controller_resolution_state if isinstance(before_controller_resolution_state, dict) else {}
  after_state = after_controller_resolution_state if isinstance(after_controller_resolution_state, dict) else {}
  review_flags = _cash_strategy_fail_flags_from_review_payload(review)
  plan_flags = [
    str(item).strip()
    for item in (plan.get("translation_fail_flags") or [])
    if str(item).strip() in _CASH_STRATEGY_TEST_MODE_FAIL_FLAGS
  ]
  result_flags = [
    str(item).strip()
    for item in (result.get("fail_flags") or [])
    if str(item).strip() in _CASH_STRATEGY_TEST_MODE_FAIL_FLAGS
  ]
  combined_flags = list(
    dict.fromkeys(
      [
        *review_flags,
        *plan_flags,
        *result_flags,
        *[
          str(item).strip()
          for item in (extra_flags or [])
          if str(item).strip() in _CASH_STRATEGY_TEST_MODE_FAIL_FLAGS
        ],
      ]
    )
  )
  selected_lever_ids = [
    str(item).strip()
    for item in (plan.get("touched_lever_ids") or [])
    if str(item).strip()
  ]
  if not selected_lever_ids:
    selected_lever_ids = [
      str((item or {}).get("lever_id") or "").strip()
      for item in ((review.get("decision") or {}).get("recommended_adjustments") or [])
      if isinstance(item, dict) and str((item or {}).get("lever_id") or "").strip()
    ]
  status = (
    str(result.get("status") or "").strip()
    or str(plan.get("status") or "").strip()
    or str(review.get("status") or "").strip()
  )
  payload = {
    "selected_cash_strategy": str(review.get("selected_cash_strategy") or "").strip(),
    "status": status,
    "selected_lever_ids": selected_lever_ids,
    "flags": combined_flags,
    "before_remaining_issue_count": int(_safe_float(before_state.get("remaining_issue_count")) or 0),
    "after_remaining_issue_count": int(_safe_float(after_state.get("remaining_issue_count")) or 0),
    "before_all_cleared": bool(before_state.get("all_cleared")),
    "after_all_cleared": bool(after_state.get("all_cleared")),
    "detail": str(detail or "").strip() or "cash_strategy_test_mode_failure",
  }
  payload["cash_failure_diagnostics"] = _build_cash_strategy_failure_diagnostics(
    review_payload=review,
    plan_payload=plan,
    result_payload=result,
    extra_flags=combined_flags,
  )
  payload["terminal_message"] = _build_cash_strategy_test_mode_terminal_message(
    failure_payload=payload
  )
  return payload


def _reset_openai_call_telemetry() -> None:
  _OPENAI_CALL_TELEMETRY["logical_call_count"] = 0
  _OPENAI_CALL_TELEMETRY["by_model"] = {}
  _OPENAI_CALL_TELEMETRY["events"] = []


def _openai_call_telemetry_snapshot() -> Dict[str, Any]:
  return {
    "logical_call_count": int(_safe_float(_OPENAI_CALL_TELEMETRY.get("logical_call_count")) or 0),
    "by_model": copy.deepcopy(
      _OPENAI_CALL_TELEMETRY.get("by_model")
      if isinstance(_OPENAI_CALL_TELEMETRY.get("by_model"), dict)
      else {}
    ),
    "events": copy.deepcopy(
      _OPENAI_CALL_TELEMETRY.get("events")
      if isinstance(_OPENAI_CALL_TELEMETRY.get("events"), list)
      else []
    ),
  }


def _parse_json_dict(raw: Any) -> Dict[str, Any]:
  if raw is None:
    return {}
  if isinstance(raw, dict):
    return raw
  try:
    parsed = json.loads(str(raw))
  except Exception:
    return {}
  return parsed if isinstance(parsed, dict) else {}


def _parse_messages(raw: Any) -> List[Dict[str, str]]:
  if raw is None:
    return []
  if isinstance(raw, list):
    return [m for m in raw if isinstance(m, dict)]
  try:
    parsed = json.loads(str(raw))
  except Exception:
    return []
  return [m for m in parsed if isinstance(m, dict)] if isinstance(parsed, list) else []


def _parse_pending_bool(raw: Any) -> bool:
  # Treat any non-null-ish, truthy value as pending.
  if raw is None:
    return False
  if raw is False:
    return False
  if raw == 0:
    return False
  if isinstance(raw, str):
    val = raw.strip().lower()
    if not val or val in ("0", "false", "null", "none", "[]", "{}"):
      return False
    return True
  if isinstance(raw, (list, dict)):
    return bool(raw)
  return bool(raw)


def _is_missing_number_value(value: Any) -> bool:
  if value is None:
    return True
  if isinstance(value, bool):
    return True
  try:
    return float(value) <= 0
  except Exception:
    return True


def _normalize_ops_capacity_compat(ops_obj: Any) -> Any:
  """
  Capacity compatibility: keep ops capacity coherent without re-asking the user.

  Rules (minimal, non-destructive):
  - If unit_cadence is weekly and week capacity is set, fill missing period capacity from it.
  - If unit_cadence is monthly/contract and period capacity is set, fill missing week capacity from it.
  - If unit_cadence is weekly/monthly and operating_periods_per_year is missing, fill it with 52/12.
  - Never overwrite an existing non-missing capacity number.
  - For multi-product ops (lob_models with >1 product), only normalize per-product fields;
    keep top-level unit fields null by design.
  """
  if not isinstance(ops_obj, dict):
    return ops_obj

  def _normalize_unit_dict(d: Dict[str, Any]) -> None:
    cadence = str(d.get("unit_cadence") or "").strip().lower()
    week = d.get("units_per_week_capacity")
    period = d.get("units_per_period_capacity")
    periods_per_year = d.get("operating_periods_per_year")

    if cadence == "weekly":
      if _is_missing_number_value(period) and not _is_missing_number_value(week):
        d["units_per_period_capacity"] = week
      if _is_missing_number_value(periods_per_year):
        d["operating_periods_per_year"] = 52
      return

    if cadence in ("monthly", "contract"):
      if _is_missing_number_value(week) and not _is_missing_number_value(period):
        d["units_per_week_capacity"] = period
      elif _is_missing_number_value(period) and not _is_missing_number_value(week):
        d["units_per_period_capacity"] = week
      if cadence == "monthly" and _is_missing_number_value(periods_per_year):
        d["operating_periods_per_year"] = 12
      return

    # Unknown cadence: best-effort fill the missing side only.
    if _is_missing_number_value(week) and not _is_missing_number_value(period):
      d["units_per_week_capacity"] = period
    elif _is_missing_number_value(period) and not _is_missing_number_value(week):
      d["units_per_period_capacity"] = week

  lob_models = ops_obj.get("lob_models")
  product_count = 0
  if isinstance(lob_models, list):
    for lob in lob_models:
      if not isinstance(lob, dict):
        continue
      prods = lob.get("products")
      if not isinstance(prods, list):
        continue
      for p in prods:
        if isinstance(p, dict):
          product_count += 1
          _normalize_unit_dict(p)

  # Only normalize top-level unit fields if this is not a multi-product model.
  if product_count <= 1:
    _normalize_unit_dict(ops_obj)

  return ops_obj


def _count_ops_products(ops_obj: Any) -> int:
  if not isinstance(ops_obj, dict):
    return 0
  total = 0
  lob_models = ops_obj.get("lob_models")
  if not isinstance(lob_models, list):
    return 0
  for lob in lob_models:
    if not isinstance(lob, dict):
      continue
    products = lob.get("products")
    if not isinstance(products, list):
      continue
    total += sum(1 for product in products if isinstance(product, dict))
  return total


def _extract_single_compact_number(text: Any) -> Optional[float]:
  blob = str(text or "").strip()
  if not blob:
    return None
  tokens = re.findall(r"\$?\d[\d,]*(?:\.\d+)?\s*[kKmM]?", blob)
  values: List[float] = []
  for tok in tokens:
    cleaned = str(tok or "").strip().replace("$", "").replace(",", "")
    match = re.match(r"^(\d+(?:\.\d+)?)\s*([kKmM]?)$", cleaned)
    if not match:
      continue
    try:
      value = float(match.group(1))
    except Exception:
      continue
    suffix = str(match.group(2) or "").strip().lower()
    if suffix == "k":
      value *= 1000.0
    elif suffix == "m":
      value *= 1000000.0
    values.append(value)
  if len(values) != 1:
    return None
  value = float(values[0])
  return value if value > 0 else None


def _extract_single_compact_number_allow_zero(text: Any) -> Optional[float]:
  blob = str(text or "").strip()
  if not blob:
    return None
  tokens = re.findall(r"\$?\d[\d,]*(?:\.\d+)?\s*[kKmM]?", blob)
  values: List[float] = []
  for tok in tokens:
    cleaned = str(tok or "").strip().replace("$", "").replace(",", "")
    match = re.match(r"^(\d+(?:\.\d+)?)\s*([kKmM]?)$", cleaned)
    if not match:
      continue
    try:
      value = float(match.group(1))
    except Exception:
      continue
    suffix = str(match.group(2) or "").strip().lower()
    if suffix == "k":
      value *= 1000.0
    elif suffix == "m":
      value *= 1000000.0
    values.append(value)
  if not values:
    return None
  unique_values: List[float] = []
  for value in values:
    if not any(abs(value - existing) < 1e-9 for existing in unique_values):
      unique_values.append(value)
  if len(unique_values) != 1:
    return None
  value = float(unique_values[0])
  return value if value >= 0 else None


def _extract_compact_numbers(text: Any) -> List[float]:
  blob = str(text or "").strip()
  if not blob:
    return []
  tokens = re.findall(r"\$?\d[\d,]*(?:\.\d+)?\s*[kKmM]?", blob)
  values: List[float] = []
  for tok in tokens:
    cleaned = str(tok or "").strip().replace("$", "").replace(",", "")
    match = re.match(r"^(\d+(?:\.\d+)?)\s*([kKmM]?)$", cleaned)
    if not match:
      continue
    try:
      value = float(match.group(1))
    except Exception:
      continue
    suffix = str(match.group(2) or "").strip().lower()
    if suffix == "k":
      value *= 1000.0
    elif suffix == "m":
      value *= 1000000.0
    values.append(value)
  return values


def _looks_like_capacity_prompt(text: Any) -> bool:
  prompt = str(text or "").strip().lower()
  if not prompt:
    return False
  if "how many" not in prompt and "capacity" not in prompt:
    return False
  if "can you handle" in prompt and ("fully booked" in prompt or "busy month" in prompt or "busy week" in prompt):
    return True
  if "to make planning realistic" in prompt and ("fully busy" in prompt or "fully booked" in prompt):
    return True
  if "operationally stretched" in prompt or "over-crowded" in prompt:
    return True
  return False


def _capacity_field_for_cadence(cadence: Any) -> Tuple[str, str]:
  cadence_norm = str(cadence or "").strip().lower()
  if cadence_norm == "weekly":
    return "units_per_week_capacity", "week"
  if cadence_norm in {"monthly", "contract"}:
    return "units_per_period_capacity", "month"
  return "units_per_period_capacity", "period"


def _find_missing_capacity_target(
  snapshot_obj: Any,
  *,
  fallback_ops: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
  if not isinstance(snapshot_obj, dict):
    return None
  fallback = fallback_ops if isinstance(fallback_ops, dict) else {}
  lob_models = snapshot_obj.get("lob_models")
  if isinstance(lob_models, list):
    for lob_index, lob in enumerate(lob_models):
      if not isinstance(lob, dict):
        continue
      products = lob.get("products")
      if not isinstance(products, list):
        continue
      for product_index, product in enumerate(products):
        if not isinstance(product, dict):
          continue
        if not _is_missing_number_value(product.get("units_per_period_capacity")) or not _is_missing_number_value(
          product.get("units_per_week_capacity")
        ):
          continue
        cadence = (
          product.get("unit_cadence")
          or snapshot_obj.get("unit_cadence")
          or fallback.get("unit_cadence")
        )
        field, period_label = _capacity_field_for_cadence(cadence)
        label = str(
          product.get("product_name")
          or product.get("unit_name")
          or snapshot_obj.get("unit_name")
          or fallback.get("unit_name")
          or "this offering"
        ).strip()
        return {
          "kind": "product",
          "lob_index": lob_index,
          "product_index": product_index,
          "field": field,
          "period_label": period_label,
          "label": label,
        }
  if _is_missing_number_value(snapshot_obj.get("units_per_period_capacity")) and _is_missing_number_value(
    snapshot_obj.get("units_per_week_capacity")
  ):
    cadence = snapshot_obj.get("unit_cadence") or fallback.get("unit_cadence")
    field, period_label = _capacity_field_for_cadence(cadence)
    label = str(snapshot_obj.get("unit_name") or fallback.get("unit_name") or "units").strip() or "units"
    return {
      "kind": "top_level",
      "field": field,
      "period_label": period_label,
      "label": label,
    }
  return None


def _build_capacity_target_question(target: Dict[str, Any]) -> str:
  period_label = str(target.get("period_label") or "period").strip() or "period"
  label = str(target.get("label") or "units").strip() or "units"
  if str(target.get("kind") or "").strip() == "product":
    return (
      f"To make planning realistic for {label}, in a fully busy {period_label}, "
      f"about how many {label} can you handle?"
    ).strip()
  return (
    f"To make planning realistic, in a fully busy {period_label}, "
    f"about how many {label} can you handle?"
  ).strip()


def _apply_capacity_target_value(snapshot_obj: Any, target: Dict[str, Any], value: float) -> Dict[str, Any]:
  next_snapshot = json.loads(json.dumps(snapshot_obj if isinstance(snapshot_obj, dict) else {}))
  field = str(target.get("field") or "").strip()
  if not field:
    return _normalize_ops_capacity_compat(next_snapshot)
  if str(target.get("kind") or "").strip() == "product":
    try:
      lob_index = int(target.get("lob_index"))
      product_index = int(target.get("product_index"))
      next_snapshot["lob_models"][lob_index]["products"][product_index][field] = float(value)
    except Exception:
      return _normalize_ops_capacity_compat(next_snapshot)
  else:
    next_snapshot[field] = float(value)
  return _normalize_ops_capacity_compat(next_snapshot)


def _apply_capacity_snapshot_to_ops_json(
  ops_json: Dict[str, Any],
  snapshot_obj: Dict[str, Any],
  target: Dict[str, Any],
) -> Dict[str, Any]:
  patch_obj: Dict[str, Any] = {}
  if isinstance(snapshot_obj.get("lob_models"), list):
    patch_obj["lob_models"] = snapshot_obj.get("lob_models")
  field = str(target.get("field") or "").strip()
  if field and field in snapshot_obj:
    patch_obj[field] = snapshot_obj.get(field)
  return _apply_model_ops_patch(dict(ops_json or {}), patch_obj)


def _infer_capacity_field_from_prompt(*, last_assistant: str, ops_json: Dict[str, Any]) -> Optional[str]:
  prompt = str(last_assistant or "").strip().lower()
  cadence = str((ops_json or {}).get("unit_cadence") or "").strip().lower()
  if "fully booked week" in prompt:
    return "units_per_week_capacity"
  if "fully booked month" in prompt or "fully booked period" in prompt:
    return "units_per_period_capacity"
  if cadence == "weekly":
    return "units_per_week_capacity"
  if cadence in {"monthly", "contract"}:
    return "units_per_period_capacity"
  return None


def _capacity_confirm_prompt_patch(
  *,
  last_assistant: str,
  user_message: str,
  ops_json: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
  prompt = str(last_assistant or "").strip().lower()
  if "just to confirm your capacity:" not in prompt or "fully booked" not in prompt:
    return None
  if _count_ops_products(ops_json) > 1:
    return None
  value = _extract_single_compact_number(user_message)
  if value is None:
    return None
  field = _infer_capacity_field_from_prompt(last_assistant=last_assistant, ops_json=ops_json or {})
  if not field:
    return None
  return {field: float(value)}


def _apply_model_ops_patch(ops_json: Any, patch_obj: Any) -> Any:
  """
  Merge model-produced incremental Ops facts into the working Ops JSON.

  This mirrors the existing edit_patch persistence style, but stays scoped to Ops
  and ignores nulls so partial snapshots do not wipe prior answers.
  """
  if not isinstance(ops_json, dict) or not isinstance(patch_obj, dict):
    return ops_json

  allowed_keys = {
    "consumer_type",
    "business_type",
    "unit_name",
    "unit_description",
    "unit_cadence",
    "units_per_week_capacity",
    "units_per_period_capacity",
    "operating_periods_per_year",
    "utilization_rate",
    "unit_price",
    "shipping_method",
    "sales_modality",
    "geographic_scope",
    "geographic_coverage",
    "countries",
    "capacity_driver",
    "primary_growth_lever",
    "legal_entity",
    "lob_models",
  }
  for k, v in patch_obj.items():
    key = str(k or "").strip()
    if key not in allowed_keys or v is None:
      continue
    ops_json[key] = v

  # Keep single-product top-level convenience fields aligned with the product row.
  lob_models = ops_json.get("lob_models")
  if isinstance(lob_models, list) and len(lob_models) == 1:
    products = lob_models[0].get("products") if isinstance(lob_models[0], dict) else None
    if isinstance(products, list) and len(products) == 1 and isinstance(products[0], dict):
      product = products[0]

      def _maybe_copy_text(field: str) -> None:
        if not str(ops_json.get(field) or "").strip() and product.get(field) is not None:
          ops_json[field] = product.get(field)

      def _maybe_copy_number(field: str) -> None:
        if _is_missing_number_value(ops_json.get(field)) and product.get(field) is not None:
          ops_json[field] = product.get(field)

      _maybe_copy_text("unit_name")
      _maybe_copy_text("unit_description")
      _maybe_copy_text("unit_cadence")
      _maybe_copy_number("unit_price")
      _maybe_copy_number("units_per_week_capacity")
      _maybe_copy_number("units_per_period_capacity")
      _maybe_copy_number("operating_periods_per_year")
      _maybe_copy_number("utilization_rate")

  return _normalize_ops_capacity_compat(ops_json)


def _first_contract_product_missing_periods(obj: Any) -> Optional[Dict[str, Any]]:
  if not isinstance(obj, dict):
    return None
  lob_models = obj.get("lob_models")
  if isinstance(lob_models, list):
    for lob in lob_models:
      if not isinstance(lob, dict):
        continue
      products = lob.get("products")
      if not isinstance(products, list):
        continue
      for product in products:
        if not isinstance(product, dict):
          continue
        if str(product.get("unit_cadence") or "").strip().lower() != "contract":
          continue
        if _is_missing_number_value(product.get("operating_periods_per_year")):
          return product
    return None
  if str(obj.get("unit_cadence") or "").strip().lower() != "contract":
    return None
  if _is_missing_number_value(obj.get("operating_periods_per_year")):
    return obj
  return None


def _last_assistant_message(messages: List[Dict[str, str]]) -> str:
  for msg in reversed(messages or []):
    if str(msg.get("role") or "").strip().lower() != "assistant":
      continue
    text = str(msg.get("content") or "").strip()
    if text:
      return text
  return ""


def _sync_pending_revenue_adjustment_state(
  financials_json: Dict[str, Any],
  financials_year1_json: Dict[str, Any],
  revenue_adjudication: Any,
) -> Dict[str, Any]:
  next_financials = dict(financials_json or {})
  try:
    from financials_year1 import build_revenue_driver_signature as _build_signature  # type: ignore
  except Exception:
    from client_intake_and_finmo.financials_year1 import (  # type: ignore
      build_revenue_driver_signature as _build_signature,
    )
  current_signature = str(_build_signature(financials_year1_json or {}) or "").strip()
  locked_signature = str(next_financials.get("_revenue_adjustment_locked_signature") or "").strip()

  if locked_signature and current_signature and locked_signature == current_signature:
    next_financials.pop("_pending_revenue_adjustment_signature", None)
    next_financials.pop("_pending_revenue_adjustment_options", None)
    return next_financials

  if not isinstance(revenue_adjudication, dict):
    next_financials.pop("_pending_revenue_adjustment_signature", None)
    next_financials.pop("_pending_revenue_adjustment_options", None)
    return next_financials

  requires_adjustment = bool(revenue_adjudication.get("requires_adjustment"))
  options = revenue_adjudication.get("options")
  options = [option for option in (options or []) if isinstance(option, dict)]
  if requires_adjustment and current_signature and options:
    next_financials["_pending_revenue_adjustment_signature"] = current_signature
    next_financials["_pending_revenue_adjustment_options"] = options
  else:
    next_financials.pop("_pending_revenue_adjustment_signature", None)
    next_financials.pop("_pending_revenue_adjustment_options", None)
  return next_financials


def _build_cogs_baseline_signature(
  financials_year1_json: Dict[str, Any],
  ops_json: Dict[str, Any],
) -> str:
  try:
    from financials_year1 import build_revenue_driver_signature as _build_signature  # type: ignore
  except Exception:
    from client_intake_and_finmo.financials_year1 import (  # type: ignore
      build_revenue_driver_signature as _build_signature,
    )
  revenue_signature = str(_build_signature(financials_year1_json or {}) or "").strip()
  naics = str((ops_json or {}).get("business_naics_6") or "").strip()
  return f"{naics}::{revenue_signature}" if revenue_signature or naics else ""


