def _run_unified_post_grid_system_run(
  *,
  conn,
  draft_id: str,
  planning_run_id: Optional[str],
  business_facts: Dict[str, Any],
  planning_context_summary_json: Optional[Dict[str, Any]],
  ops_json: Dict[str, Any],
  target_market_json: Dict[str, Any],
  people_json: Dict[str, Any],
  financials_json: Dict[str, Any],
  financials_year1_json: Dict[str, Any],
  fulfillment_json: Dict[str, Any],
  marketing_model_json: Dict[str, Any],
  planning_mode: str,
  planning_mode_reason: str,
  planning_result: Dict[str, Any],
  grid_application_summary: Optional[Dict[str, Any]],
  catalog_source_model_input_json: Dict[str, Any],
  applied_model_input_json: Dict[str, Any],
  applied_finmo_json: Dict[str, Any],
  stage_ramp_contract: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
  try:
    from client_intake_and_finmo.numeric_execution import build_numeric_solver_contract  # type: ignore
  except Exception:
    from numeric_execution import build_numeric_solver_contract  # type: ignore

  active_planning_run_id = str(planning_run_id or "").strip()
  prompt_file = str(planning_result.get("prompt_file") or "").strip()
  final_model_input_json = _model_input_with_controller_catalog(
    model_input_json=copy.deepcopy(applied_model_input_json or {}),
    catalog_source_model_input_json=copy.deepcopy(catalog_source_model_input_json or {}),
  )
  if not isinstance(stage_ramp_contract, dict) or not stage_ramp_contract:
    raise RuntimeError(
      "stage_ramp_contract_missing_before_convergence: GPT stage ramp contract must be generated before post-intake convergence."
    )
  final_finmo_json = copy.deepcopy(applied_finmo_json or {})
  realism_memo_before_resolution = generate_realism_memo_payload_safe(
    ops_json=ops_json,
    financials_json=financials_json,
    solved_model_input_json=copy.deepcopy(final_model_input_json),
    solved_finmo_json=copy.deepcopy(final_finmo_json),
  )
  realism_issue_ledger = _build_issue_status_records_from_issue_list(
    current_issues=_memo_issue_records(copy.deepcopy(realism_memo_before_resolution), "remaining_issues", "issues"),
    iteration=0,
  )
  flatline_issue_ledger = _build_p_and_l_flatline_issue_status_records(
    model_input_json=copy.deepcopy(final_model_input_json),
    finmo_json=copy.deepcopy(final_finmo_json),
    iteration=0,
  )
  stage_maturity_issue_ledger = _build_stage_maturity_cost_structure_issue_status_records(
    model_input_json=copy.deepcopy(final_model_input_json),
    finmo_json=copy.deepcopy(final_finmo_json),
    stage_ramp_contract=copy.deepcopy(stage_ramp_contract),
    iteration=0,
  )
  realism_issue_ledger = _refresh_issue_status_records_from_scan(
    existing_issue_status_records=[],
    scanned_issue_status_records=(
      copy.deepcopy(realism_issue_ledger)
      + copy.deepcopy(flatline_issue_ledger)
      + copy.deepcopy(stage_maturity_issue_ledger)
    ),
    iteration=0,
  )
  resolution_summary = _build_resolution_summary_from_issue_ledger(
    before_memo=copy.deepcopy(realism_memo_before_resolution),
    issue_status_records=copy.deepcopy(realism_issue_ledger),
  )
  realism_memo_json = _build_realism_memo_from_issue_ledger(
    before_memo=copy.deepcopy(realism_memo_before_resolution),
    issue_status_records=copy.deepcopy(realism_issue_ledger),
    resolution_summary=copy.deepcopy(resolution_summary),
    iteration=0,
  )
  controller_resolution_state = _build_controller_resolution_state_from_issue_ledger(
    issue_status_records=copy.deepcopy(realism_issue_ledger),
    iteration=0,
    current_finmo_json=copy.deepcopy(final_finmo_json),
  )
  protected_resolved_issue_constraints = _build_strategy_resolved_issue_constraints(
    copy.deepcopy(realism_issue_ledger)
  )
  prior_numeric_feedback = _build_numeric_solver_feedback_payload(
    copy.deepcopy(grid_application_summary if isinstance(grid_application_summary, dict) else {})
  )
  unified_convergence_iterations: List[Dict[str, Any]] = []
  unified_convergence_cycle_count = 0
  unified_convergence_decision: Dict[str, Any] = {}
  unified_convergence_plan: Dict[str, Any] = {}
  unified_convergence_result: Dict[str, Any] = {}
  cash_strategy_review_context: Dict[str, Any] = {}
  cash_strategy_review_decision: Dict[str, Any] = {}
  cash_strategy_second_pass_plan: Dict[str, Any] = {}
  cash_strategy_second_pass_result: Dict[str, Any] = {}
  cash_strategy_effect_summary: Dict[str, Any] = {}
  latest_quality_assessment: Dict[str, Any] = {}
  consecutive_no_progress_cycles = 0
  retry_memory: Dict[str, Any] = {
    "completed_attempt_count": 0,
    "prior_lever_unions": [],
    "prior_target_keys": [],
    "latest_candidate_signature": {},
    "latest_result_signature": {},
    "latest_improvement_summary": {},
    "latest_validation_error": {},
    "recent_validation_errors": [],
    "attempt_records": [],
    "prior_controller_state_summary": {},
    "latest_controller_state_summary": {
      "overall_completion_score_pct": int(_safe_float(controller_resolution_state.get("overall_completion_score_pct")) or 0),
      "overall_completion_grade": str(controller_resolution_state.get("overall_completion_grade") or "").strip() or "D",
      "lowest_quarter_score_pct": int(_safe_float(controller_resolution_state.get("lowest_quarter_score_pct")) or 0),
      "remaining_issue_count": int(_safe_float(controller_resolution_state.get("remaining_issue_count")) or 0),
      "resolved_issue_count": int(_safe_float(controller_resolution_state.get("resolved_issue_count")) or 0),
      "tolerated_issue_count": int(_safe_float(controller_resolution_state.get("tolerated_issue_count")) or 0),
    },
  }

  def _rebuild_unified_context() -> Tuple[Dict[str, Any], Dict[str, Any]]:
    next_context = _build_unified_convergence_context_payload(
      draft_id=str(draft_id).strip(),
      business_facts=copy.deepcopy(business_facts or {}),
      ops_json=copy.deepcopy(ops_json or {}),
      financials_json=copy.deepcopy(financials_json or {}),
      planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      prompt_file=prompt_file,
      current_model_input_json=copy.deepcopy(final_model_input_json),
      current_finmo_json=copy.deepcopy(final_finmo_json),
      controller_resolution_state=copy.deepcopy(controller_resolution_state),
      grid_application_summary=copy.deepcopy(grid_application_summary or {}),
      protected_resolved_issue_constraints=copy.deepcopy(protected_resolved_issue_constraints),
      prior_numeric_feedback=copy.deepcopy(prior_numeric_feedback),
      stage_ramp_contract=copy.deepcopy(stage_ramp_contract),
    )
    next_hard_rules = (
      next_context.get("hard_rule_assessment")
      if isinstance(next_context.get("hard_rule_assessment"), dict)
      else {}
    )
    next_context["cycle_stall_assessment"] = _build_unified_cycle_stall_assessment(
      consecutive_no_progress_cycles=consecutive_no_progress_cycles,
      latest_quality_assessment=latest_quality_assessment,
    )
    return next_context, copy.deepcopy(next_hard_rules)

  unified_convergence_context, hard_rule_assessment = _rebuild_unified_context()
  _persist_unified_convergence_state(
    conn=conn,
    draft_id=str(draft_id).strip(),
    stage="convergence_running",
    status="running",
    planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
    controller_resolution_state=copy.deepcopy(controller_resolution_state),
    resolution_summary=copy.deepcopy(resolution_summary),
    planning_mode=planning_mode,
    planning_mode_reason=planning_mode_reason,
    prompt_file=prompt_file,
    grid_application_summary=copy.deepcopy(grid_application_summary or {}),
    realism_memo_before_resolution=copy.deepcopy(realism_memo_before_resolution),
    realism_memo_json=copy.deepcopy(realism_memo_json),
    unified_convergence_context=copy.deepcopy(unified_convergence_context),
    unified_convergence_decision={},
    unified_convergence_plan={},
    unified_convergence_result={},
    unified_convergence_iterations=[],
    unified_convergence_cycle_count=0,
    model_input_json=copy.deepcopy(final_model_input_json),
    finmo_json=copy.deepcopy(final_finmo_json),
  )
  _maybe_interrupt_planning_run(
    conn=conn,
    draft_id=str(draft_id).strip(),
    planning_run_id=active_planning_run_id,
    stage="convergence_running",
    planning_status="running",
    model_input_json=copy.deepcopy(final_model_input_json),
    finmo_json=copy.deepcopy(final_finmo_json),
    realism_memo_json=copy.deepcopy(realism_memo_json),
    event_summary="convergence:stage_gate",
  )

  while (
    not bool(controller_resolution_state.get("all_cleared"))
    or not bool(hard_rule_assessment.get("all_hard_rules_cleared"))
  ):
    if (
      bool(controller_resolution_state.get("all_cleared"))
      and _hard_rules_can_defer_to_cash_strategy(hard_rule_assessment)
    ):
      break
    unified_convergence_cycle_count += 1
    if unified_convergence_cycle_count > _UNIFIED_CONVERGENCE_MAX_CYCLES:
      raise RuntimeError("unified_convergence_unresolved_after_max_cycles")
    cycle_started_at = time.perf_counter()
    cycle_deadline = cycle_started_at + float(_UNIFIED_CONVERGENCE_CYCLE_TIMEOUT_SECONDS)
    cycle_timing: Dict[str, Any] = {
      "cycle": int(unified_convergence_cycle_count),
      "cycle_wall_clock_timeout_seconds": float(_UNIFIED_CONVERGENCE_CYCLE_TIMEOUT_SECONDS),
      "cycle_timing_policy": "fail_if_total_cycle_elapsed_exceeds_180_seconds",
      "started_at_monotonic": float(cycle_started_at),
      "deadline_monotonic": float(cycle_deadline),
      "phase_timings": [],
    }
    phase_started_at = cycle_started_at
    previous_cycle_openai_deadline = _set_active_openai_deadline(cycle_deadline)

    baseline_model_input_json = copy.deepcopy(final_model_input_json)
    baseline_finmo_json = copy.deepcopy(final_finmo_json)
    baseline_issue_ledger = copy.deepcopy(realism_issue_ledger)
    baseline_controller_resolution_state = copy.deepcopy(controller_resolution_state)
    baseline_realism_memo_json = copy.deepcopy(realism_memo_json)
    baseline_resolution_summary = copy.deepcopy(resolution_summary)
    hard_rule_assessment_before = copy.deepcopy(hard_rule_assessment)
    stall_assessment = _build_unified_cycle_stall_assessment(
      consecutive_no_progress_cycles=consecutive_no_progress_cycles,
      latest_quality_assessment=latest_quality_assessment,
    )
    retry_focus_packet = _build_convergence_retry_focus_packet(
      attempt_number=unified_convergence_cycle_count,
      controller_resolution_state=copy.deepcopy(controller_resolution_state),
      latest_quality_assessment=copy.deepcopy(latest_quality_assessment),
      stall_assessment=copy.deepcopy(stall_assessment),
      retry_memory=copy.deepcopy(retry_memory),
      numeric_solver_contract=copy.deepcopy((unified_convergence_context or {}).get("numeric_solver_contract") or {}),
      prior_numeric_feedback=copy.deepcopy(prior_numeric_feedback),
    )
    controller_retry_context = _build_pass_retry_context(
      pass_name="unified_convergence",
      pass_label="Unified Convergence",
      attempt_number=unified_convergence_cycle_count,
      max_attempts=_UNIFIED_CONVERGENCE_MAX_CYCLES,
      retry_memory=copy.deepcopy(retry_memory),
      numeric_solver_contract=copy.deepcopy((unified_convergence_context or {}).get("numeric_solver_contract") or {}),
    )
    controller_retry_context.update(copy.deepcopy(stall_assessment))
    controller_retry_context["issues_remaining"] = int(_safe_float(controller_resolution_state.get("remaining_issue_count")) or 0)
    controller_retry_context["failed_quarters"] = copy.deepcopy(
      (
        (prior_numeric_feedback.get("target_verification") if isinstance(prior_numeric_feedback.get("target_verification"), dict) else {})
        .get("quarters_failed")
        or []
      )
    )
    controller_retry_context["failed_metrics"] = copy.deepcopy(
      (
        (prior_numeric_feedback.get("quarter_fit_summary") or [])
        if isinstance(prior_numeric_feedback, dict)
        else []
      )
    )
    controller_retry_context["previous_levers_used"] = copy.deepcopy(
      (retry_memory.get("latest_candidate_signature") or {}).get("lever_set_union") or []
    )
    controller_retry_context["focus_issue_codes"] = copy.deepcopy(
      retry_focus_packet.get("focus_issue_codes")
      or retry_focus_packet.get("required_open_issue_codes")
      or []
    )
    controller_retry_context["focus_quarters"] = copy.deepcopy(
      retry_focus_packet.get("focus_quarters")
      or retry_focus_packet.get("required_failed_quarters")
      or []
    )
    controller_retry_context["progress_status"] = str(
      retry_focus_packet.get("progress_status")
      or (
        "regressed" if bool(latest_quality_assessment.get("worsened_without_compensating_improvement"))
        else "stalled" if bool(stall_assessment.get("stalled"))
        else "initial" if unified_convergence_cycle_count == 1
        else "improved"
      )
    ).strip()
    previous_controller_summary = (
      retry_memory.get("prior_controller_state_summary")
      if isinstance(retry_memory.get("prior_controller_state_summary"), dict)
      else {}
    )
    latest_controller_summary = (
      retry_memory.get("latest_controller_state_summary")
      if isinstance(retry_memory.get("latest_controller_state_summary"), dict)
      else {}
    )
    controller_retry_context["previous_overall_completion_score_pct"] = _safe_float(
      previous_controller_summary.get("overall_completion_score_pct")
    )
    controller_retry_context["previous_overall_completion_grade"] = str(
      previous_controller_summary.get("overall_completion_grade") or ""
    ).strip()
    controller_retry_context["latest_overall_completion_score_pct"] = int(
      _safe_float(latest_controller_summary.get("overall_completion_score_pct")) or 0
    )
    controller_retry_context["latest_overall_completion_grade"] = str(
      latest_controller_summary.get("overall_completion_grade") or ""
    ).strip() or "D"
    controller_retry_context["last_failure_reason"] = str(
      retry_focus_packet.get("last_failure_reason")
      or (retry_memory.get("latest_validation_error") or {}).get("reason")
      or ("post_execution_regression_or_no_progress" if bool(latest_quality_assessment.get("reject_attempt")) else "")
    ).strip()
    controller_retry_context["constraints"] = list(
      dict.fromkeys(
        [
      "remaining_issue_count must converge to zero",
      "accounting must hold",
      "hard rules must hold",
      "use only authorized levers",
      "quarter target coverage must satisfy the deterministic solver contract for this cycle's focused required_target_quarters",
          *copy.deepcopy(retry_focus_packet.get("constraints") or []),
        ]
      )
    )
    controller_retry_context["required_open_issue_codes"] = copy.deepcopy(
      retry_focus_packet.get("required_open_issue_codes") or []
    )
    controller_retry_context["required_primary_metric_candidates"] = copy.deepcopy(
      retry_focus_packet.get("required_primary_metric_candidates") or []
    )
    controller_retry_context["required_issue_lever_ids"] = copy.deepcopy(
      retry_focus_packet.get("required_issue_lever_ids") or []
    )
    controller_retry_context["minimum_primary_metric_coverage_count"] = int(
      _safe_float(retry_focus_packet.get("minimum_primary_metric_coverage_count")) or 0
    )
    controller_retry_context["issue_coverage_requirements"] = copy.deepcopy(
      retry_focus_packet.get("issue_coverage_requirements") or []
    )
    planner_snapshot = {
      "attempt_number": unified_convergence_cycle_count,
      "attempt_stage": _controller_retry_stage_for_attempt(unified_convergence_cycle_count),
      "status": "planner_running",
      "decision": copy.deepcopy(unified_convergence_decision),
      "plan": copy.deepcopy(unified_convergence_plan),
      "result": copy.deepcopy(unified_convergence_result),
      "retry_memory": _compact_retry_memory_snapshot(retry_memory),
      "working_model_input_json": copy.deepcopy(final_model_input_json),
      "working_finmo_json": copy.deepcopy(final_finmo_json),
      "controller_retry_context": copy.deepcopy(controller_retry_context),
      "candidate_signature": {},
      "validation_error": None,
    }
    _persist_unified_convergence_state(
      conn=conn,
      draft_id=str(draft_id).strip(),
      stage="convergence_running",
      status="running",
      planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
      controller_resolution_state=copy.deepcopy(controller_resolution_state),
      resolution_summary=copy.deepcopy(resolution_summary),
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      prompt_file=prompt_file,
      grid_application_summary=copy.deepcopy(grid_application_summary or {}),
      realism_memo_before_resolution=copy.deepcopy(realism_memo_before_resolution),
      realism_memo_json=copy.deepcopy(realism_memo_json),
      unified_convergence_context=copy.deepcopy(unified_convergence_context),
      unified_convergence_decision=copy.deepcopy(unified_convergence_decision),
      unified_convergence_plan=copy.deepcopy(unified_convergence_plan),
      unified_convergence_result=copy.deepcopy(unified_convergence_result),
      unified_convergence_iterations=copy.deepcopy(unified_convergence_iterations),
      unified_convergence_cycle_count=unified_convergence_cycle_count,
      model_input_json=copy.deepcopy(final_model_input_json),
      finmo_json=copy.deepcopy(final_finmo_json),
      controller_retry_heartbeat=_controller_retry_heartbeat_from_snapshot(planner_snapshot),
    )
    _maybe_interrupt_planning_run(
      conn=conn,
      draft_id=str(draft_id).strip(),
      planning_run_id=active_planning_run_id,
      stage="convergence_running",
      planning_status="running",
      model_input_json=copy.deepcopy(final_model_input_json),
      finmo_json=copy.deepcopy(final_finmo_json),
      realism_memo_json=copy.deepcopy(realism_memo_json),
      event_summary=f"convergence:cycle_{unified_convergence_cycle_count}_planner_gate",
    )
    _mark_unified_convergence_cycle_phase(
      cycle_timing=cycle_timing,
      cycle_started_at=cycle_started_at,
      phase_name="contract_build_and_planner_gate",
      phase_started_at=phase_started_at,
      detail="Built retry context, persisted planner heartbeat, and prepared planner call.",
    )
    _raise_unified_convergence_cycle_timeout_if_needed(
      cycle=unified_convergence_cycle_count,
      cycle_started_at=cycle_started_at,
      stage="contract_build_and_planner_gate",
      cycle_timing=cycle_timing,
    )

    phase_started_at = time.perf_counter()
    previous_openai_deadline = _set_active_openai_deadline(cycle_deadline)
    try:
      unified_convergence_decision = _run_unified_convergence_openai(
        draft_id=str(draft_id).strip(),
        planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
        planning_mode=planning_mode,
        planning_mode_reason=planning_mode_reason,
        planning_mode_prompt_file=prompt_file,
        unified_convergence_context=copy.deepcopy(unified_convergence_context),
        prior_numeric_feedback=copy.deepcopy(prior_numeric_feedback),
        controller_retry_context=copy.deepcopy(controller_retry_context),
      )
    finally:
      _set_active_openai_deadline(previous_openai_deadline)
    _mark_unified_convergence_cycle_phase(
      cycle_timing=cycle_timing,
      cycle_started_at=cycle_started_at,
      phase_name="planner_gpt_and_contract_validation",
      phase_started_at=phase_started_at,
      detail=str((unified_convergence_decision or {}).get("status") or "").strip(),
    )
    cycle_timing["planner_elapsed_seconds"] = round(time.perf_counter() - cycle_started_at, 3)
    _raise_unified_convergence_cycle_timeout_if_needed(
      cycle=unified_convergence_cycle_count,
      cycle_started_at=cycle_started_at,
      stage="planner",
      detail=str((unified_convergence_decision or {}).get("detail") or "").strip(),
      cycle_timing=cycle_timing,
    )
    phase_started_at = time.perf_counter()
    cycle_numeric_guidance_packet = _build_unified_numeric_guidance_packet(
      controller_resolution_state=copy.deepcopy(baseline_controller_resolution_state),
      controller_retry_context=copy.deepcopy(controller_retry_context),
      unified_convergence_context=copy.deepcopy(unified_convergence_context),
      quarter_count=max(
        _CONVERGENCE_DEFAULT_QUARTER_COUNT,
        len((((unified_convergence_context or {}).get("current_finmo_json") or {}) if isinstance((unified_convergence_context or {}).get("current_finmo_json"), dict) else {}).get("quarter_rows") or []),
      ),
    )
    previous_openai_deadline = _set_active_openai_deadline(cycle_deadline)
    try:
      _raise_unified_convergence_cycle_timeout_if_needed(
        cycle=unified_convergence_cycle_count,
        cycle_started_at=cycle_started_at,
        stage="plan_builder_start",
        cycle_timing=cycle_timing,
      )
      unified_convergence_plan = _build_unified_convergence_pass_plan(
        draft_id=str(draft_id).strip(),
        business_facts=copy.deepcopy(business_facts or {}),
        planning_mode=planning_mode,
        planning_mode_reason=planning_mode_reason,
        review_decision_payload=copy.deepcopy(unified_convergence_decision),
        solved_model_input_json=copy.deepcopy(final_model_input_json),
        solved_finmo_json=copy.deepcopy(final_finmo_json),
        ops_json=copy.deepcopy(ops_json or {}),
        people_json=copy.deepcopy(people_json or {}),
        financials_json=copy.deepcopy(financials_json or {}),
        financials_year1_json=copy.deepcopy(financials_year1_json or {}),
        marketing_model_json=copy.deepcopy(marketing_model_json or {}),
        numeric_solver_contract=copy.deepcopy((unified_convergence_context or {}).get("numeric_solver_contract") or {}),
        deterministic_numeric_guidance=copy.deepcopy(cycle_numeric_guidance_packet),
        stage_ramp_contract=copy.deepcopy(stage_ramp_contract),
      )
    finally:
      _set_active_openai_deadline(previous_openai_deadline)
    _mark_unified_convergence_cycle_phase(
      cycle_timing=cycle_timing,
      cycle_started_at=cycle_started_at,
      phase_name="plan_builder_and_presolver_validation",
      phase_started_at=phase_started_at,
      detail=str((unified_convergence_plan or {}).get("status") or "").strip(),
    )
    cycle_timing["plan_builder_elapsed_seconds"] = round(time.perf_counter() - cycle_started_at, 3)
    _raise_unified_convergence_cycle_timeout_if_needed(
      cycle=unified_convergence_cycle_count,
      cycle_started_at=cycle_started_at,
      stage="plan_builder",
      detail=str((unified_convergence_plan or {}).get("next_step") or "").strip(),
      cycle_timing=cycle_timing,
    )
    decision_status = str((unified_convergence_decision or {}).get("status") or "").strip()
    plan_status = str((unified_convergence_plan or {}).get("status") or "").strip()
    plan_solver_contract = (
      unified_convergence_plan.get("numeric_solver_contract")
      if isinstance(unified_convergence_plan.get("numeric_solver_contract"), dict)
      else {}
    )
    plan_active_issue_count = int(_safe_float(plan_solver_contract.get("active_issue_count")) or 0)
    candidate_signature = _extract_pass_retry_candidate_signature(unified_convergence_plan)
    validation_error = None
    if decision_status and decision_status != "completed":
      planner_detail = str((unified_convergence_decision or {}).get("detail") or "").strip()
      validation_error = {
        "rejected": True,
        "reason_code": "planner_not_completed",
        "reason": (
          f"Unified convergence planner did not complete successfully: {decision_status}."
          + (f" Detail: {planner_detail}" if planner_detail else "")
        ),
      }
    elif plan_status == "skipped_review_not_completed" and plan_active_issue_count > 0:
      validation_error = {
        "rejected": True,
        "reason_code": "broken_contract_shape",
        "reason": "Planner review did not complete, so target-driven execution cannot start for an active-issue cycle.",
      }
    elif plan_status != "ready" and plan_active_issue_count > 0:
      validation_error = {
        "rejected": True,
        "reason_code": "broken_contract_shape",
        "reason": (
          "Planner did not provide a valid authorized target-and-lever contract for the active-issue cycle. "
          "Unified convergence now requires explicit GPT-authored solver-ready lever controls."
        ),
      }

    if validation_error:
      diagnostics = _pre_solver_validation_failure_diagnostics(
        unified_convergence_plan=copy.deepcopy(unified_convergence_plan),
        validation_error=copy.deepcopy(validation_error),
      )
      diagnostics["solver_invoked"] = False
      diagnostics["cycle"] = int(unified_convergence_cycle_count)
      diagnostics["planner_plan_status"] = str(plan_status or "").strip() or None
      diagnostics["validation_error"] = copy.deepcopy(validation_error)
      diagnostics["timing"] = {
        **copy.deepcopy(cycle_timing),
        "total_elapsed_seconds": round(time.perf_counter() - cycle_started_at, 3),
      }
      critical_payroll_fail_flags = {
        str(item).strip()
        for item in (
          (
            (diagnostics.get("pre_solver_validation") if isinstance(diagnostics.get("pre_solver_validation"), dict) else {})
            .get("flags")
            or []
          )
        )
        if str(item).strip()
      } & _PAYROLL_DERIVATION_TEST_MODE_FAIL_FLAGS
      if _convergence_test_mode_enabled() and critical_payroll_fail_flags:
        raise StructuredSystemRunFailure(
          detail=_structured_system_run_failure_detail(
            diagnostics=diagnostics,
            fallback="payroll_validation_failed",
          ),
          diagnostics=copy.deepcopy(diagnostics),
        )
      if _convergence_test_mode_enabled():
        raise StructuredSystemRunFailure(
          detail=_structured_system_run_failure_detail(
            diagnostics=diagnostics,
            fallback="solver_not_invoked",
          ),
          diagnostics=copy.deepcopy(diagnostics),
        )
      non_productive_tracker = _update_non_productive_cycle_tracker(
        retry_memory=retry_memory,
        diagnostics=diagnostics,
        controller_resolution_state=baseline_controller_resolution_state,
      )
      progress_failure_diagnostics = _build_convergence_progress_failure_diagnostics(
        cycles_attempted=unified_convergence_cycle_count,
        last_known_state=non_productive_tracker.get("last_known_state"),
        repeated_failure_pattern=non_productive_tracker.get("repeated_failure_pattern"),
        planner_plan_status=plan_status,
      )
      diagnostics["non_productive_cycle_tracker"] = copy.deepcopy(non_productive_tracker)
      progress_failure_diagnostics["validation_error"] = copy.deepcopy(validation_error)
      progress_failure_diagnostics["pre_solver_validation"] = copy.deepcopy(
        diagnostics.get("pre_solver_validation") or {}
      )
      retry_memory["latest_validation_error"] = copy.deepcopy(validation_error)
      retry_memory["recent_validation_errors"] = _bounded_tail(
        list(retry_memory.get("recent_validation_errors") or []) + [
        {
          "attempt_number": unified_convergence_cycle_count,
          "attempt_stage": _controller_retry_stage_for_attempt(unified_convergence_cycle_count),
          "reason_code": str(validation_error.get("reason_code") or "").strip(),
          "reason": str(validation_error.get("reason") or "").strip(),
        }
      ],
        _RETRY_MEMORY_MAX_VALIDATION_ERRORS,
      )
      if (
        _convergence_test_mode_enabled()
        and bool(non_productive_tracker.get("repeated_same_pattern"))
        and isinstance((diagnostics.get("pre_solver_validation") or {}), dict)
        and (
          (diagnostics.get("pre_solver_validation") or {}).get("errors")
          or (diagnostics.get("pre_solver_validation") or {}).get("flags")
        )
      ):
        raise StructuredSystemRunFailure(
          detail="no_meaningful_progress",
          diagnostics=progress_failure_diagnostics,
        )
      if (
        _convergence_test_mode_enabled()
        and int(_safe_float(non_productive_tracker.get("consecutive_non_productive_cycles")) or 0)
        >= _CONVERGENCE_NON_PRODUCTIVE_CYCLE_LIMIT
      ):
        raise StructuredSystemRunFailure(
          detail="no_meaningful_progress",
          diagnostics=progress_failure_diagnostics,
        )
      retry_memory["attempt_records"] = _bounded_tail(
        list(retry_memory.get("attempt_records") or []) + [
        {
          "attempt_number": unified_convergence_cycle_count,
          "attempt_stage": _controller_retry_stage_for_attempt(unified_convergence_cycle_count),
          "status": "rejected_before_solver",
          "controller_retry_context": copy.deepcopy(controller_retry_context),
          "candidate_signature": copy.deepcopy(candidate_signature),
          "rejection": copy.deepcopy(validation_error),
        }
      ],
        _RETRY_MEMORY_MAX_ATTEMPT_RECORDS,
      )
      unified_convergence_result = {
        "contract_version": "unified_convergence_result_v1",
        "status": "retry_rejected_before_solver",
        "target_verification": {
          "controller_state": "retry_required",
          "controller_reason": str(validation_error.get("reason") or "").strip(),
        },
      }
      latest_quality_assessment = {
        "accepted": False,
        "reject_attempt": True,
        "no_progress": True,
      }
      consecutive_no_progress_cycles += 1
      cycle_timing["total_elapsed_seconds"] = round(time.perf_counter() - cycle_started_at, 3)
      unified_convergence_context, hard_rule_assessment = _rebuild_unified_context()
      unified_convergence_iterations.append(
        {
          "cycle": unified_convergence_cycle_count,
          "accepted": False,
          "cycle_timing": copy.deepcopy(cycle_timing),
          "decision": copy.deepcopy(unified_convergence_decision),
          "plan": copy.deepcopy(unified_convergence_plan),
          "result": copy.deepcopy(unified_convergence_result),
          "retry_memory": _compact_retry_memory_snapshot(retry_memory),
          "validation_error": copy.deepcopy(validation_error),
          "controller_resolution_state_before": copy.deepcopy(baseline_controller_resolution_state),
          "controller_resolution_state_after": copy.deepcopy(controller_resolution_state),
        }
      )
      _persist_unified_convergence_state(
        conn=conn,
        draft_id=str(draft_id).strip(),
        stage="convergence_running",
        status="running",
        planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
        controller_resolution_state=copy.deepcopy(controller_resolution_state),
        resolution_summary=copy.deepcopy(resolution_summary),
        planning_mode=planning_mode,
        planning_mode_reason=planning_mode_reason,
        prompt_file=prompt_file,
        grid_application_summary=copy.deepcopy(grid_application_summary or {}),
        realism_memo_before_resolution=copy.deepcopy(realism_memo_before_resolution),
        realism_memo_json=copy.deepcopy(realism_memo_json),
        unified_convergence_context=copy.deepcopy(unified_convergence_context),
        unified_convergence_decision=copy.deepcopy(unified_convergence_decision),
        unified_convergence_plan=copy.deepcopy(unified_convergence_plan),
        unified_convergence_result=copy.deepcopy(unified_convergence_result),
        unified_convergence_iterations=copy.deepcopy(unified_convergence_iterations),
        unified_convergence_cycle_count=unified_convergence_cycle_count,
        model_input_json=copy.deepcopy(final_model_input_json),
        finmo_json=copy.deepcopy(final_finmo_json),
      )
      _set_active_openai_deadline(previous_cycle_openai_deadline)
      continue

    _reset_non_productive_cycle_tracker(retry_memory)
    phase_started_at = time.perf_counter()
    unified_convergence_result = _apply_followup_exact_updates(
      review_plan=copy.deepcopy(unified_convergence_plan),
      current_model_input_json=copy.deepcopy(final_model_input_json),
      contract_version="unified_convergence_result_v1",
      solver_deadline_monotonic=cycle_deadline,
    )
    _mark_unified_convergence_cycle_phase(
      cycle_timing=cycle_timing,
      cycle_started_at=cycle_started_at,
      phase_name="apply_model_input_and_rebuild_finmo",
      phase_started_at=phase_started_at,
      detail=str((unified_convergence_result or {}).get("status") or "").strip(),
    )
    cycle_timing["solver_application_elapsed_seconds"] = round(time.perf_counter() - cycle_started_at, 3)
    _raise_unified_convergence_cycle_timeout_if_needed(
      cycle=unified_convergence_cycle_count,
      cycle_started_at=cycle_started_at,
      stage="solver_application",
      detail=str((unified_convergence_result or {}).get("status") or "").strip(),
      cycle_timing=cycle_timing,
    )
    result_signature = _extract_result_retry_signature(unified_convergence_result)
    previous_result_signature = (
      retry_memory.get("latest_result_signature")
      if isinstance(retry_memory.get("latest_result_signature"), dict)
      else {}
    )
    improvement_summary = _evaluate_retry_improvement(
      previous_result_signature=copy.deepcopy(previous_result_signature),
      current_result_signature=copy.deepcopy(result_signature),
    )
    retry_memory["completed_attempt_count"] = int(unified_convergence_cycle_count)
    retry_memory["prior_lever_unions"] = _bounded_tail(
      list(retry_memory.get("prior_lever_unions") or []) + [
        copy.deepcopy(candidate_signature.get("lever_set_union") or [])
      ],
      _RETRY_MEMORY_MAX_PRIOR_LEVER_UNIONS,
    )
    retry_memory["prior_target_keys"] = _bounded_tail(
      list(retry_memory.get("prior_target_keys") or []) + [
        str(candidate_signature.get("quarter_target_key") or "")
      ],
      _RETRY_MEMORY_MAX_PRIOR_TARGET_KEYS,
    )
    retry_memory["latest_candidate_signature"] = copy.deepcopy(candidate_signature)
    retry_memory["latest_result_signature"] = copy.deepcopy(result_signature)
    retry_memory["latest_improvement_summary"] = copy.deepcopy(improvement_summary)
    retry_memory["latest_validation_error"] = {}
    retry_memory["attempt_records"] = _bounded_tail(
      list(retry_memory.get("attempt_records") or []) + [
      {
        "attempt_number": unified_convergence_cycle_count,
        "attempt_stage": _controller_retry_stage_for_attempt(unified_convergence_cycle_count),
        "status": str(unified_convergence_result.get("status") or "").strip(),
        "controller_retry_context": copy.deepcopy(controller_retry_context),
        "candidate_signature": copy.deepcopy(candidate_signature),
        "result_signature": copy.deepcopy(result_signature),
        "improvement_summary": copy.deepcopy(improvement_summary),
      }
      ],
      _RETRY_MEMORY_MAX_ATTEMPT_RECORDS,
    )
    prior_numeric_feedback = _build_numeric_solver_feedback_payload(copy.deepcopy(unified_convergence_result))
    final_model_input_json = _model_input_with_controller_catalog(
      model_input_json=copy.deepcopy(unified_convergence_result.get("updated_model_input_json") or {}),
      catalog_source_model_input_json=copy.deepcopy(catalog_source_model_input_json or {}),
    )
    final_finmo_json = copy.deepcopy(unified_convergence_result.get("updated_finmo_json") or {})

    post_solver_business_world_contract = _business_world_contract(
      business_facts=copy.deepcopy(business_facts or {}),
      ops_json=copy.deepcopy(ops_json or {}),
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      stage_ramp_contract=copy.deepcopy(stage_ramp_contract)
      if isinstance(stage_ramp_contract, dict)
      else None,
    )
    post_solver_payroll_validation = _validate_payroll_derivation_contract(
      model_input_json=copy.deepcopy(final_model_input_json or {}),
      business_world_contract=copy.deepcopy(post_solver_business_world_contract),
    )
    post_solver_payroll_errors = [
      copy.deepcopy(item)
      for item in (post_solver_payroll_validation.get("details") or [])
      if isinstance(item, dict)
    ]
    if post_solver_payroll_errors:
      first_payroll_error = post_solver_payroll_errors[0]
      diagnostics = {
        "failure_stage": "post_solver_validation",
        "failure_reason": str(first_payroll_error.get("error") or "").strip() or "payroll_validation_failed",
        "lever": "expenses::Payroll",
        "solver_invoked": True,
        "cycle": int(unified_convergence_cycle_count),
        "timing": {
          **copy.deepcopy(cycle_timing),
          "total_elapsed_seconds": round(time.perf_counter() - cycle_started_at, 3),
        },
        "validation_context": {
          "convergence_test_mode": _convergence_test_mode_enabled(),
          "planner_plan_status": str(plan_status or "").strip() or None,
          "focus_issue_codes": copy.deepcopy(controller_retry_context.get("focus_issue_codes") or []),
          "lever_selection": copy.deepcopy((unified_convergence_plan or {}).get("lever_selection") or []),
          "payroll_derivation_validation": copy.deepcopy(post_solver_payroll_validation),
          "numeric_solver_result": copy.deepcopy(unified_convergence_result.get("numeric_solver_result") or {}),
          "target_verification": copy.deepcopy(unified_convergence_result.get("target_verification") or {}),
        },
        "pre_solver_validation": {
          "stage": "post_solver_validation",
          "status": "failed",
          "flags": list(
            dict.fromkeys(
              [
                "payroll_derivation_failed",
                *[
                  str(item.get("error") or "").strip()
                  for item in post_solver_payroll_errors
                  if str(item.get("error") or "").strip()
                ],
              ]
            )
          ),
          "errors": copy.deepcopy(post_solver_payroll_errors),
        },
      }
      unified_convergence_result["post_solver_validation"] = copy.deepcopy(diagnostics)
      raise StructuredSystemRunFailure(
        detail=_structured_system_run_failure_detail(
          diagnostics=diagnostics,
          fallback="payroll_validation_failed",
        ),
        diagnostics=diagnostics,
      )

    target_miss_count = int(_safe_float(unified_convergence_result.get("quarters_with_target_misses")) or 0)
    result_status_text = str(unified_convergence_result.get("status") or "").strip().lower()
    if _convergence_test_mode_enabled() and (
      target_miss_count > 0 or "target_miss" in result_status_text
    ):
      diagnostics = {
        "failure_stage": "post_solver_validation",
        "failure_reason": "solver_target_miss_before_verification",
        "solver_invoked": True,
        "cycle": int(unified_convergence_cycle_count),
        "timing": {
          **copy.deepcopy(cycle_timing),
          "total_elapsed_seconds": round(time.perf_counter() - cycle_started_at, 3),
        },
        "validation_error": {
          "rejected": True,
          "reason_code": "solver_target_miss_before_verification",
          "reason": (
            "Numeric solver did not meet the GPT-authored target contract, "
            "so OpenAI verification was skipped to preserve the cycle time invariant."
          ),
        },
        "pre_solver_validation": {
          "stage": "post_solver_validation",
          "status": "failed",
          "flags": ["solver_target_miss_before_verification"],
          "errors": [
            {
              "error": "solver_target_miss_before_verification",
              "reason": "Solver target misses must be fixed before realism verification is invoked.",
              "target_metric_names": copy.deepcopy(unified_convergence_result.get("target_metric_names") or []),
              "targeted_quarters": copy.deepcopy(unified_convergence_result.get("targeted_quarters") or []),
              "quarter_fit_summary": copy.deepcopy(unified_convergence_result.get("quarter_fit_summary") or []),
            }
          ],
        },
        "numeric_solver_result": copy.deepcopy(unified_convergence_result.get("numeric_solver_result") or {}),
        "target_verification": copy.deepcopy(unified_convergence_result.get("target_verification") or {}),
        "result_summary": {
          "status": str(unified_convergence_result.get("status") or "").strip(),
          "quarters_with_target_misses": target_miss_count,
          "quarters_with_all_targets_within_tolerance": int(
            _safe_float(unified_convergence_result.get("quarters_with_all_targets_within_tolerance")) or 0
          ),
          "quarter_fit_summary": copy.deepcopy(unified_convergence_result.get("quarter_fit_summary") or []),
        },
      }
      raise StructuredSystemRunFailure(
        detail=_structured_system_run_failure_detail(
          diagnostics=diagnostics,
          fallback="solver_target_miss_before_verification",
        ),
        diagnostics=diagnostics,
      )

    next_iteration = max(
      1,
      int(_safe_float(baseline_controller_resolution_state.get("last_review_iteration")) or 0) + 1,
    )
    verification_numeric_solver_contract = copy.deepcopy(
      (unified_convergence_decision or {}).get("numeric_solver_contract")
      if isinstance((unified_convergence_decision or {}).get("numeric_solver_contract"), dict)
      else (unified_convergence_plan or {}).get("numeric_solver_contract")
      if isinstance((unified_convergence_plan or {}).get("numeric_solver_contract"), dict)
      else (unified_convergence_context or {}).get("numeric_solver_contract")
      if isinstance((unified_convergence_context or {}).get("numeric_solver_contract"), dict)
      else {}
    )
    verification_issue_packets = _build_issue_packets_from_issue_ledger(
      issue_status_records=copy.deepcopy(baseline_issue_ledger),
      numeric_solver_contract=copy.deepcopy(verification_numeric_solver_contract),
      prior_decision_payload=copy.deepcopy(unified_convergence_decision or {}),
      current_finmo_json=copy.deepcopy(final_finmo_json),
    )
    verification_allowed_issue_keys = [
      _issue_ledger_key(item)
      for item in (baseline_issue_ledger or [])
      if isinstance(item, dict) and _issue_ledger_key(item)
    ]
    realism_pass_consistency_context = _build_realism_pass_consistency_context_payload(
      phase="unified_convergence",
      prior_issue_status_records=copy.deepcopy(baseline_issue_ledger),
      baseline_model_input_json=copy.deepcopy(baseline_model_input_json),
      baseline_finmo_json=copy.deepcopy(baseline_finmo_json),
      result_payload=copy.deepcopy(unified_convergence_result),
    )
    _raise_unified_convergence_stage_budget_if_needed(
      cycle=unified_convergence_cycle_count,
      cycle_started_at=cycle_started_at,
      stage="verification_start",
      minimum_remaining_seconds=45.0,
      detail=str((unified_convergence_result or {}).get("status") or "").strip(),
      cycle_timing=cycle_timing,
    )
    phase_started_at = time.perf_counter()
    previous_openai_deadline = _set_active_openai_deadline(cycle_deadline)
    try:
      unified_convergence_verification = _run_realism_verification_openai(
        draft_id=str(draft_id).strip(),
        business_facts=copy.deepcopy(business_facts or {}),
        ops_json=copy.deepcopy(ops_json or {}),
        planning_mode=planning_mode,
        planning_mode_reason=planning_mode_reason,
        planning_mode_prompt_file=prompt_file,
        protected_resolved_issue_constraints=copy.deepcopy(protected_resolved_issue_constraints),
        realism_pass_consistency_context=copy.deepcopy(realism_pass_consistency_context),
        realism_memo_before_resolution=copy.deepcopy(baseline_realism_memo_json),
        unified_convergence_decision={
          "decision": {
            "issue_packets": copy.deepcopy(verification_issue_packets),
          },
          "deterministic_issue_packets": copy.deepcopy(verification_issue_packets),
        },
        unified_convergence_plan={
          "issue_packets": copy.deepcopy(verification_issue_packets),
          "strategy_class": str((unified_convergence_plan or {}).get("strategy_class") or "").strip(),
          "change_type": str((unified_convergence_plan or {}).get("change_type") or "").strip(),
          "progress_expectation": str((unified_convergence_plan or {}).get("progress_expectation") or "").strip(),
          "strategy_rationale": str((unified_convergence_plan or {}).get("strategy_rationale") or "").strip(),
          "retry_reason": str((unified_convergence_plan or {}).get("retry_reason") or "").strip(),
          "lever_selection": copy.deepcopy((unified_convergence_plan or {}).get("lever_selection") or []),
          "target_tolerances": copy.deepcopy((unified_convergence_plan or {}).get("target_tolerances") or []),
          "targets_by_quarter": copy.deepcopy((unified_convergence_plan or {}).get("targets_by_quarter") or []),
          "translated_action_packages": copy.deepcopy((unified_convergence_plan or {}).get("translated_action_packages") or []),
        },
        unified_convergence_result=copy.deepcopy(unified_convergence_result),
        updated_model_input_json=copy.deepcopy(final_model_input_json),
        updated_finmo_json=copy.deepcopy(final_finmo_json),
      )
    finally:
      _set_active_openai_deadline(previous_openai_deadline)
    _mark_unified_convergence_cycle_phase(
      cycle_timing=cycle_timing,
      cycle_started_at=cycle_started_at,
      phase_name="verification_gpt_and_rescan",
      phase_started_at=phase_started_at,
      detail=str((unified_convergence_verification or {}).get("status") or "").strip(),
    )
    cycle_timing["verification_elapsed_seconds"] = round(time.perf_counter() - cycle_started_at, 3)
    _raise_unified_convergence_cycle_timeout_if_needed(
      cycle=unified_convergence_cycle_count,
      cycle_started_at=cycle_started_at,
      stage="verification",
      detail=str((unified_convergence_verification or {}).get("detail") or "").strip(),
      cycle_timing=cycle_timing,
    )
    unified_convergence_result["verification"] = copy.deepcopy(unified_convergence_verification)
    verification_status = str((unified_convergence_verification or {}).get("status") or "").strip()
    if verification_status == "completed":
      verified_issue_ledger = _apply_realism_verification_to_issue_status_records(
        issue_status_records=copy.deepcopy(baseline_issue_ledger),
        verification_payload=copy.deepcopy(unified_convergence_verification),
        iteration=next_iteration,
        allowed_issue_keys=copy.deepcopy(verification_allowed_issue_keys),
        allow_new_records=False,
      )
      scan_memo = generate_realism_memo_payload_safe(
        ops_json=ops_json,
        financials_json=financials_json,
        solved_model_input_json=copy.deepcopy(final_model_input_json),
        solved_finmo_json=copy.deepcopy(final_finmo_json),
      )
      scan_issue_set = _build_issue_status_records_from_issue_list(
        current_issues=_memo_issue_records(copy.deepcopy(scan_memo), "remaining_issues", "issues"),
        iteration=next_iteration,
      )
      flatline_scan_issue_set = _build_p_and_l_flatline_issue_status_records(
        model_input_json=copy.deepcopy(final_model_input_json),
        finmo_json=copy.deepcopy(final_finmo_json),
        iteration=next_iteration,
      )
      stage_maturity_scan_issue_set = _build_stage_maturity_cost_structure_issue_status_records(
        model_input_json=copy.deepcopy(final_model_input_json),
        finmo_json=copy.deepcopy(final_finmo_json),
        stage_ramp_contract=copy.deepcopy(stage_ramp_contract),
        iteration=next_iteration,
      )
      if flatline_scan_issue_set or stage_maturity_scan_issue_set:
        scan_issue_set = _refresh_issue_status_records_from_scan(
          existing_issue_status_records=[],
          scanned_issue_status_records=(
            copy.deepcopy(scan_issue_set)
            + copy.deepcopy(flatline_scan_issue_set)
            + copy.deepcopy(stage_maturity_scan_issue_set)
          ),
          iteration=next_iteration,
        )
      realism_issue_ledger = _merge_new_scan_detected_issues(
        existing_issue_status_records=copy.deepcopy(verified_issue_ledger),
        scanned_issue_status_records=copy.deepcopy(scan_issue_set),
        iteration=next_iteration,
      )
      resolution_summary = _build_resolution_summary_from_issue_ledger(
        before_memo=copy.deepcopy(scan_memo),
        issue_status_records=copy.deepcopy(realism_issue_ledger),
      )
      realism_memo_json = _build_realism_memo_from_issue_ledger(
        before_memo=copy.deepcopy(scan_memo),
        issue_status_records=copy.deepcopy(realism_issue_ledger),
        resolution_summary=copy.deepcopy(resolution_summary),
        iteration=next_iteration,
      )
      controller_resolution_state = _build_controller_resolution_state_from_issue_ledger(
        issue_status_records=copy.deepcopy(realism_issue_ledger),
        iteration=next_iteration,
        current_finmo_json=copy.deepcopy(final_finmo_json),
      )
      protected_resolved_issue_constraints = _build_strategy_resolved_issue_constraints(
        copy.deepcopy(realism_issue_ledger)
      )
      unified_convergence_context, after_hard_rule_assessment = _rebuild_unified_context()
      quality_assessment = _build_unified_cycle_quality_assessment(
        before_controller_resolution_state=copy.deepcopy(baseline_controller_resolution_state),
        before_hard_rule_assessment=copy.deepcopy(hard_rule_assessment_before),
        after_controller_resolution_state=copy.deepcopy(controller_resolution_state),
        after_hard_rule_assessment=copy.deepcopy(after_hard_rule_assessment),
        before_finmo_json=copy.deepcopy(baseline_finmo_json),
        after_finmo_json=copy.deepcopy(final_finmo_json),
        result_payload=copy.deepcopy(unified_convergence_result),
        before_numeric_guidance_packet=copy.deepcopy(cycle_numeric_guidance_packet),
        candidate_signature=copy.deepcopy(candidate_signature),
        prior_quality_assessment=copy.deepcopy(latest_quality_assessment),
      )
    else:
      after_hard_rule_assessment = copy.deepcopy(hard_rule_assessment_before)
      quality_assessment = {
        "accepted": False,
        "reject_attempt": True,
        "no_progress": True,
        "verification_failed": True,
        "verification_status": verification_status,
        "verification_detail": str((unified_convergence_verification or {}).get("detail") or "").strip(),
        "remaining_issue_count_before": int(_safe_float(baseline_controller_resolution_state.get("remaining_issue_count")) or 0),
        "remaining_issue_count_after": int(_safe_float(baseline_controller_resolution_state.get("remaining_issue_count")) or 0),
        "resolved_issue_count_before": int(_safe_float(baseline_controller_resolution_state.get("resolved_issue_count")) or 0),
        "resolved_issue_count_after": int(_safe_float(baseline_controller_resolution_state.get("resolved_issue_count")) or 0),
        "open_issue_codes_before": copy.deepcopy(
          [
            str(item.get("issue_code") or "").strip().lower()
            for item in (baseline_controller_resolution_state.get("remaining_issues") or [])
            if isinstance(item, dict) and str(item.get("issue_code") or "").strip()
          ]
        ),
        "open_issue_codes_after": copy.deepcopy(
          [
            str(item.get("issue_code") or "").strip().lower()
            for item in (baseline_controller_resolution_state.get("remaining_issues") or [])
            if isinstance(item, dict) and str(item.get("issue_code") or "").strip()
          ]
        ),
      }
    accepted_attempt = bool(quality_assessment.get("accepted"))
    latest_quality_assessment = copy.deepcopy(quality_assessment)
    if accepted_attempt:
      retry_memory["prior_controller_state_summary"] = copy.deepcopy(
        retry_memory.get("latest_controller_state_summary") or {}
      )
      retry_memory["latest_controller_state_summary"] = {
        "overall_completion_score_pct": int(_safe_float(controller_resolution_state.get("overall_completion_score_pct")) or 0),
        "overall_completion_grade": str(controller_resolution_state.get("overall_completion_grade") or "").strip() or "D",
        "lowest_quarter_score_pct": int(_safe_float(controller_resolution_state.get("lowest_quarter_score_pct")) or 0),
        "remaining_issue_count": int(_safe_float(controller_resolution_state.get("remaining_issue_count")) or 0),
        "resolved_issue_count": int(_safe_float(controller_resolution_state.get("resolved_issue_count")) or 0),
        "tolerated_issue_count": int(_safe_float(controller_resolution_state.get("tolerated_issue_count")) or 0),
      }
      hard_rule_assessment = copy.deepcopy(after_hard_rule_assessment)
      if bool(controller_resolution_state.get("all_cleared")) or bool(quality_assessment.get("meaningful_progress")):
        consecutive_no_progress_cycles = 0
      else:
        consecutive_no_progress_cycles += 1
    else:
      final_model_input_json = copy.deepcopy(baseline_model_input_json)
      final_finmo_json = copy.deepcopy(baseline_finmo_json)
      realism_issue_ledger = copy.deepcopy(baseline_issue_ledger)
      controller_resolution_state = copy.deepcopy(baseline_controller_resolution_state)
      realism_memo_json = copy.deepcopy(baseline_realism_memo_json)
      resolution_summary = copy.deepcopy(baseline_resolution_summary)
      unified_convergence_context, hard_rule_assessment = _rebuild_unified_context()
      consecutive_no_progress_cycles += 1
    unified_convergence_context["cycle_stall_assessment"] = _build_unified_cycle_stall_assessment(
      consecutive_no_progress_cycles=consecutive_no_progress_cycles,
      latest_quality_assessment=latest_quality_assessment,
    )
    unified_convergence_iterations.append(
      {
        "cycle": unified_convergence_cycle_count,
        "accepted": accepted_attempt,
        "cycle_timing": {
          **copy.deepcopy(cycle_timing),
          "total_elapsed_seconds": round(time.perf_counter() - cycle_started_at, 3),
        },
        "stall_assessment_before": copy.deepcopy(stall_assessment),
        "quality_assessment": copy.deepcopy(quality_assessment),
        "hard_rule_assessment_before": copy.deepcopy(hard_rule_assessment_before),
        "hard_rule_assessment_after": copy.deepcopy(hard_rule_assessment),
        "decision": copy.deepcopy(unified_convergence_decision),
        "plan": copy.deepcopy(unified_convergence_plan),
        "result": copy.deepcopy(unified_convergence_result),
        "retry_memory": _compact_retry_memory_snapshot(retry_memory),
        "controller_resolution_state_before": copy.deepcopy(baseline_controller_resolution_state),
        "controller_resolution_state_after": copy.deepcopy(controller_resolution_state),
      }
    )
    _persist_unified_convergence_state(
      conn=conn,
      draft_id=str(draft_id).strip(),
      stage="convergence_running",
      status="running",
      planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
      controller_resolution_state=copy.deepcopy(controller_resolution_state),
      resolution_summary=copy.deepcopy(resolution_summary),
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      prompt_file=prompt_file,
      grid_application_summary=copy.deepcopy(grid_application_summary or {}),
      realism_memo_before_resolution=copy.deepcopy(realism_memo_before_resolution),
      realism_memo_json=copy.deepcopy(realism_memo_json),
      unified_convergence_context=copy.deepcopy(unified_convergence_context),
      unified_convergence_decision=copy.deepcopy(unified_convergence_decision),
      unified_convergence_plan=copy.deepcopy(unified_convergence_plan),
      unified_convergence_result=copy.deepcopy(unified_convergence_result),
      unified_convergence_iterations=copy.deepcopy(unified_convergence_iterations),
      unified_convergence_cycle_count=unified_convergence_cycle_count,
      model_input_json=copy.deepcopy(final_model_input_json),
      finmo_json=copy.deepcopy(final_finmo_json),
    )
    if (
      _convergence_test_mode_enabled()
      and int(consecutive_no_progress_cycles or 0) >= _CONVERGENCE_NON_PRODUCTIVE_CYCLE_LIMIT
      and not bool(quality_assessment.get("meaningful_progress"))
      and not bool(controller_resolution_state.get("all_cleared"))
    ):
      raise StructuredSystemRunFailure(
        detail="no_meaningful_progress",
        diagnostics=_build_convergence_progress_failure_diagnostics(
          cycles_attempted=unified_convergence_cycle_count,
          last_known_state={
            "remaining_issue_count": int(_safe_float(controller_resolution_state.get("remaining_issue_count")) or 0),
            "resolved_issue_count": int(_safe_float(controller_resolution_state.get("resolved_issue_count")) or 0),
            "tolerated_issue_count": int(_safe_float(controller_resolution_state.get("tolerated_issue_count")) or 0),
          },
          repeated_failure_pattern={
            "planner_status": plan_status,
            "solver_invoked": bool(unified_convergence_result.get("solver_invoked")),
            "invalid_levers": [],
            "pre_solver_validation_flags": copy.deepcopy(
              (
                (unified_convergence_plan.get("pre_solver_validation") if isinstance(unified_convergence_plan.get("pre_solver_validation"), dict) else {})
                .get("flags")
                or []
              )
            ),
          },
          planner_plan_status=plan_status,
        ),
      )
    _raise_unified_convergence_cycle_timeout_if_needed(
      cycle=unified_convergence_cycle_count,
      cycle_started_at=cycle_started_at,
      stage="cycle_complete",
      detail=str((quality_assessment or {}).get("status") or "").strip(),
      cycle_timing=cycle_timing,
    )
    _set_active_openai_deadline(previous_cycle_openai_deadline)
    _handle_convergence_test_mode_failure(quality_assessment)

  # Convergence-cycle deadlines must not leak into the post-convergence cash
  # phase. Cash has its own validation/fail-fast gates; inheriting the last
  # cycle's nearly expired OpenAI deadline turns a cleared convergence run into
  # a false terminal timeout.
  _set_active_openai_deadline(None)

  pre_cash_model_input_json = copy.deepcopy(final_model_input_json)
  pre_cash_finmo_json = copy.deepcopy(final_finmo_json)
  pre_cash_issue_ledger = copy.deepcopy(realism_issue_ledger)
  pre_cash_resolution_summary = copy.deepcopy(resolution_summary)
  pre_cash_realism_memo_json = copy.deepcopy(realism_memo_json)
  pre_cash_controller_resolution_state = copy.deepcopy(controller_resolution_state)
  pre_cash_hard_rule_assessment = copy.deepcopy(hard_rule_assessment)
  pre_cash_debt_semantics_seed = _apply_cash_pass_short_term_debt_current_portion(
    cash_strategy_result={
      "updated_model_input_json": copy.deepcopy(pre_cash_model_input_json),
      "updated_finmo_json": copy.deepcopy(pre_cash_finmo_json),
      "applied_updates": [],
    }
  )
  pre_cash_model_input_json = copy.deepcopy(
    pre_cash_debt_semantics_seed.get("updated_model_input_json")
    if isinstance(pre_cash_debt_semantics_seed.get("updated_model_input_json"), dict)
    else pre_cash_model_input_json
  )
  pre_cash_finmo_json = copy.deepcopy(
    pre_cash_debt_semantics_seed.get("updated_finmo_json")
    if isinstance(pre_cash_debt_semantics_seed.get("updated_finmo_json"), dict)
    else pre_cash_finmo_json
  )

  def _persist_cash_pass_stage(
    *,
    stage: str,
    status: str = "running",
    cash_controller_resolution_state: Optional[Dict[str, Any]] = None,
    cash_strategy_review_context_payload: Optional[Dict[str, Any]] = None,
    cash_strategy_review_decision_payload: Optional[Dict[str, Any]] = None,
    cash_strategy_second_pass_plan_payload: Optional[Dict[str, Any]] = None,
    cash_strategy_second_pass_result_payload: Optional[Dict[str, Any]] = None,
    model_input_payload: Optional[Dict[str, Any]] = None,
    finmo_payload: Optional[Dict[str, Any]] = None,
  ) -> None:
    _persist_unified_convergence_state(
      conn=conn,
      draft_id=str(draft_id).strip(),
      stage=stage,
      status=status,
      planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
      controller_resolution_state=copy.deepcopy(cash_controller_resolution_state or pre_cash_controller_resolution_state or {}),
      resolution_summary=copy.deepcopy(pre_cash_resolution_summary or {}),
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      prompt_file=prompt_file,
      grid_application_summary=copy.deepcopy(grid_application_summary or {}),
      realism_memo_before_resolution=copy.deepcopy(realism_memo_before_resolution),
      realism_memo_json=copy.deepcopy(pre_cash_realism_memo_json or {}),
      cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context_payload or {}),
      cash_strategy_review_decision=copy.deepcopy(cash_strategy_review_decision_payload or {}),
      cash_strategy_second_pass_plan=copy.deepcopy(cash_strategy_second_pass_plan_payload or {}),
      cash_strategy_second_pass_result=copy.deepcopy(cash_strategy_second_pass_result_payload or {}),
      unified_convergence_context=copy.deepcopy(unified_convergence_context or {}),
      unified_convergence_decision=copy.deepcopy(unified_convergence_decision or {}),
      unified_convergence_plan=copy.deepcopy(unified_convergence_plan or {}),
      unified_convergence_result=copy.deepcopy(unified_convergence_result or {}),
      unified_convergence_iterations=copy.deepcopy(unified_convergence_iterations),
      unified_convergence_cycle_count=unified_convergence_cycle_count,
      model_input_json=copy.deepcopy(model_input_payload or pre_cash_model_input_json or {}),
      finmo_json=copy.deepcopy(finmo_payload or pre_cash_finmo_json or {}),
    )

  cash_strategy_review_context = _build_cash_strategy_review_context_payload(
    draft_id=str(draft_id).strip(),
    business_facts=copy.deepcopy(business_facts or {}),
    ops_json=copy.deepcopy(ops_json or {}),
    financials_json=copy.deepcopy(financials_json or {}),
    planning_mode=planning_mode,
    planning_mode_reason=planning_mode_reason,
    prompt_file=prompt_file,
    solved_model_input_json=copy.deepcopy(pre_cash_model_input_json),
    solved_finmo_json=copy.deepcopy(pre_cash_finmo_json),
    controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
    prior_numeric_feedback=copy.deepcopy(prior_numeric_feedback),
  )
  cash_pass_review_controller_state = _build_cash_pass_controller_resolution_state(
    phase="cash_pass_review_running",
    base_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
    cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context),
  )
  _persist_cash_pass_stage(
    stage="cash_pass_review_running",
    cash_controller_resolution_state=copy.deepcopy(cash_pass_review_controller_state),
    cash_strategy_review_context_payload=copy.deepcopy(cash_strategy_review_context),
  )
  cash_strategy_review_decision = _run_cash_strategy_review_openai(
    draft_id=str(draft_id).strip(),
    business_facts=copy.deepcopy(business_facts or {}),
    ops_json=copy.deepcopy(ops_json or {}),
    financials_json=copy.deepcopy(financials_json or {}),
    planning_mode=planning_mode,
    planning_mode_reason=planning_mode_reason,
    planning_mode_prompt_file=prompt_file,
    first_pass_handoff={},
    cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context),
    solved_model_input_json=copy.deepcopy(pre_cash_model_input_json),
    solved_finmo_json=copy.deepcopy(pre_cash_finmo_json),
    prior_numeric_feedback=copy.deepcopy(prior_numeric_feedback),
    controller_retry_context={},
  )
  cash_review_failure_flags = _cash_strategy_fail_flags_from_review_payload(cash_strategy_review_decision)
  review_payload_with_context = copy.deepcopy(cash_strategy_review_decision)
  review_payload_with_context["cash_strategy_review_context"] = copy.deepcopy(cash_strategy_review_context)
  review_payload_with_context["numeric_solver_contract"] = copy.deepcopy(
    cash_strategy_review_context.get("numeric_solver_contract")
    if isinstance(cash_strategy_review_context.get("numeric_solver_contract"), dict)
    else {}
  )
  if cash_review_failure_flags:
    cash_pass_failed_controller_state = _build_cash_pass_controller_resolution_state(
      phase="cash_pass_failed",
      base_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
      cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context),
      cash_strategy_review_decision=copy.deepcopy(cash_strategy_review_decision),
    )
    _persist_cash_pass_stage(
      stage="cash_pass_failed",
      status="failed",
      cash_controller_resolution_state=copy.deepcopy(cash_pass_failed_controller_state),
      cash_strategy_review_context_payload=copy.deepcopy(cash_strategy_review_context),
      cash_strategy_review_decision_payload=copy.deepcopy(cash_strategy_review_decision),
    )
    _handle_cash_strategy_test_mode_failure(
      _build_cash_strategy_test_failure_payload(
        review_payload=copy.deepcopy(cash_strategy_review_decision),
        before_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
        after_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
        extra_flags=copy.deepcopy(cash_review_failure_flags),
        detail=str(cash_strategy_review_decision.get("detail") or "").strip() or "cash_strategy_review_failed",
      )
    )
  cash_pass_plan_controller_state = _build_cash_pass_controller_resolution_state(
    phase="cash_pass_plan_running",
    base_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
    cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context),
    cash_strategy_review_decision=copy.deepcopy(cash_strategy_review_decision),
  )
  _persist_cash_pass_stage(
    stage="cash_pass_plan_running",
    cash_controller_resolution_state=copy.deepcopy(cash_pass_plan_controller_state),
    cash_strategy_review_context_payload=copy.deepcopy(cash_strategy_review_context),
    cash_strategy_review_decision_payload=copy.deepcopy(cash_strategy_review_decision),
  )
  cash_strategy_second_pass_plan = _build_cash_strategy_second_pass_plan(
    review_decision_payload=copy.deepcopy(review_payload_with_context),
    solved_model_input_json=copy.deepcopy(pre_cash_model_input_json),
    financials_json=copy.deepcopy(financials_json or {}),
    numeric_solver_contract=copy.deepcopy(
      cash_strategy_review_context.get("numeric_solver_contract")
      if isinstance(cash_strategy_review_context.get("numeric_solver_contract"), dict)
      else {}
    ),
  )
  cash_plan_fail_flags = [
    str(item).strip()
    for item in (cash_strategy_second_pass_plan.get("translation_fail_flags") or [])
    if str(item).strip() in _CASH_STRATEGY_TEST_MODE_FAIL_FLAGS
  ]
  if cash_plan_fail_flags:
    cash_pass_failed_controller_state = _build_cash_pass_controller_resolution_state(
      phase="cash_pass_failed",
      base_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
      cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context),
      cash_strategy_review_decision=copy.deepcopy(cash_strategy_review_decision),
      cash_strategy_second_pass_plan=copy.deepcopy(cash_strategy_second_pass_plan),
    )
    _persist_cash_pass_stage(
      stage="cash_pass_failed",
      status="failed",
      cash_controller_resolution_state=copy.deepcopy(cash_pass_failed_controller_state),
      cash_strategy_review_context_payload=copy.deepcopy(cash_strategy_review_context),
      cash_strategy_review_decision_payload=copy.deepcopy(cash_strategy_review_decision),
      cash_strategy_second_pass_plan_payload=copy.deepcopy(cash_strategy_second_pass_plan),
    )
    _handle_cash_strategy_test_mode_failure(
      _build_cash_strategy_test_failure_payload(
        review_payload=copy.deepcopy(cash_strategy_review_decision),
        plan_payload=copy.deepcopy(cash_strategy_second_pass_plan),
        before_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
        after_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
        extra_flags=copy.deepcopy(cash_plan_fail_flags),
        detail="cash_strategy_second_pass_plan_failed",
      )
    )
  cash_pass_application_controller_state = _build_cash_pass_controller_resolution_state(
    phase="cash_pass_application_running",
    base_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
    cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context),
    cash_strategy_review_decision=copy.deepcopy(cash_strategy_review_decision),
    cash_strategy_second_pass_plan=copy.deepcopy(cash_strategy_second_pass_plan),
  )
  _persist_cash_pass_stage(
    stage="cash_pass_application_running",
    cash_controller_resolution_state=copy.deepcopy(cash_pass_application_controller_state),
    cash_strategy_review_context_payload=copy.deepcopy(cash_strategy_review_context),
    cash_strategy_review_decision_payload=copy.deepcopy(cash_strategy_review_decision),
    cash_strategy_second_pass_plan_payload=copy.deepcopy(cash_strategy_second_pass_plan),
  )
  cash_strategy_second_pass_result = _apply_cash_strategy_exact_updates(
    review_plan=copy.deepcopy(cash_strategy_second_pass_plan),
    current_model_input_json=copy.deepcopy(pre_cash_model_input_json),
    current_finmo_json=copy.deepcopy(pre_cash_finmo_json),
  )
  cash_strategy_second_pass_result = _apply_cash_pass_short_term_debt_current_portion(
    cash_strategy_result=copy.deepcopy(cash_strategy_second_pass_result)
  )
  cash_validation_iteration = max(
    int(_safe_float(pre_cash_controller_resolution_state.get("last_review_iteration")) or unified_convergence_cycle_count),
    unified_convergence_cycle_count,
  ) + 1
  cash_post_validation = _validate_cash_strategy_post_pass(
    ops_json=copy.deepcopy(ops_json or {}),
    financials_json=copy.deepcopy(financials_json or {}),
    baseline_issue_ledger=copy.deepcopy(pre_cash_issue_ledger),
    candidate_model_input_json=copy.deepcopy(cash_strategy_second_pass_result.get("updated_model_input_json") or {}),
    candidate_finmo_json=copy.deepcopy(cash_strategy_second_pass_result.get("updated_finmo_json") or {}),
    iteration=cash_validation_iteration,
  )
  cash_strategy_second_pass_result["post_validation"] = copy.deepcopy(cash_post_validation)
  cash_pass_validation_controller_state = _build_cash_pass_controller_resolution_state(
    phase="cash_pass_validation_running",
    base_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
    cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context),
    cash_strategy_review_decision=copy.deepcopy(cash_strategy_review_decision),
    cash_strategy_second_pass_plan=copy.deepcopy(cash_strategy_second_pass_plan),
    cash_strategy_second_pass_result=copy.deepcopy(cash_strategy_second_pass_result),
    cash_post_validation=copy.deepcopy(cash_post_validation),
  )
  _persist_cash_pass_stage(
    stage="cash_pass_validation_running",
    cash_controller_resolution_state=copy.deepcopy(cash_pass_validation_controller_state),
    cash_strategy_review_context_payload=copy.deepcopy(cash_strategy_review_context),
    cash_strategy_review_decision_payload=copy.deepcopy(cash_strategy_review_decision),
    cash_strategy_second_pass_plan_payload=copy.deepcopy(cash_strategy_second_pass_plan),
    cash_strategy_second_pass_result_payload=copy.deepcopy(cash_strategy_second_pass_result),
    model_input_payload=copy.deepcopy(cash_strategy_second_pass_result.get("updated_model_input_json") or pre_cash_model_input_json),
    finmo_payload=copy.deepcopy(cash_strategy_second_pass_result.get("updated_finmo_json") or pre_cash_finmo_json),
  )
  post_validation_fail_flags = [
    str(item).strip()
    for item in (cash_post_validation.get("failed_rule_codes") or [])
    if str(item).strip() in _CASH_STRATEGY_TEST_MODE_FAIL_FLAGS
  ]
  if post_validation_fail_flags:
    cash_strategy_second_pass_result["fail_flags"] = list(
      dict.fromkeys(
        [
          *[
            str(item).strip()
            for item in (cash_strategy_second_pass_result.get("fail_flags") or [])
            if str(item).strip()
          ],
          *post_validation_fail_flags,
        ]
      )
    )
  if bool(cash_post_validation.get("keep_changes")):
    final_model_input_json = _model_input_with_controller_catalog(
      model_input_json=copy.deepcopy(cash_strategy_second_pass_result.get("updated_model_input_json") or {}),
      catalog_source_model_input_json=copy.deepcopy(catalog_source_model_input_json or {}),
    )
    final_finmo_json = copy.deepcopy(cash_strategy_second_pass_result.get("updated_finmo_json") or {})
    realism_issue_ledger = copy.deepcopy(cash_post_validation.get("issue_ledger") or [])
    resolution_summary = copy.deepcopy(cash_post_validation.get("resolution_summary") or {})
    realism_memo_json = copy.deepcopy(cash_post_validation.get("realism_memo_json") or {})
    controller_resolution_state = copy.deepcopy(cash_post_validation.get("controller_resolution_state") or {})
    hard_rule_assessment = copy.deepcopy(cash_post_validation.get("hard_rule_assessment") or {})
  else:
    final_model_input_json = copy.deepcopy(pre_cash_model_input_json)
    final_finmo_json = copy.deepcopy(pre_cash_finmo_json)
    realism_issue_ledger = copy.deepcopy(pre_cash_issue_ledger)
    resolution_summary = copy.deepcopy(pre_cash_resolution_summary)
    realism_memo_json = copy.deepcopy(pre_cash_realism_memo_json)
    controller_resolution_state = copy.deepcopy(pre_cash_controller_resolution_state)
    hard_rule_assessment = copy.deepcopy(pre_cash_hard_rule_assessment)
    cash_strategy_second_pass_result["status"] = "reverted_post_validation"
    cash_strategy_second_pass_result["final_model_source"] = "converged_model_reverted"
  cash_strategy_result_fail_flags = [
    str(item).strip()
    for item in (cash_strategy_second_pass_result.get("fail_flags") or [])
    if str(item).strip() in _CASH_STRATEGY_TEST_MODE_FAIL_FLAGS
  ]
  if cash_strategy_result_fail_flags:
    cash_pass_failed_controller_state = _build_cash_pass_controller_resolution_state(
      phase="cash_pass_failed",
      base_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
      cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context),
      cash_strategy_review_decision=copy.deepcopy(cash_strategy_review_decision),
      cash_strategy_second_pass_plan=copy.deepcopy(cash_strategy_second_pass_plan),
      cash_strategy_second_pass_result=copy.deepcopy(cash_strategy_second_pass_result),
      cash_post_validation=copy.deepcopy(cash_post_validation),
    )
    _persist_cash_pass_stage(
      stage="cash_pass_failed",
      status="failed",
      cash_controller_resolution_state=copy.deepcopy(cash_pass_failed_controller_state),
      cash_strategy_review_context_payload=copy.deepcopy(cash_strategy_review_context),
      cash_strategy_review_decision_payload=copy.deepcopy(cash_strategy_review_decision),
      cash_strategy_second_pass_plan_payload=copy.deepcopy(cash_strategy_second_pass_plan),
      cash_strategy_second_pass_result_payload=copy.deepcopy(cash_strategy_second_pass_result),
      model_input_payload=copy.deepcopy(cash_strategy_second_pass_result.get("updated_model_input_json") or final_model_input_json),
      finmo_payload=copy.deepcopy(cash_strategy_second_pass_result.get("updated_finmo_json") or final_finmo_json),
    )
    _handle_cash_strategy_test_mode_failure(
      _build_cash_strategy_test_failure_payload(
        review_payload=copy.deepcopy(cash_strategy_review_decision),
        plan_payload=copy.deepcopy(cash_strategy_second_pass_plan),
        result_payload=copy.deepcopy(cash_strategy_second_pass_result),
        before_controller_resolution_state=copy.deepcopy(pre_cash_controller_resolution_state),
        after_controller_resolution_state=copy.deepcopy(
          cash_post_validation.get("controller_resolution_state")
          if isinstance(cash_post_validation.get("controller_resolution_state"), dict)
          else pre_cash_controller_resolution_state
        ),
        extra_flags=copy.deepcopy(cash_strategy_result_fail_flags),
        detail="cash_strategy_second_pass_execution_failed",
      )
    )
  try:
    from client_intake_and_finmo.finmo_bridge import build_python_finmo_json  # type: ignore
  except Exception:
    try:
      from finmo_bridge import build_python_finmo_json  # type: ignore
    except Exception as exc:
      raise RuntimeError(
        "post_cash_final_finmo_rebuild_unavailable: final hard gates require a fresh FINMO rebuild from the latest model_input_json."
      ) from exc
  final_finmo_json = build_python_finmo_json(model_input_json=copy.deepcopy(final_model_input_json))
  _raise_cash_pass_unresolved_liquidity_if_needed(
    financials_json=copy.deepcopy(financials_json or {}),
    final_model_input_json=copy.deepcopy(final_model_input_json),
    final_finmo_json=copy.deepcopy(final_finmo_json),
    cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context),
    cash_strategy_review_decision=copy.deepcopy(cash_strategy_review_decision),
    cash_strategy_second_pass_plan=copy.deepcopy(cash_strategy_second_pass_plan),
    cash_strategy_second_pass_result=copy.deepcopy(cash_strategy_second_pass_result),
  )
  _raise_p_and_l_flatline_if_needed(
    final_model_input_json=copy.deepcopy(final_model_input_json),
    final_finmo_json=copy.deepcopy(final_finmo_json),
    stage="post_cash_pass_final",
  )
  cash_strategy_effect_summary = _build_cash_strategy_effect_summary(
    financials_json=copy.deepcopy(financials_json or {}),
    review_decision_payload=copy.deepcopy(cash_strategy_review_decision),
    second_pass_result=copy.deepcopy(cash_strategy_second_pass_result),
    first_pass_finmo_json=copy.deepcopy(pre_cash_finmo_json),
    final_finmo_json=copy.deepcopy(final_finmo_json),
  )

  diagnostics_snapshot = {
    "contract_version": "planning_diagnostics_snapshot_v3",
    "baseline_model_input_json": copy.deepcopy(catalog_source_model_input_json or {}),
    "grid_applied_model_input_json": copy.deepcopy(applied_model_input_json or {}),
    "grid_applied_finmo_json": copy.deepcopy(applied_finmo_json or {}),
    "final_model_input_json": copy.deepcopy(final_model_input_json),
    "final_finmo_json": copy.deepcopy(final_finmo_json),
    "unified_convergence_iterations": copy.deepcopy(unified_convergence_iterations),
    "cash_strategy_review_context": copy.deepcopy(cash_strategy_review_context),
    "cash_strategy_review_decision": copy.deepcopy(cash_strategy_review_decision),
    "cash_strategy_second_pass_plan": copy.deepcopy(cash_strategy_second_pass_plan),
    "cash_strategy_second_pass_result": copy.deepcopy(cash_strategy_second_pass_result),
    "cash_strategy_effect_summary": copy.deepcopy(cash_strategy_effect_summary),
    "cost_telemetry": _openai_call_telemetry_snapshot(),
  }
  next_planning_run_json = _build_planning_run_payload(
    stage="cash_pass_completed",
    status="completed",
    controller_resolution_state=copy.deepcopy(controller_resolution_state),
    resolution_summary=copy.deepcopy(resolution_summary),
    planning_mode=planning_mode,
    planning_mode_reason=planning_mode_reason,
    prompt_file=prompt_file,
    gpt_narrative=str(planning_result.get("gpt_narrative") or "").strip(),
    gpt_grid_metadata=copy.deepcopy(planning_result.get("metadata") or {}),
    grid_application_summary=copy.deepcopy(grid_application_summary or {}),
    realism_memo_before_resolution=copy.deepcopy(realism_memo_before_resolution),
    cash_strategy_review_context=copy.deepcopy(cash_strategy_review_context),
    cash_strategy_review_decision=copy.deepcopy(cash_strategy_review_decision),
    cash_strategy_second_pass_plan=copy.deepcopy(cash_strategy_second_pass_plan),
    cash_strategy_second_pass_result=copy.deepcopy(cash_strategy_second_pass_result),
    cash_strategy_effect_summary=copy.deepcopy(cash_strategy_effect_summary),
    unified_convergence_context=copy.deepcopy(unified_convergence_context),
    unified_convergence_decision=copy.deepcopy(unified_convergence_decision),
    unified_convergence_plan=copy.deepcopy(unified_convergence_plan),
    unified_convergence_result=copy.deepcopy(unified_convergence_result),
    unified_convergence_iterations=copy.deepcopy(unified_convergence_iterations),
    unified_convergence_cycle_count=unified_convergence_cycle_count,
    diagnostics_snapshot=copy.deepcopy(diagnostics_snapshot),
    numeric_solver_contract=build_numeric_solver_contract(
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      selected_cash_strategy=_resolved_cash_strategy(financials_json),
      issue_status_records=_controller_state_issue_status_records(controller_resolution_state),
      writable_lever_catalog=_build_writable_lever_review_catalog(final_model_input_json),
      current_model_input_json=copy.deepcopy(final_model_input_json or {}),
      current_finmo_json=copy.deepcopy(final_finmo_json or {}),
      pass_name="final_system_state",
      contract_scope="planning_run_snapshot",
    ),
  )
  next_planning_run_json["planning_run_id"] = active_planning_run_id
  next_planning_run_json["trigger_type"] = "system_run"
  next_planning_run_json["lifecycle_mode"] = "start"
  persisted_realism_memo = _build_persisted_realism_memo_payload(
    controller_resolution_state=copy.deepcopy(controller_resolution_state),
    working_memo=copy.deepcopy(realism_memo_json),
  )
  financial_story_payload = _build_financial_story_payload(
    business_facts=copy.deepcopy(business_facts or {}),
    ops_json=copy.deepcopy(ops_json or {}),
    target_market_json=copy.deepcopy(target_market_json or {}),
    financials_json=copy.deepcopy(financials_json or {}),
    planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
    current_finmo_json=copy.deepcopy(final_finmo_json or {}),
    controller_resolution_state=copy.deepcopy(controller_resolution_state),
    hard_rule_assessment=copy.deepcopy(hard_rule_assessment),
  )
  persisted_completion = persist_post_intake_execution_state(
    conn,
    draft_id=str(draft_id).strip(),
    new_messages=[],
    operating_model_json=ops_json,
    target_market_json=target_market_json,
    people_json=people_json,
    financials_json=financials_json,
    financials_year1_json=financials_year1_json,
    marketing_model_json=marketing_model_json,
    planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
    realism_memo_json=persisted_realism_memo,
    fulfillment_json=fulfillment_json,
    model_input_json=final_model_input_json,
    finmo_json=final_finmo_json,
    planning_run_json=next_planning_run_json,
    numeric_solver_feedback_json=_extract_numeric_solver_feedback_for_persistence(
      planning_run_payload=next_planning_run_json,
      explicit_candidates=[
        ("unified_convergence_result", unified_convergence_result),
        ("cash_strategy_second_pass_result", cash_strategy_second_pass_result),
      ],
    ),
    financial_story=copy.deepcopy(financial_story_payload),
    active_focus="done",
    business_facts=business_facts,
    status="completed",
    completed=True,
    checkpoint_kind="run_complete",
    event_type="run_completed",
    event_summary="cash_pass_completed:completed",
  )
  if isinstance(persisted_completion, dict) and isinstance(persisted_completion.get("planning_run_json"), dict):
    next_planning_run_json = copy.deepcopy(persisted_completion.get("planning_run_json") or next_planning_run_json)
  return {
    "draft_id": str(draft_id).strip(),
    "planning_context_summary_json": copy.deepcopy(planning_context_summary_json or {}),
    "planning_run_json": next_planning_run_json,
    "planning_runtime_json": (
      copy.deepcopy(persisted_completion.get("planning_runtime_json"))
      if isinstance(persisted_completion, dict) and isinstance(persisted_completion.get("planning_runtime_json"), dict)
      else {}
    ),
    "numeric_solver_feedback_json": _extract_numeric_solver_feedback_for_persistence(
      planning_run_payload=next_planning_run_json,
      explicit_candidates=[
        ("unified_convergence_result", unified_convergence_result),
        ("cash_strategy_second_pass_result", cash_strategy_second_pass_result),
      ],
    ),
    "financial_story": (
      copy.deepcopy(persisted_completion.get("financial_story"))
      if isinstance(persisted_completion, dict) and isinstance(persisted_completion.get("financial_story"), dict)
      else copy.deepcopy(financial_story_payload)
    ),
    "realism_memo_json": persisted_realism_memo,
    "model_input_json": final_model_input_json,
    "finmo_json": final_finmo_json,
  }


def _run_planning_system_for_draft_unified(
  *,
  conn,
  draft_id: str,
  lifecycle_mode: str = "start",
  planning_run_id: Optional[str] = None,
) -> Dict[str, Any]:
  if build_shared_context is None:
    raise RuntimeError("build_shared_context_unavailable")
  draft = get_draft(conn, draft_id=str(draft_id).strip())
  if str(draft.get("active_focus") or "").strip().lower() != "done":
    raise RuntimeError("draft_not_complete")
  _reset_openai_call_telemetry()
  lifecycle_start = begin_planning_run(
    conn,
    draft_id=str(draft_id).strip(),
    trigger_type="system_run",
    lifecycle_mode=str(lifecycle_mode or "start").strip().lower() or "start",
    planning_run_id=planning_run_id,
  )
  active_planning_run = (
    lifecycle_start.get("planning_run")
    if isinstance(lifecycle_start.get("planning_run"), dict)
    else {}
  )
  active_planning_run_id = str(active_planning_run.get("planning_run_id") or "").strip()
  if not active_planning_run_id:
    raise RuntimeError("planning_run_start_failed")

  try:
    from financials_consultant import estimate_marketing_baseline_from_context  # type: ignore
  except Exception:
    from client_intake_and_finmo.financials_consultant import estimate_marketing_baseline_from_context  # type: ignore
  try:
    from financials_year1 import assemble_financials_year1  # type: ignore
  except Exception:
    from client_intake_and_finmo.financials_year1 import assemble_financials_year1  # type: ignore

  ops_json = _parse_json_dict(draft.get("operating_model_json"))
  market_json = _parse_json_dict(draft.get("target_market_json"))
  people_json = _parse_json_dict(draft.get("people_json"))
  financials_json = _parse_json_dict(draft.get("financials_json"))
  financials_year1_json = _parse_json_dict(draft.get("financials_year1_json"))
  fulfillment_json = _parse_json_dict(draft.get("fulfillment_json"))
  marketing_model_json = _parse_json_dict(draft.get("marketing_model_json"))
  planning_context_summary_json = _parse_json_dict(draft.get("planning_context_summary_json"))
  resume_checkpoint = (
    lifecycle_start.get("latest_checkpoint")
    if isinstance(lifecycle_start.get("latest_checkpoint"), dict)
    else {}
  )
  resume_checkpoint_stage = str(resume_checkpoint.get("stage") or "").strip().lower()
  resume_checkpoint_planning_payload = _parse_json_dict(resume_checkpoint.get("planning_run_json"))
  resume_checkpoint_model_input_json = _parse_json_dict(resume_checkpoint.get("model_input_json"))
  resume_checkpoint_finmo_json = _parse_json_dict(resume_checkpoint.get("finmo_json"))
  resume_from_checkpoint_state = bool(
    str(lifecycle_mode or "").strip().lower() == "resume"
    and isinstance(resume_checkpoint_model_input_json, dict)
    and resume_checkpoint_model_input_json
    and isinstance(resume_checkpoint_finmo_json, dict)
    and resume_checkpoint_finmo_json
    and resume_checkpoint_stage not in {"", "system_run_starting", "baseline_ready", "quarter_grid_running", "quarter_grid_ready"}
  )

  business_facts: Dict[str, Any] = {
    "name": draft.get("business_name"),
    "business_name": draft.get("business_name"),
    "address": draft.get("business_address"),
    "start_date": draft.get("business_start_date"),
    "address_street": draft.get("address_street"),
    "address_city": draft.get("address_city"),
    "address_state": draft.get("address_state"),
    "address_zip": draft.get("address_zip"),
    "address_country": draft.get("address_country"),
  }

  def _refresh_planning_context_summary(
    *,
    current_model_input_json: Optional[Dict[str, Any]],
    planning_mode_value: str = "",
    planning_mode_reason_value: str = "",
    prompt_file_value: str = "",
  ) -> Dict[str, Any]:
    return _build_planning_context_summary_payload(
      business_facts=copy.deepcopy(business_facts or {}),
      ops_json=copy.deepcopy(ops_json or {}),
      target_market_json=copy.deepcopy(market_json or {}),
      people_json=copy.deepcopy(people_json or {}),
      financials_json=copy.deepcopy(financials_json or {}),
      financials_year1_json=copy.deepcopy(financials_year1_json or {}),
      marketing_model_json=copy.deepcopy(marketing_model_json or {}),
      model_input_json=copy.deepcopy(current_model_input_json or {}),
      planning_mode=planning_mode_value,
      planning_mode_reason=planning_mode_reason_value,
      prompt_file=prompt_file_value,
    )

  def _persist_system_stage(
    *,
    stage: str,
    status: str,
    planning_mode: str = "",
    planning_mode_reason: str = "",
    prompt_file: str = "",
    gpt_narrative: str = "",
    gpt_grid_metadata: Optional[Dict[str, Any]] = None,
    grid_application_summary: Optional[Dict[str, Any]] = None,
    model_input_payload: Optional[Dict[str, Any]] = None,
    finmo_payload: Optional[Dict[str, Any]] = None,
  ) -> Dict[str, Any]:
    payload = _build_planning_run_payload(
      stage=stage,
      status=status,
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      prompt_file=prompt_file,
      gpt_narrative=gpt_narrative,
      gpt_grid_metadata=copy.deepcopy(gpt_grid_metadata or {}),
      grid_application_summary=copy.deepcopy(grid_application_summary or {}),
    )
    payload["planning_run_id"] = active_planning_run_id
    payload["trigger_type"] = "system_run"
    payload["lifecycle_mode"] = str(lifecycle_mode or "start").strip().lower() or "start"
    persisted = persist_post_intake_execution_state(
      conn,
      draft_id=str(draft_id).strip(),
      new_messages=[],
      planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
      model_input_json=model_input_payload,
      finmo_json=finmo_payload,
      planning_run_json=payload,
      numeric_solver_feedback_json=_extract_numeric_solver_feedback_for_persistence(
        planning_run_payload=payload
      ),
      active_focus="done",
      status="in_progress",
      completed=False,
      checkpoint_kind="stage_snapshot",
      event_type="stage_persisted",
      event_summary=f"{stage}:{status}",
    )
    persisted_payload = (
      persisted.get("planning_run_json")
      if isinstance(persisted, dict) and isinstance(persisted.get("planning_run_json"), dict)
      else payload
    )
    _maybe_interrupt_planning_run(
      conn=conn,
      draft_id=str(draft_id).strip(),
      planning_run_id=active_planning_run_id,
      stage=stage,
      planning_status=status,
      planning_run_json=copy.deepcopy(persisted_payload),
      model_input_json=copy.deepcopy(model_input_payload or {}),
      finmo_json=copy.deepcopy(finmo_payload or {}),
      numeric_solver_feedback_json=_extract_numeric_solver_feedback_for_persistence(
        planning_run_payload=persisted_payload
      ),
      event_summary=f"{stage}:{status}:lifecycle_gate",
    )
    return persisted_payload

  shared_context = build_shared_context(conn, draft_id=str(draft_id).strip())
  shared_context = dict(shared_context or {})
  shared_context["operating_model"] = ops_json
  shared_context["target_market"] = market_json
  shared_context["people_capability"] = people_json
  shared_context["financials"] = financials_json

  base_year1 = assemble_financials_year1(shared_context, None)
  if _year1_drivers_conflict(financials_year1_json, base_year1):
    financials_year1_json = base_year1
  else:
    financials_year1_json = assemble_financials_year1(shared_context, financials_year1_json)
  if isinstance(financials_year1_json, dict) and financials_year1_json:
    shared_context["financials_year1_json"] = financials_year1_json

  try:
    marketing_model_json = _compute_marketing_model_json(
      conn=conn,
      ops_json=ops_json,
      market_json=market_json,
      people_json=people_json,
      financials_year1_json=financials_year1_json,
      business_facts=business_facts,
      existing_marketing_model_json=marketing_model_json,
      estimate_marketing_baseline_from_context=estimate_marketing_baseline_from_context,
    )
  except Exception:
    marketing_model_json = dict(marketing_model_json or {})
  shared_context["marketing"] = marketing_model_json

  forecast_starting_ppe_decision = _estimate_maintenance_capex_percent_with_gpt(
    business_facts=business_facts,
    ops_json=ops_json,
    financials_json=financials_json,
    financials_year1_json=financials_year1_json,
  )
  forecast_starting_ppe = int(round(max(0.0, float(_safe_float((financials_json or {}).get("initial_assets")) or 0.0))))
  maintenance_rate = float(_safe_float(forecast_starting_ppe_decision.get("maintenance_rate")) or 0.0)
  if maintenance_rate < 0.02 or maintenance_rate > 0.15:
    raise RuntimeError(
      f"maintenance_capex_percent_maintenance_rate_invalid: GPT returned invalid maintenance_rate={maintenance_rate!r}; expected 0.02 <= rate <= 0.15."
    )
  shared_context["forecast_starting_ppe_decision"] = {
    "contract_version": forecast_starting_ppe_decision.get("contract_version"),
    "decision_source": forecast_starting_ppe_decision.get("decision_source"),
    "starting_ppe": forecast_starting_ppe,
    "starting_ppe_source": "financials_json.initial_assets_authoritative_balance_sheet",
    "balance_sheet_authoritative": True,
    "maintenance_capex_percent": forecast_starting_ppe_decision.get("maintenance_capex_percent"),
    "maintenance_rate": maintenance_rate,
  }

  try:
    from finmo_bridge import sync_planning_state_to_finmo  # type: ignore
  except Exception:
    from client_intake_and_finmo.finmo_bridge import sync_planning_state_to_finmo  # type: ignore
  try:
    from quarter_grid import determine_planning_mode, generate_live_quarter_grid_plan, apply_live_quarter_grid_plan  # type: ignore
  except Exception:
    from client_intake_and_finmo.quarter_grid import determine_planning_mode, generate_live_quarter_grid_plan, apply_live_quarter_grid_plan  # type: ignore

  sync_result = sync_planning_state_to_finmo(
    finmo_path="",
    business_facts=business_facts,
    ops_json=ops_json,
    people_json=people_json,
    financials_json=financials_json,
    financials_year1_json=financials_year1_json,
    marketing_model_json=marketing_model_json,
    forecast_starting_ppe=forecast_starting_ppe,
    maintenance_rate=maintenance_rate,
    controller_input_seed=[],
    forecast_quarters=[],
    calibration_spec=None,
  )
  if resume_from_checkpoint_state:
    model_input_json = copy.deepcopy(resume_checkpoint_model_input_json)
    catalog_source_model_input_json = copy.deepcopy(model_input_json)
    finmo_json = copy.deepcopy(resume_checkpoint_finmo_json)
    planning_context_summary_json = _refresh_planning_context_summary(
      current_model_input_json=model_input_json,
    )
    _persist_system_stage(
      stage="resume_checkpoint_loaded",
      status="running",
      model_input_payload=model_input_json,
      finmo_payload=finmo_json,
    )
  else:
    model_input_json = (
      sync_result.get("model_input_json")
      if isinstance(sync_result.get("model_input_json"), dict)
      else {}
    )
    catalog_source_model_input_json = copy.deepcopy(model_input_json)
    finmo_json = (
      sync_result.get("finmo_json")
      if isinstance(sync_result.get("finmo_json"), dict)
      else {}
    )
    planning_context_summary_json = _refresh_planning_context_summary(
      current_model_input_json=model_input_json,
    )
    _persist_system_stage(
      stage="baseline_ready",
      status="running",
      model_input_payload=model_input_json,
      finmo_payload=finmo_json,
    )

  planning_choice = determine_planning_mode(
    ops_json=dict(ops_json or {}),
    target_market_json=dict(market_json or {}),
    people_json=dict(people_json or {}),
    financials_json=dict(financials_json or {}),
    financials_year1_json=dict(financials_year1_json or {}),
    fulfillment_json=dict(fulfillment_json or {}),
    marketing_model_json=dict(marketing_model_json or {}),
    model_input_json=copy.deepcopy(model_input_json),
    finmo_json=copy.deepcopy(finmo_json),
    business_facts=copy.deepcopy(business_facts or {}),
  )
  planning_mode = str(planning_choice.get("planning_mode") or "").strip()
  planning_mode_reason = str(planning_choice.get("planning_mode_reason") or "").strip()
  planning_context_summary_json = _refresh_planning_context_summary(
    current_model_input_json=model_input_json,
    planning_mode_value=planning_mode,
    planning_mode_reason_value=planning_mode_reason,
    prompt_file_value=str(planning_choice.get("prompt_file") or "").strip(),
  )
  stage_ramp_contract = _estimate_stage_ramp_contract_with_gpt(
    business_facts=copy.deepcopy(business_facts or {}),
    ops_json=copy.deepcopy(ops_json or {}),
    financials_json=copy.deepcopy(financials_json or {}),
    financials_year1_json=copy.deepcopy(financials_year1_json or {}),
    planning_mode=planning_mode,
    planning_mode_reason=planning_mode_reason,
    model_input_json=copy.deepcopy(model_input_json or {}),
    finmo_json=copy.deepcopy(finmo_json or {}),
  )
  shared_context["stage_ramp_contract_decision"] = {
    key: copy.deepcopy(value)
    for key, value in stage_ramp_contract.items()
    if key not in {"prompt_context", "raw_openai_response"}
  }
  if isinstance(planning_context_summary_json, dict):
    planning_context_summary_json["stage_ramp_contract"] = {
      key: copy.deepcopy(value)
      for key, value in stage_ramp_contract.items()
      if key not in {"prompt_context", "raw_openai_response"}
    }

  if resume_from_checkpoint_state:
    planning_result = {
      "prompt_file": str(
        (resume_checkpoint_planning_payload or {}).get("prompt_file")
        or planning_choice.get("prompt_file")
        or ""
      ).strip(),
      "gpt_narrative": str((resume_checkpoint_planning_payload or {}).get("gpt_narrative") or "").strip(),
      "metadata": copy.deepcopy((resume_checkpoint_planning_payload or {}).get("gpt_grid_metadata") or {}),
    }
    grid_application_summary = copy.deepcopy(
      (resume_checkpoint_planning_payload or {}).get("grid_application_summary") or {}
    )
    applied_model_input_json = copy.deepcopy(model_input_json)
    applied_finmo_json = copy.deepcopy(finmo_json)
    _persist_system_stage(
      stage="resume_checkpoint_ready",
      status="running",
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      prompt_file=str(planning_result.get("prompt_file") or "").strip(),
      gpt_narrative=str(planning_result.get("gpt_narrative") or "").strip(),
      gpt_grid_metadata=copy.deepcopy(planning_result.get("metadata") or {}),
      grid_application_summary=copy.deepcopy(grid_application_summary or {}),
      model_input_payload=applied_model_input_json,
      finmo_payload=applied_finmo_json,
    )
  else:
    _persist_system_stage(
      stage="quarter_grid_running",
      status="running",
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      prompt_file=str(planning_choice.get("prompt_file") or "").strip(),
      model_input_payload=model_input_json,
      finmo_payload=finmo_json,
    )

    planning_result = generate_live_quarter_grid_plan(
      business_name=str(business_facts.get("name") or "").strip(),
      planning_mode=planning_mode,
      model_input_json=copy.deepcopy(model_input_json),
      finmo_json=copy.deepcopy(finmo_json),
      ops_json=ops_json,
      target_market_json=market_json,
      people_json=people_json,
      financials_json=financials_json,
      financials_year1_json=financials_year1_json,
      fulfillment_json=fulfillment_json,
      marketing_model_json=marketing_model_json,
      realism_memo_json=_parse_json_dict(draft.get("realism_memo_json")),
      business_facts=copy.deepcopy(business_facts or {}),
      stage_ramp_contract=copy.deepcopy(stage_ramp_contract),
    )
    validation = planning_result.get("validation") if isinstance(planning_result.get("validation"), dict) else {}
    if (
      list(validation.get("missing_rows") or [])
      or list(validation.get("extra_rows") or [])
      or list(validation.get("duplicate_rows") or [])
      or list(validation.get("malformed_rows") or [])
    ):
      raise RuntimeError("planning_grid_validation_failed")
    _persist_system_stage(
      stage="quarter_grid_ready",
      status="ready_for_grid_application",
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      prompt_file=str(planning_result.get("prompt_file") or "").strip(),
      gpt_narrative=str(planning_result.get("gpt_narrative") or "").strip(),
      gpt_grid_metadata=copy.deepcopy(planning_result.get("metadata") or {}),
      model_input_payload=model_input_json,
      finmo_payload=finmo_json,
    )

    grid_application_result = apply_live_quarter_grid_plan(
      baseline_model_input_json=copy.deepcopy(model_input_json),
      grid_json=copy.deepcopy(planning_result.get("grid_json") or {}),
    )
    grid_application_summary = (
      grid_application_result.get("application_summary")
      if isinstance(grid_application_result.get("application_summary"), dict)
      else {}
    )
    applied_model_input_json = (
      grid_application_result.get("applied_model_input_json")
      if isinstance(grid_application_result.get("applied_model_input_json"), dict)
      else {}
    )
    applied_finmo_json = (
      grid_application_result.get("applied_finmo_json")
      if isinstance(grid_application_result.get("applied_finmo_json"), dict)
      else {}
    )

  return _run_unified_post_grid_system_run(
    conn=conn,
    draft_id=str(draft_id).strip(),
    planning_run_id=active_planning_run_id,
    business_facts=copy.deepcopy(business_facts or {}),
    planning_context_summary_json=copy.deepcopy(planning_context_summary_json or {}),
    ops_json=copy.deepcopy(ops_json or {}),
    target_market_json=copy.deepcopy(market_json or {}),
    people_json=copy.deepcopy(people_json or {}),
    financials_json=copy.deepcopy(financials_json or {}),
    financials_year1_json=copy.deepcopy(financials_year1_json or {}),
    fulfillment_json=copy.deepcopy(fulfillment_json or {}),
    marketing_model_json=copy.deepcopy(marketing_model_json or {}),
    planning_mode=planning_mode,
    planning_mode_reason=planning_mode_reason,
    planning_result=copy.deepcopy(planning_result or {}),
    grid_application_summary=copy.deepcopy(grid_application_summary or {}),
    catalog_source_model_input_json=copy.deepcopy(model_input_json),
    applied_model_input_json=copy.deepcopy(applied_model_input_json),
    applied_finmo_json=copy.deepcopy(applied_finmo_json),
    stage_ramp_contract=copy.deepcopy(stage_ramp_contract),
  )


def _run_planning_system_for_draft(
  *,
  conn,
  draft_id: str,
  lifecycle_mode: str = "start",
  planning_run_id: Optional[str] = None,
) -> Dict[str, Any]:
  return _run_planning_system_for_draft_unified(
    conn=conn,
    draft_id=draft_id,
    lifecycle_mode=lifecycle_mode,
    planning_run_id=planning_run_id,
  )


def _minimal_controller_state_from_convergence_payloads(
  *,
  planning_convergence_payload: Optional[Dict[str, Any]],
  convergence_state_payload: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
  planning_payload = (
    planning_convergence_payload
    if isinstance(planning_convergence_payload, dict)
    else {}
  )
  convergence_payload = (
    convergence_state_payload
    if isinstance(convergence_state_payload, dict)
    else {}
  )
  issue_state = (
    convergence_payload.get("issue_state")
    if isinstance(convergence_payload.get("issue_state"), dict)
    else {}
  )
  hard_rule_state = (
    convergence_payload.get("hard_rule_state")
    if isinstance(convergence_payload.get("hard_rule_state"), dict)
    else {}
  )
  controller_status = str(
    issue_state.get("controller_status")
    or planning_payload.get("controller_status")
    or ""
  ).strip() or None
  remaining_issue_count = _safe_float(
    issue_state.get("remaining_issue_count")
    if issue_state.get("remaining_issue_count") is not None
    else planning_payload.get("remaining_issue_count")
  )
  all_cleared = bool(
    controller_status == "all_cleared"
    or (remaining_issue_count is not None and remaining_issue_count <= 0.0)
  )
  return {
    "status": controller_status,
    "all_cleared": all_cleared,
    "detected_issue_count": (
      int(_safe_float(issue_state.get("detected_issue_count")) or 0)
      if issue_state.get("detected_issue_count") is not None
      else planning_payload.get("detected_issue_count")
    ),
    "remaining_issue_count": (
      int(_safe_float(remaining_issue_count) or 0)
      if remaining_issue_count is not None
      else None
    ),
    "resolved_issue_count": (
      int(_safe_float(issue_state.get("resolved_issue_count")) or 0)
      if issue_state.get("resolved_issue_count") is not None
      else planning_payload.get("resolved_issue_count")
    ),
    "tolerated_issue_count": (
      int(_safe_float(issue_state.get("tolerated_issue_count")) or 0)
      if issue_state.get("tolerated_issue_count") is not None
      else planning_payload.get("tolerated_issue_count")
    ),
    "iteration_pending_issue_count": (
      int(_safe_float(issue_state.get("iteration_pending_issue_count")) or 0)
      if issue_state.get("iteration_pending_issue_count") is not None
      else planning_payload.get("iteration_pending_issue_count")
    ),
    "overall_completion_score_pct": issue_state.get("overall_completion_score_pct"),
    "overall_completion_grade": issue_state.get("overall_completion_grade"),
    "lowest_quarter_score_pct": issue_state.get("lowest_quarter_score_pct"),
    "failing_quarters": copy.deepcopy(issue_state.get("failing_quarters") or []),
    "remaining_hard_issue_count": (
      int(_safe_float(hard_rule_state.get("remaining_hard_issue_count")) or 0)
      if hard_rule_state.get("remaining_hard_issue_count") is not None
      else None
    ),
  }


def _latest_failure_preservation_payloads(
  *,
  conn,
  draft_id: str,
  planning_run_id: Optional[str] = None,
) -> Dict[str, Any]:
  draft = get_draft(conn, draft_id=str(draft_id).strip())
  latest_checkpoint = None
  run_id = str(planning_run_id or "").strip()
  if not run_id:
    latest_checkpoint = get_latest_planning_run_checkpoint(
      conn,
      draft_id=str(draft_id).strip(),
    )
    run_id = str((latest_checkpoint or {}).get("planning_run_id") or "").strip()
  candidate_checkpoints: List[Dict[str, Any]] = []
  if run_id:
    cur = conn.cursor(dictionary=True)
    try:
      cur.execute(
        """
        SELECT checkpoint_id, checkpoint_kind, planning_convergence_json, convergence_state_json, created_at
        FROM planning_run_checkpoints
        WHERE planning_run_id = %s
        ORDER BY created_at DESC
        LIMIT 12
        """,
        (run_id,),
      )
      candidate_checkpoints = [
        row for row in (cur.fetchall() or [])
        if isinstance(row, dict)
      ]
    finally:
      try:
        cur.close()
      except Exception:
        pass
  if candidate_checkpoints:
    latest_checkpoint = candidate_checkpoints[0]
  elif latest_checkpoint is None:
    latest_checkpoint = get_latest_planning_run_checkpoint(
      conn,
      planning_run_id=run_id or None,
      draft_id=str(draft_id).strip(),
    )
  candidate_rows = []
  for row in candidate_checkpoints:
    candidate_rows.append(row)
  if isinstance(latest_checkpoint, dict) and latest_checkpoint not in candidate_rows:
    candidate_rows.append(latest_checkpoint)
  if isinstance(draft, dict):
    candidate_rows.append(draft)

  preserved_planning_convergence: Dict[str, Any] = {}
  preserved_convergence_state: Dict[str, Any] = {}
  source_kind: Optional[str] = None
  source_checkpoint_id: Optional[str] = None
  for row in candidate_rows:
    planning_convergence_payload = _parse_json_dict(row.get("planning_convergence_json"))
    convergence_payload = _parse_json_dict(row.get("convergence_state_json"))
    issue_state = (
      convergence_payload.get("issue_state")
      if isinstance(convergence_payload.get("issue_state"), dict)
      else {}
    )
    has_counts = any(
      issue_state.get(key) is not None
      for key in (
        "remaining_issue_count",
        "resolved_issue_count",
        "tolerated_issue_count",
        "overall_completion_score_pct",
      )
    )
    if planning_convergence_payload or convergence_payload or has_counts:
      preserved_planning_convergence = copy.deepcopy(planning_convergence_payload)
      preserved_convergence_state = copy.deepcopy(convergence_payload)
      source_kind = "checkpoint" if row is not draft else "draft"
      source_checkpoint_id = str(row.get("checkpoint_id") or "").strip() or None
      if has_counts:
        break

  return {
    "planning_convergence_json": preserved_planning_convergence,
    "convergence_state_json": preserved_convergence_state,
    "source_kind": source_kind,
    "source_checkpoint_id": source_checkpoint_id,
  }


def _merge_terminal_failure_context(
  *,
  planning_convergence_payload: Optional[Dict[str, Any]],
  convergence_state_payload: Optional[Dict[str, Any]],
  current_stage: str,
  detail: str,
  source_kind: Optional[str] = None,
  source_checkpoint_id: Optional[str] = None,
  failure_diagnostics: Optional[Dict[str, Any]] = None,
) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any], bool]:
  planning_payload = (
    copy.deepcopy(planning_convergence_payload)
    if isinstance(planning_convergence_payload, dict)
    else {}
  )
  convergence_payload = (
    copy.deepcopy(convergence_state_payload)
    if isinstance(convergence_state_payload, dict)
    else {}
  )
  controller_state = _minimal_controller_state_from_convergence_payloads(
    planning_convergence_payload=planning_payload,
    convergence_state_payload=convergence_payload,
  )
  terminal_failure_after_all_cleared = bool(controller_state.get("all_cleared"))
  failure_context = {
    "failure_reason": str(detail or "").strip() or None,
    "failed_stage": str(current_stage or "").strip() or None,
    "source_kind": str(source_kind or "").strip() or None,
    "source_checkpoint_id": str(source_checkpoint_id or "").strip() or None,
    "preserved_last_known_good_state": bool(planning_payload or convergence_payload),
    "terminal_failure_after_all_cleared": terminal_failure_after_all_cleared,
  }
  if isinstance(failure_diagnostics, dict) and failure_diagnostics:
    failure_context["failure_diagnostics"] = copy.deepcopy(failure_diagnostics)
  planning_payload["status"] = "failed"
  planning_payload["run_status"] = "failed"
  planning_payload["failure_reason"] = str(detail or "").strip() or None
  planning_payload["terminal_failure_context"] = copy.deepcopy(failure_context)
  if convergence_payload:
    convergence_payload["status"] = "failed"
    convergence_payload["stage"] = str(current_stage or "").strip() or None
    convergence_payload["failure_reason"] = str(detail or "").strip() or None
    convergence_payload["terminal_failure_context"] = copy.deepcopy(failure_context)
  return planning_payload, convergence_payload, controller_state, terminal_failure_after_all_cleared


def _persist_failed_system_run_snapshot(
  *,
  conn,
  draft_id: str,
  detail: str,
  active_run: Optional[Dict[str, Any]] = None,
  failure_diagnostics: Optional[Dict[str, Any]] = None,
) -> None:
  draft = get_draft(conn, draft_id=str(draft_id).strip())
  planning_run_payload = _parse_json_dict(draft.get("planning_run_json"))
  planning_runtime_payload = _parse_json_dict(draft.get("planning_runtime_json"))
  numeric_solver_feedback_payload = _parse_json_dict(draft.get("numeric_solver_feedback_json"))
  model_input_payload = _parse_json_dict(draft.get("model_input_json"))
  finmo_payload = _parse_json_dict(draft.get("finmo_json"))
  if not isinstance(planning_run_payload, dict):
    planning_run_payload = {}
  active_run_row = active_run if isinstance(active_run, dict) else {}
  current_stage = str(
    active_run_row.get("current_stage")
    or planning_run_payload.get("stage")
    or "system_run_failed"
  ).strip() or "system_run_failed"
  planning_run_id = str(
    active_run_row.get("planning_run_id")
    or planning_run_payload.get("planning_run_id")
    or ""
  ).strip()
  preserved_payloads = _latest_failure_preservation_payloads(
    conn=conn,
    draft_id=str(draft_id).strip(),
    planning_run_id=planning_run_id or None,
  )
  preserved_planning_convergence, preserved_convergence_state, preserved_controller_state, terminal_failure_after_all_cleared = _merge_terminal_failure_context(
    planning_convergence_payload=copy.deepcopy(preserved_payloads.get("planning_convergence_json") or {}),
    convergence_state_payload=copy.deepcopy(preserved_payloads.get("convergence_state_json") or {}),
    current_stage=current_stage,
    detail=str(detail or "").strip(),
    source_kind=str(preserved_payloads.get("source_kind") or "").strip() or None,
    source_checkpoint_id=str(preserved_payloads.get("source_checkpoint_id") or "").strip() or None,
    failure_diagnostics=copy.deepcopy(failure_diagnostics if isinstance(failure_diagnostics, dict) else {}),
  )
  planning_run_payload["stage"] = current_stage
  planning_run_payload["status"] = "failed"
  planning_run_payload["run_status"] = "failed"
  planning_run_payload["failure_reason"] = (
    f"terminal_failure_after_all_cleared: {str(detail or '').strip()}"
    if terminal_failure_after_all_cleared
    else str(detail or "").strip()
  )
  if planning_run_id:
    planning_run_payload["planning_run_id"] = planning_run_id
  if preserved_controller_state:
    planning_run_payload["controller_resolution_state"] = copy.deepcopy(preserved_controller_state)
  planning_run_payload["terminal_failure_context"] = {
    "terminal_failure_after_all_cleared": terminal_failure_after_all_cleared,
    "source_kind": str(preserved_payloads.get("source_kind") or "").strip() or None,
    "source_checkpoint_id": str(preserved_payloads.get("source_checkpoint_id") or "").strip() or None,
    "preserved_last_known_good_state": bool(preserved_planning_convergence or preserved_convergence_state),
  }
  if isinstance(failure_diagnostics, dict) and failure_diagnostics:
    planning_run_payload["terminal_failure_context"]["failure_diagnostics"] = copy.deepcopy(
      failure_diagnostics
    )
    planning_run_payload["cash_strategy_failure_diagnostics"] = copy.deepcopy(
      failure_diagnostics
    )
  persist_post_intake_execution_state(
    conn,
    draft_id=str(draft_id).strip(),
    new_messages=[],
    model_input_json=model_input_payload if isinstance(model_input_payload, dict) else None,
    finmo_json=finmo_payload if isinstance(finmo_payload, dict) else None,
    planning_run_json=copy.deepcopy(planning_run_payload),
    planning_runtime_json=(
      copy.deepcopy(planning_runtime_payload)
      if isinstance(planning_runtime_payload, dict)
      else None
    ),
    planning_convergence_json=copy.deepcopy(preserved_planning_convergence),
    convergence_state_json=copy.deepcopy(preserved_convergence_state),
    numeric_solver_feedback_json=(
      copy.deepcopy(numeric_solver_feedback_payload)
      if isinstance(numeric_solver_feedback_payload, dict)
      else None
    ),
    active_focus="done",
    status="failed",
    completed=False,
    checkpoint_kind="failure_snapshot",
    event_type="system_run_failed",
    event_summary=f"{current_stage}:failed",
  )


def post_intake_consult_system_run_handler(*, app, request):
  if request.method == "OPTIONS":
    return ("", 204)

  # The OpenAI deadline is a per-run/cycle guard. Clear any stale value from a
  # prior failed request before this run starts so one failure cannot poison the
  # next system run.
  _set_active_openai_deadline(None)

  payload = request.get_json(silent=True) or {}
  draft_id = str(payload.get("draft_id") or "").strip()
  lifecycle_mode = str(payload.get("lifecycle_mode") or "start").strip().lower() or "start"
  planning_run_id = str(payload.get("planning_run_id") or "").strip()
  if not draft_id:
    return (
      jsonify({"error": "invalid_request", "detail": "draft_id is required"}),
      400,
    )

  try:
    from intake_submission import get_mysql_connection  # type: ignore
  except Exception as exc:
    app.logger.exception("Failed to import MySQL helpers: %s", exc)
    return (jsonify({"error": "server_error"}), 500)

  conn = get_mysql_connection()
  try:
    try:
      result = _run_planning_system_for_draft(
        conn=conn,
        draft_id=draft_id,
        lifecycle_mode=lifecycle_mode,
        planning_run_id=planning_run_id or None,
      )
    except PlanningRunLifecycleInterrupt as exc:
      run_row = get_planning_run(conn, planning_run_id=exc.planning_run_id)
      checkpoint = get_latest_planning_run_checkpoint(conn, planning_run_id=exc.planning_run_id)
      return jsonify(
        {
          "status": "ok",
          "draft_id": draft_id,
          "planning_run_id": exc.planning_run_id,
          "action": f"system_run_{exc.action}d",
          "assistant_message": f"System run {exc.action}d.",
          "detail": exc.detail,
          "planning_run": _serialize_debug_draft_row(run_row or {}),
          "latest_checkpoint": _serialize_debug_draft_row(checkpoint or {}),
        }
      )
    except RuntimeError as exc:
      detail = str(exc).strip() or "system_run_failed"
      if detail == "draft_not_complete":
        return (jsonify({"error": "conflict", "detail": detail}), 409)
      if detail.startswith("planning_run_already_active:"):
        return (
          jsonify(
            {
              "error": "conflict",
              "detail": "planning_run_already_active",
              "planning_run_id": detail.split(":", 1)[1],
            }
          ),
          409,
        )
      if detail == "planning_run_resume_target_not_found":
        return (jsonify({"error": "not_found", "detail": detail}), 404)
      active_run = get_planning_run(
        conn,
        planning_run_id=planning_run_id or None,
        draft_id=draft_id,
        active_only=True,
      )
      if isinstance(active_run, dict):
        clear_planning_run_action(
          conn,
          planning_run_id=str(active_run.get("planning_run_id") or "").strip(),
          run_status="failed",
          failure_reason=detail,
        )
      _persist_failed_system_run_snapshot(
        conn=conn,
        draft_id=draft_id,
        detail=detail,
        active_run=active_run if isinstance(active_run, dict) else None,
        failure_diagnostics=(
          copy.deepcopy(getattr(exc, "diagnostics", {}))
          if isinstance(getattr(exc, "diagnostics", {}), dict)
          else None
        ),
      )
      app.logger.exception("System run failed for draft %s: %s", draft_id, detail)
      return (jsonify({"error": "system_run_failed", "detail": detail}), 500)
    except Exception as exc:
      active_run = get_planning_run(
        conn,
        planning_run_id=planning_run_id or None,
        draft_id=draft_id,
        active_only=True,
      )
      if isinstance(active_run, dict):
        clear_planning_run_action(
          conn,
          planning_run_id=str(active_run.get("planning_run_id") or "").strip(),
          run_status="failed",
          failure_reason=str(exc),
        )
      _persist_failed_system_run_snapshot(
        conn=conn,
        draft_id=draft_id,
        detail=str(exc),
        active_run=active_run if isinstance(active_run, dict) else None,
      )
      app.logger.exception("System run failed for draft %s", draft_id)
      return (jsonify({"error": "system_run_failed", "detail": str(exc)}), 500)

    planning_run_json = (
      result.get("planning_run_json")
      if isinstance(result.get("planning_run_json"), dict)
      else {}
    )
    numeric_solver_feedback_json = (
      result.get("numeric_solver_feedback_json")
      if isinstance(result.get("numeric_solver_feedback_json"), dict)
      else {}
    )
    planning_runtime_json = (
      result.get("planning_runtime_json")
      if isinstance(result.get("planning_runtime_json"), dict)
      else {}
    )
    planning_context_summary_json = (
      result.get("planning_context_summary_json")
      if isinstance(result.get("planning_context_summary_json"), dict)
      else {}
    )
    return jsonify(
      {
        "status": "ok",
        "draft_id": str(result.get("draft_id") or draft_id).strip(),
        "action": "system_run_complete",
        "assistant_message": "System run complete.",
        "planning_context_summary_json": planning_context_summary_json,
        "planning_run_json": planning_run_json,
        "planning_runtime_json": planning_runtime_json,
        "numeric_solver_feedback_json": numeric_solver_feedback_json,
      }
    )
  finally:
    _set_active_openai_deadline(None)
    try:
      conn.close()
    except Exception:
      pass


def post_intake_consult_system_run_control_handler(*, app, request):
  if request.method == "OPTIONS":
    return ("", 204)

  payload = request.get_json(silent=True) or {}
  draft_id = str(payload.get("draft_id") or "").strip()
  planning_run_id = str(payload.get("planning_run_id") or "").strip()
  action = str(payload.get("action") or "").strip().lower()
  reason = str(payload.get("reason") or "").strip()
  if not draft_id and not planning_run_id:
    return (
      jsonify({"error": "invalid_request", "detail": "draft_id or planning_run_id is required"}),
      400,
    )
  if action not in {"pause", "stop"}:
    return (
      jsonify({"error": "invalid_request", "detail": "action must be pause or stop"}),
      400,
    )

  try:
    from intake_submission import get_mysql_connection  # type: ignore
  except Exception as exc:
    app.logger.exception("Failed to import MySQL helpers: %s", exc)
    return (jsonify({"error": "server_error"}), 500)

  conn = get_mysql_connection()
  try:
    try:
      run_row = request_planning_run_action(
        conn,
        draft_id=draft_id or None,
        planning_run_id=planning_run_id or None,
        action=action,
        reason=reason,
      )
    except RuntimeError as exc:
      detail = str(exc).strip() or "planning_run_control_failed"
      if detail == "planning_run_not_found_for_action":
        return (jsonify({"error": "not_found", "detail": detail}), 404)
      if detail == "unsupported_planning_run_action":
        return (jsonify({"error": "invalid_request", "detail": detail}), 400)
      raise
    checkpoint = get_latest_planning_run_checkpoint(
      conn,
      planning_run_id=str((run_row or {}).get("planning_run_id") or "").strip(),
    )
    return jsonify(
      {
        "status": "ok",
        "action": f"run_{action}_requested",
        "planning_run": _serialize_debug_draft_row(run_row or {}),
        "latest_checkpoint": _serialize_debug_draft_row(checkpoint or {}),
      }
    )
  finally:
    try:
      conn.close()
    except Exception:
      pass


def get_intake_consult_system_run_status_handler(*, app, request):
  if request.method == "OPTIONS":
    return ("", 204)

  draft_id = str(request.args.get("draft_id") or "").strip()
  planning_run_id = str(request.args.get("planning_run_id") or "").strip()
  if not draft_id and not planning_run_id:
    return (
      jsonify({"error": "invalid_request", "detail": "draft_id or planning_run_id is required"}),
      400,
    )

  try:
    from intake_submission import get_mysql_connection  # type: ignore
  except Exception as exc:
    app.logger.exception("Failed to import MySQL helpers: %s", exc)
    return (jsonify({"error": "server_error"}), 500)

  conn = get_mysql_connection()
  try:
    run_row = get_planning_run(
      conn,
      planning_run_id=planning_run_id or None,
      draft_id=draft_id or None,
      active_only=not bool(planning_run_id),
    )
    if not isinstance(run_row, dict) and draft_id and not planning_run_id:
      run_row = get_planning_run(
        conn,
        draft_id=draft_id,
        active_only=False,
      )
    if not isinstance(run_row, dict):
      return (jsonify({"error": "not_found", "detail": "planning_run_not_found"}), 404)
    checkpoint = get_latest_planning_run_checkpoint(
      conn,
      planning_run_id=str(run_row.get("planning_run_id") or "").strip(),
    )
    return jsonify(
      {
        "status": "ok",
        "planning_run": _serialize_debug_draft_row(run_row or {}),
        "latest_checkpoint": _serialize_debug_draft_row(checkpoint or {}),
      }
    )
  finally:
    try:
      conn.close()
    except Exception:
      pass


def _parse_json_value(raw: Any) -> Any:
  if raw is None:
    return None
  if isinstance(raw, (dict, list)):
    return raw
  try:
    return json.loads(str(raw))
  except Exception:
    return raw

def _serialize_debug_draft_row(row: Dict[str, Any]) -> Dict[str, Any]:
  if not isinstance(row, dict):
    return {}
  json_columns = {
    "messages_json",
    "operating_model_json",
    "target_market_json",
    "people_json",
    "financials_json",
    "marketing_model_json",
    "financials_year1_json",
    "realism_memo_json",
    "model_input_json",
    "finmo_json",
    "planning_run_json",
    "numeric_solver_feedback_json",
    "pending_ops_milestone_json",
    "fulfillment_json",
  }
  serialized: Dict[str, Any] = {}
  for key, value in row.items():
    if key in json_columns:
      serialized[key] = _parse_json_value(value)
    elif isinstance(value, (datetime, date)):
      serialized[key] = value.isoformat(sep=" ")
    else:
      serialized[key] = value
  return serialized


def get_intake_consult_debug_state_handler(*, app, request, draft_id: str):
  if request.method == "OPTIONS":
    return ("", 204)

  if not draft_id or not str(draft_id).strip():
    return (
      jsonify({"error": "invalid_request", "detail": "draft_id is required"}),
      400,
    )

  try:
    from intake_submission import get_mysql_connection  # type: ignore
    from intake_consult_draft import get_draft  # type: ignore
  except Exception as exc:
    app.logger.exception("Failed to import MySQL helpers: %s", exc)
    return (jsonify({"error": "server_error"}), 500)

  conn = get_mysql_connection()
  try:
    try:
      draft = get_draft(conn, draft_id=str(draft_id).strip())
    except Exception as exc:
      return (jsonify({"error": "not_found", "detail": str(exc)}), 404)

    return jsonify(
      {
        "status": "ok",
        "table": "intake_consult_drafts",
        "draft_id": str(draft_id).strip(),
        "controller_resolution_state": (
          _parse_json_dict(draft.get("planning_run_json")).get("controller_resolution_state")
          if isinstance(_parse_json_dict(draft.get("planning_run_json")).get("controller_resolution_state"), dict)
          else {}
        ),
        "row": _serialize_debug_draft_row(draft),
      }
    )
  finally:
    try:
      conn.close()
    except Exception:
      pass


def post_intake_consult_handler(*, app, request):
  """
  Unified intake consult controller (single chat, single draft model).
  """

  if request.method == "OPTIONS":
    return ("", 204)

  payload = request.get_json(silent=True) or {}
  draft_id = payload.get("draft_id")
  if not draft_id or not str(draft_id).strip():
    return (
      jsonify({"error": "invalid_request", "detail": "draft_id is required"}),
      400,
    )

  raw_message = payload.get("message")
  message = str(raw_message or "").strip()
  starting = raw_message is None or not message

  try:
    from intake_submission import get_mysql_connection  # type: ignore
    from intake_consult_draft import append_messages, get_draft  # type: ignore
    from api_handlers.shared_context import build_shared_context  # type: ignore
    from fact_templates import sanitize_fact_template  # type: ignore
    from intent_router import route_intent  # type: ignore

    from intake_consultant import consultant_chat_turn, consultant_finalize  # type: ignore
    from target_market_consultant import target_market_chat_turn, target_market_finalize  # type: ignore
    from people_capability_consultant import (  # type: ignore
      extract_people_collection_progress,
      people_capability_chat_turn,
      people_capability_finalize,
    )
    from financials_year1 import (  # type: ignore
      assemble_financials_year1,
      build_revenue_driver_signature,
      build_revenue_guardrail_signals,
      build_revenue_constraints_snippet,
      build_revenue_math_line,
    )
    from api_handlers.fact_propagation import propagate_shared_facts
    from api_handlers.revenue_guardrail_state import acknowledge_signature, get_acknowledged_signature
  except Exception as exc:
    app.logger.exception("Failed to import unified intake helpers: %s", exc)
    return (jsonify({"error": "server_error"}), 500)

  conn = get_mysql_connection()
  try:
    consult = get_draft(conn, draft_id=str(draft_id).strip())
    client_id = str(consult.get("client_id") or "").strip()
    draft_status = str(consult.get("status") or "").strip().lower()
    if draft_status == "submitted":
      return (
        jsonify({"error": "duplicate_submit", "detail": "This draft was already submitted."}),
        409,
      )

    messages = _parse_messages(consult.get("messages_json"))

    ops_json = _parse_json_dict(consult.get("operating_model_json"))
    market_json = _parse_json_dict(consult.get("target_market_json"))
    people_json = _parse_json_dict(consult.get("people_json"))
    financials_json = _parse_json_dict(consult.get("financials_json"))
    marketing_model_json = _parse_json_dict(consult.get("marketing_model_json"))
    financials_year1_json = _parse_json_dict(consult.get("financials_year1_json"))
    fulfillment_json = _parse_json_dict(consult.get("fulfillment_json"))
    pending_ops_milestone = _parse_pending_bool(consult.get("pending_ops_milestone_json"))

    _ensure_ops_business_naics(conn, ops_json)
    restatement_locked_prior = bool(ops_json.get("business_type_candidates_locked"))

    ops_confirmed = bool(consult.get("ops_confirmed"))
    market_confirmed = bool(consult.get("market_confirmed"))
    people_confirmed = bool(consult.get("people_confirmed"))
    financials_confirmed = bool(consult.get("financials_confirmed"))
    ops_finalize_proposed = bool(consult.get("ops_finalize_proposed"))
    market_finalize_proposed = bool(consult.get("market_finalize_proposed"))
    people_finalize_proposed = bool(consult.get("people_finalize_proposed"))

    business_facts: Dict[str, Any] = {
      "name": consult.get("business_name"),
      "address": consult.get("business_address"),
      "start_date": consult.get("business_start_date"),
      "address_street": consult.get("address_street"),
      "address_city": consult.get("address_city"),
      "address_state": consult.get("address_state"),
      "address_zip": consult.get("address_zip"),
      "address_country": consult.get("address_country"),
    }

    # Allow explicit client-detail updates from the UI (no intent inference).
    if payload.get("business_name") is not None:
      name_raw = str(payload.get("business_name") or "").strip()
      if name_raw:
        business_facts["name"] = name_raw
    address_keys = ("address_street", "address_city", "address_state", "address_zip", "address_country")
    payload_parts: Dict[str, str] = {}
    for key in address_keys:
      if payload.get(key) is None:
        payload_parts[key] = ""
        continue
      payload_parts[key] = str(payload.get(key) or "").strip()
    has_all_parts = all(payload_parts.values())
    if payload.get("address") is not None:
      addr_raw = str(payload.get("address") or "").strip()
      if addr_raw and has_all_parts:
        business_facts["address"] = addr_raw
    start_date_raw = payload.get("business_start_date")
    if start_date_raw is None:
      start_date_raw = payload.get("businessStartDate") or payload.get("business_startDate")
    if start_date_raw is not None:
      sd_raw = str(start_date_raw or "").strip()
      if sd_raw:
        business_facts["start_date"] = sd_raw

    if has_all_parts:
      for key, val in payload_parts.items():
        if val:
          business_facts[key] = val

    current_date = datetime.utcnow().date()
    current_date_iso = current_date.isoformat()
    business_stage_hint = _infer_business_stage(business_facts.get("start_date"), current_date)

    focus, confirm_question = _compute_focus_and_confirm_question(
      ops_json=ops_json,
      market_json=market_json,
      people_json=people_json,
      financials_json=financials_json,
      ops_confirmed=ops_confirmed,
      market_confirmed=market_confirmed,
      people_confirmed=people_confirmed,
      financials_confirmed=financials_confirmed,
    )

    shared_context = build_shared_context(conn, draft_id=str(draft_id).strip())
    shared_context = dict(shared_context or {})
    shared_context["operating_model"] = ops_json
    shared_context["target_market"] = market_json
    shared_context["people_capability"] = people_json
    shared_context["financials"] = financials_json
    base_year1 = assemble_financials_year1(shared_context, None)
    if _year1_drivers_conflict(financials_year1_json, base_year1):
      financials_year1_json = base_year1
    else:
      financials_year1_json = assemble_financials_year1(shared_context, financials_year1_json)
    financials_json, financials_year1_json = _sync_financials_consult_persistence_state(
      financials_json=financials_json,
      financials_year1_json=financials_year1_json,
      marketing_model_json=marketing_model_json,
    )
    shared_context["financials"] = financials_json
    if isinstance(financials_year1_json, dict) and financials_year1_json:
      shared_context["financials_year1_json"] = financials_year1_json

    def _refresh_marketing_model() -> Dict[str, Any]:
      nonlocal marketing_model_json, shared_context
      try:
        marketing_model_json = _compute_marketing_model_json(
          conn=conn,
          ops_json=ops_json,
          market_json=market_json,
          people_json=people_json,
          financials_year1_json=financials_year1_json,
          business_facts=business_facts,
          existing_marketing_model_json=marketing_model_json,
          estimate_marketing_baseline_from_context=estimate_marketing_baseline_from_context,
        )
      except Exception:
        marketing_model_json = dict(marketing_model_json or {})
      shared_context["marketing"] = marketing_model_json
      return marketing_model_json

    def _persist_intake_completion(
      *,
      new_messages: List[Dict[str, str]],
      ops_value: Dict[str, Any],
      market_value: Dict[str, Any],
      people_value: Dict[str, Any],
      financials_value: Dict[str, Any],
      financials_year1_value: Dict[str, Any],
      marketing_value: Dict[str, Any],
      confirmations_value: Optional[Dict[str, bool]] = None,
      flat_fields_value: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
      planning_run_json = _build_intake_complete_planning_run_payload()
      realism_memo_json = generate_realism_memo_payload_safe(
        ops_json=ops_value,
        financials_json=financials_value,
      )
      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=new_messages,
        operating_model_json=ops_value,
        target_market_json=market_value,
        people_json=people_value,
        financials_json=financials_value,
        financials_year1_json=financials_year1_value,
        marketing_model_json=marketing_value,
        realism_memo_json=realism_memo_json,
        planning_run_json=planning_run_json,
        active_focus="done",
        confirmations=confirmations_value,
        business_facts=business_facts,
        status="completed",
        completed=True,
        flat_fields=flat_fields_value,
      )
      return planning_run_json

    _refresh_marketing_model()
    revenue_math_line = build_revenue_math_line(
      financials_year1_json,
      unit_name=str((ops_json or {}).get("unit_name") or "").strip() or None,
    )
    revenue_constraints_snippet = build_revenue_constraints_snippet(
      shared_context,
      financials_year1_json,
      business_start_date=str(business_facts.get("start_date") or "").strip() or None,
    )
    guardrail_signals = build_revenue_guardrail_signals(
      shared_context,
      financials_year1_json,
      business_start_date=str(business_facts.get("start_date") or "").strip() or None,
      fulfillment_context=fulfillment_json,
    )
    driver_signature = build_revenue_driver_signature(financials_year1_json)
    guardrail_acknowledged = (
      get_acknowledged_signature(str(draft_id).strip()) == driver_signature
    )
    guardrail_triggered = bool(guardrail_signals.get("triggered")) and not guardrail_acknowledged

    if starting:
      start_instruction = _start_instruction_for_focus(focus)
      turn_messages = [*messages, {"role": "user", "content": start_instruction}]
      intake_context: Dict[str, Any] = {
        "client_id": client_id,
        "draft_id": str(draft_id).strip(),
        "business_name": business_facts.get("name"),
        "business_start_date": business_facts.get("start_date"),
        "address": business_facts.get("address"),
        "current_date": current_date_iso,
        "business_stage_hint": business_stage_hint,
        "shared_context": shared_context,
        "fulfillment_json": fulfillment_json,
      }
      if focus == "market":
        consumer_type = str((ops_json or {}).get("consumer_type") or "consumer").strip().lower()
        if consumer_type not in ("consumer", "b2b", "mixed"):
          consumer_type = "consumer"
        intake_context["consumer_type"] = consumer_type
      intake_context["financials_year1_json"] = financials_year1_json
      intake_context["revenue_math_line"] = revenue_math_line
      intake_context["revenue_constraints_snippet"] = revenue_constraints_snippet
      intake_context["revenue_driver_patch"] = None
      intake_context["revenue_guardrail_triggered"] = guardrail_triggered
      intake_context["revenue_guardrail_context_signals"] = guardrail_signals.get("context_signals") or []
      intake_context["revenue_guardrail_product_signals"] = guardrail_signals.get("product_signals") or []

      # Target Market is model-interpreted every turn and returns a structured patch,
      # allowing us to persist the Target Market JSON incrementally (no controller parsing).
      turn: Dict[str, Any] = {}
      closeout: Optional[Dict[str, Any]] = None
      if focus == "ops":
        turn = consultant_chat_turn(intake_context=intake_context, conversation_messages=turn_messages) or {}
        ops_json = _apply_model_ops_patch(ops_json, turn.get("patch") if isinstance(turn, dict) else None)
        try:
          shared_context["operating_model"] = ops_json
        except Exception:
          pass
      elif focus == "market":
        turn = target_market_chat_turn(intake_context=intake_context, conversation_messages=turn_messages) or {}
        try:
          if isinstance(market_json, dict):
            patch_obj = turn.get("patch") if isinstance(turn, dict) else None
            if isinstance(patch_obj, dict):
              allowed_keys = {
                "consumer_type",
                "gender_age_intent",
                "income_intent",
                "b2b_industry_terms",
                "b2b_size_bands",
                "b2b_age_bands",
              }
              for k, v in patch_obj.items():
                key = str(k or "").strip()
                if not key:
                  continue
                if key.startswith("market."):
                  key = key.split(".", 1)[1].strip()
                if key in allowed_keys:
                  # In strict json_schema, the model must always output every patch key.
                  # We treat null values as "no change" to avoid wiping prior answers.
                  if v is None:
                    continue
                  market_json[key] = v
        except Exception:
          pass
      elif focus == "people":
        turn = people_capability_chat_turn(intake_context=intake_context, conversation_messages=turn_messages) or {}
      elif focus == "financials":
        turn, financials_json = _build_financials_live_turn(
          conn=conn,
          intake_context=intake_context,
          conversation_messages=turn_messages,
          shared_context=shared_context,
          financials_json=financials_json,
          financials_year1_json=financials_year1_json,
          guardrail_triggered=False,
        )
      else:
        turn = {"assistant_message": "Continue."}

      assistant_text = str(turn.get("assistant_message") or "").strip() or "Continue."

      assistant_text = sanitize_fact_template(str(assistant_text or "").strip())
      if focus == "market":
        assistant_text = _strip_acs_codes(assistant_text)
      if focus == "financials":
        assistant_text = _append_constraints_snippet(
          assistant_text,
          revenue_constraints_snippet,
          messages,
          force=True,
        )

      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[{"role": "assistant", "content": assistant_text}],
        operating_model_json=ops_json if focus == "done" else None,
        target_market_json=market_json if focus in {"market", "done"} else None,
        people_json=people_json if focus == "done" else None,
        financials_json=financials_json if focus in {"financials", "done"} else None,
        financials_year1_json=financials_year1_json if focus == "done" else None,
        marketing_model_json=marketing_model_json if focus == "done" else _refresh_marketing_model(),
        active_focus=focus,
        business_facts=business_facts,
        status="completed" if focus == "done" else None,
        completed=bool(focus == "done"),
      )

      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": focus,
          "awaiting_confirmation": bool(confirm_question),
          "done": bool(focus == "done"),
          "action": "continue",
          "assistant_message": assistant_text,
          "planning_mode": (
            str((closeout or {}).get("planning_mode") or "").strip()
            if isinstance(closeout, dict)
            else None
          ) or None,
          "planning_mode_reason": (
            str((closeout or {}).get("planning_mode_reason") or "").strip()
            if isinstance(closeout, dict)
            else None
          ) or None,
          "prompt_file": (
            str((closeout or {}).get("prompt_file") or "").strip()
            if isinstance(closeout, dict)
            else None
          ) or None,
        }
      )

    user_msg = {"role": "user", "content": message}
    recent_messages = messages[-12:] if len(messages) > 12 else list(messages)
    last_assistant = _last_assistant_message(messages)
    restatement_confirmed_this_turn = False
    persist_ops_from_restatement = False
    ops_restatement_meta_touched = False
    ops_restatement_pending = bool((ops_json or {}).get("_ops_restatement_pending"))
    ops_restatement_text = str((ops_json or {}).get("_ops_restatement_text") or "").strip()
    if (
      str(focus).strip().lower() == "ops"
      and last_assistant
    ):
      # Only run restatement confirmation inference when the controller explicitly
      # marked the prior assistant turn as the restatement confirmation prompt.
      # This avoids early persistence from classifier misfires on non-restatement turns.
      if ops_restatement_pending:
        try:
          classification = _classify_restatement_response(
            restatement=ops_restatement_text or last_assistant,
            user_reply=message,
          )
        finally:
          # Pending applies to exactly one client reply turn. Clear it regardless of
          # ACCEPT/REJECT/CLARIFY so we don't keep classifying subsequent answers.
          if isinstance(ops_json, dict):
            ops_json.pop("_ops_restatement_pending", None)
          ops_restatement_meta_touched = True
        if classification == "ACCEPT":
          restatement_confirmed_this_turn = True

    if restatement_confirmed_this_turn:
      already_locked = bool(ops_json.get("business_type_candidates_locked"))
      existing_candidates = ops_json.get("business_type_candidates")
      has_candidates = isinstance(existing_candidates, list) and bool(existing_candidates)
      if not already_locked and not has_candidates:
        try:
          bt_candidates = _build_business_type_candidates(
            conn=conn,
            messages=[*messages, user_msg],
            restatement_text=ops_restatement_text or last_assistant,
          )
        except Exception as exc:
          logger.exception("business_type_selection_failed: %s", exc)
          return (jsonify({"error": "business_type_selection_failed"}), 500)
        if not bt_candidates:
          logger.warning("business_type_selection_empty restatement=%r", last_assistant)
          return (jsonify({"error": "business_type_selection_failed"}), 500)
        ops_json["business_type_candidates"] = bt_candidates
        ops_json["business_type_candidates_locked"] = True
        ops_json["business_type"] = bt_candidates[0]
        try:
          try:
            from business_type_naics import get_naics_from_business_type  # type: ignore
          except Exception:
            from client_intake_and_finmo.business_type_naics import (  # type: ignore
              get_naics_from_business_type,
            )
          if ops_json.get("business_type"):
            ops_json["business_naics_6"] = get_naics_from_business_type(
              conn, ops_json.get("business_type")
            )
          else:
            ops_json["business_naics_6"] = None
        except Exception:
          ops_json["business_naics_6"] = None
        lines = []
        for idx, bt in enumerate(bt_candidates[:80], start=1):
          lines.append(f"{idx}. {bt}")
        if lines:
          logger.warning(
            "BUSINESS TYPE CANDIDATES (ranked):\n%s",
            "\n".join(lines),
          )
        logger.warning(
          "business_type_persisted business_type=%r business_naics_6=%r",
          ops_json.get("business_type"),
          ops_json.get("business_naics_6"),
        )
        persist_ops_from_restatement = True
    revenue_driver_patch = None
    pending_competitive_advantage = _extract_competitive_advantage_prompt(last_assistant)
    competitive_intent_override: Optional[Dict[str, Any]] = None
    if (
      pending_competitive_advantage
      and str(focus).strip().lower() == "ops"
      and not restatement_locked_prior
    ):
      pending_competitive_advantage = None

    if (
      pending_competitive_advantage
      and str(focus).strip().lower() == "ops"
      and not str((ops_json or {}).get("competitive_advantage") or "").strip()
    ):
      competitive_intent = route_intent(
        consult_type="ops",
        user_message=message,
        baseline_json=ops_json,
        shared_context=shared_context,
        recent_messages=recent_messages,
        confirm_question_override=COMPETITIVE_ADVANTAGE_QUESTION,
        active_focus="ops",
      )
      comp_action = str(competitive_intent.get("action") or "").strip()
      comp_router_msg = sanitize_fact_template(
        str(competitive_intent.get("assistant_message") or "").strip()
      )
      comp_patch = competitive_intent.get("patch") if isinstance(competitive_intent.get("patch"), dict) else None
      if comp_action == "confirm_clarify":
        assistant_text = comp_router_msg
        append_messages(
          conn,
          draft_id=str(draft_id).strip(),
          new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
          marketing_model_json=_refresh_marketing_model(),
          active_focus=focus,
          business_facts=business_facts,
        )
        return jsonify(
          {
            "status": "ok",
            "draft_id": str(draft_id).strip(),
            "client_id": client_id,
            "active_focus": focus,
            "awaiting_confirmation": True,
            "done": False,
            "action": "confirm_clarify",
            "assistant_message": assistant_text,
          }
        )
      if comp_action == "confirm_proceed":
        # Commit the confirmed competitive advantage immediately so subsequent Ops logic
        # in this turn cannot re-trigger the proposal injection.
        confirmed_advantage = sanitize_fact_template(
          str(pending_competitive_advantage or "").strip()
        )
        ops_json["competitive_advantage"] = confirmed_advantage
        try:
          shared_context["operating_model"] = ops_json
        except Exception:
          pass
        comp_action = "edit_patch"
        comp_patch = {
          "ops.competitive_advantage": confirmed_advantage
        }
      if comp_action != "edit_patch":
        raise RuntimeError("Unexpected intent action for competitive advantage.")
      competitive_intent_override = {
        "action": comp_action,
        "router_msg": comp_router_msg,
        "patch": comp_patch,
      }

    if not starting:
      # Revenue adjudication / option-battle flow has been removed from the live
      # Financials consult. Financials now stays on the controller/router path.
      pass

    if (
      guardrail_triggered
      and not revenue_driver_patch
      and not starting
      and _is_guardrail_acknowledgement(message)
    ):
      acknowledge_signature(str(draft_id).strip(), driver_signature)
      guardrail_triggered = False

    revenue_math_line = build_revenue_math_line(
      financials_year1_json,
      unit_name=str((ops_json or {}).get("unit_name") or "").strip() or None,
    )

    focus, confirm_question = _compute_focus_and_confirm_question(
      ops_json=ops_json,
      market_json=market_json,
      people_json=people_json,
      financials_json=financials_json,
      ops_confirmed=ops_confirmed,
      market_confirmed=market_confirmed,
      people_confirmed=people_confirmed,
      financials_confirmed=financials_confirmed,
    )

    baseline_json = {
      "business": business_facts,
      "ops": ops_json,
      "market": market_json,
      "people": people_json,
      "financials": financials_json,
      "financials_year1": financials_year1_json,
      "marketing": dict((shared_context or {}).get("marketing") or {}),
      "fulfillment": fulfillment_json,
    }
    current_financials_stage = (
      _next_financials_stage(financials_json)
      if str(focus).strip().lower() == "financials"
      else None
    )
    shared_context_for_router = shared_context
    try:
      router_candidates = ops_json.get("business_type_candidates")
      if isinstance(router_candidates, list) and router_candidates:
        shared_context_for_router = dict(shared_context or {})
        shared_context_for_router["business_type_candidates"] = router_candidates
    except Exception:
      shared_context_for_router = shared_context
    # Route the user's message through the GPT-only intent router first.
    confirm_override = str(confirm_question or _detect_confirm_question(last_assistant) or "").strip()
    # NOTE: Target Market replies are interpreted directly by the Target Market consultant
    # (structured patch). We intentionally do not maintain controller-owned "pending income"
    # confirmation state to avoid brittle loops.
    milestone_intent_override: Optional[Dict[str, Any]] = None
    if (
      str(focus).strip().lower() == "ops"
      and pending_ops_milestone
      and not _has_confirmed_milestone(ops_json)
    ):
      try:
        extracted_milestone = _extract_ops_pending_milestone_via_openai(
          text=message,
          ops_json=ops_json,
          business_facts=business_facts,
        )
        milestone_obj = extracted_milestone.get("milestone")
        clarification_question = sanitize_fact_template(
          str(extracted_milestone.get("clarification_question") or "").strip()
        )
        if bool(extracted_milestone.get("captured")) and isinstance(milestone_obj, dict):
          milestone_intent_override = {
            "action": "edit_patch",
            "router_msg": "Got it.",
            "patch": {"milestones": [milestone_obj]},
          }
        else:
          fallback_milestone = _fallback_ops_pending_milestone_from_text(message)
          if isinstance(fallback_milestone, dict):
            milestone_intent_override = {
              "action": "edit_patch",
              "router_msg": "Got it.",
              "patch": {"milestones": [fallback_milestone]},
            }
          elif clarification_question:
            milestone_intent_override = {
              "action": "confirm_clarify",
              "router_msg": clarification_question,
              "patch": None,
            }
          else:
            milestone_intent = route_intent(
              consult_type="ops",
              user_message=message,
              baseline_json=ops_json,
              shared_context=shared_context_for_router,
              recent_messages=recent_messages,
              active_focus="ops",
            )
            m_action = str(milestone_intent.get("action") or "").strip()
            m_router_msg = sanitize_fact_template(str(milestone_intent.get("assistant_message") or "").strip())
            m_patch = (
              milestone_intent.get("patch") if isinstance(milestone_intent.get("patch"), dict) else None
            )
            # Only override routing when the router actually produced a milestones patch.
            if m_action == "edit_patch" and isinstance(m_patch, dict) and (
              "milestones" in m_patch or "ops.milestones" in m_patch
            ):
              milestone_intent_override = {
                "action": m_action,
                "router_msg": m_router_msg,
                "patch": m_patch,
              }
            elif m_action == "confirm_clarify" and m_router_msg:
              milestone_intent_override = {
                "action": m_action,
                "router_msg": m_router_msg,
                "patch": None,
              }
      except Exception:
        milestone_intent_override = None

    if (
      str(focus).strip().lower() == "people"
      and str(confirm_override or "").strip() != PEOPLE_CONFIRM_QUESTION
      and _detect_people_done_adding_via_openai(
        last_assistant=last_assistant,
        user_message=message,
      )
    ):
      intake_context_people = {
        "client_id": client_id,
        "draft_id": str(draft_id).strip(),
        "business_name": business_facts.get("name"),
        "business_start_date": business_facts.get("start_date"),
        "address": business_facts.get("address"),
        "current_date": current_date_iso,
        "business_stage_hint": business_stage_hint,
        "shared_context": shared_context,
        "operating_model_json": ops_json,
        "target_market_json": market_json,
        "people_json": people_json,
        "financials_json": financials_json,
        "fulfillment_json": fulfillment_json,
      }
      final_obj = people_capability_finalize(
        intake_context=intake_context_people,
        conversation_messages=[*messages, user_msg],
      )
      people_json, assistant_final = _build_people_review_payload(
        conn=conn,
        final_obj=final_obj,
        ops_json=ops_json,
        market_json=market_json,
        financials_json=financials_json,
        business_facts=business_facts,
      )
      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": assistant_final}],
        people_json=people_json,
        marketing_model_json=_refresh_marketing_model(),
        active_focus="people",
        business_facts=business_facts,
        flat_fields=_finalize_flag_field("people", True),
      )
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": "people",
          "awaiting_confirmation": True,
          "done": False,
          "action": "continue",
          "assistant_message": assistant_final,
        }
      )

    if str(focus).strip().lower() == "financials":
      intake_context_financials = {
        "client_id": client_id,
        "draft_id": str(draft_id).strip(),
        "business_name": business_facts.get("name"),
        "business_start_date": business_facts.get("start_date"),
        "address": business_facts.get("address"),
        "current_date": current_date_iso,
        "business_stage_hint": business_stage_hint,
        "shared_context": shared_context,
        "operating_model_json": ops_json,
        "target_market_json": market_json,
        "people_json": people_json,
        "financials_json": financials_json,
        "financials_year1_json": financials_year1_json,
        "fulfillment_json": fulfillment_json,
        "revenue_math_line": revenue_math_line,
        "revenue_constraints_snippet": revenue_constraints_snippet,
        "revenue_driver_patch": revenue_driver_patch,
        "revenue_guardrail_triggered": guardrail_triggered,
        "revenue_guardrail_context_signals": guardrail_signals.get("context_signals") or [],
        "revenue_guardrail_product_signals": guardrail_signals.get("product_signals") or [],
      }
      financials_turn, financials_json = _run_financials_turn_and_sync(
        route_intent=route_intent,
        conn=conn,
        intake_context=intake_context_financials,
        conversation_messages=[*messages, user_msg],
        business_facts=business_facts,
        shared_context=shared_context,
        last_assistant=last_assistant,
        user_message=message,
        financials_json=financials_json,
        financials_year1_json=financials_year1_json,
      )
      shared_context["financials"] = financials_json
      shared_context["financials_year1"] = financials_year1_json
      assistant_text = sanitize_fact_template(
        str((financials_turn or {}).get("assistant_message") or "").strip()
      )
      assistant_text = _append_constraints_snippet(
        assistant_text,
        revenue_constraints_snippet,
        messages,
        force=True,
      )

      if bool((financials_turn or {}).get("transition_to_done")):
        assistant_final = str((financials_turn or {}).get("assistant_message") or "").strip()
        _persist_intake_completion(
          new_messages=[user_msg, {"role": "assistant", "content": assistant_final}],
          ops_value=ops_json,
          market_value=market_json,
          people_value=people_json,
          financials_value=financials_json,
          financials_year1_value=financials_year1_json,
          marketing_value=_refresh_marketing_model(),
          confirmations_value={"financials": True},
          flat_fields_value=_finalize_flag_field("financials", True),
        )
        return jsonify(
          {
            "status": "ok",
            "draft_id": str(draft_id).strip(),
            "client_id": client_id,
            "active_focus": "done",
            "awaiting_confirmation": False,
            "done": True,
            "action": "intake_complete",
            "assistant_message": assistant_final,
          }
        )

      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
        financials_json=financials_json,
        marketing_model_json=_refresh_marketing_model(),
        active_focus="financials",
        business_facts=business_facts,
        flat_fields=_finalize_flag_field("financials", False),
      )
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": "financials",
          "awaiting_confirmation": False,
          "done": False,
          "action": "continue",
          "assistant_message": assistant_text,
        }
      )

    if competitive_intent_override:
      action = str(competitive_intent_override.get("action") or "").strip()
      router_msg = sanitize_fact_template(str(competitive_intent_override.get("router_msg") or "").strip())
      patch = (
        competitive_intent_override.get("patch")
        if isinstance(competitive_intent_override.get("patch"), dict)
        else None
      )
    elif milestone_intent_override:
      action = str(milestone_intent_override.get("action") or "").strip()
      router_msg = sanitize_fact_template(str(milestone_intent_override.get("router_msg") or "").strip())
      patch = (
        milestone_intent_override.get("patch")
        if isinstance(milestone_intent_override.get("patch"), dict)
        else None
      )
    elif str(focus).strip().lower() == "ops" and not restatement_locked_prior:
      action = "continue_chat"
      router_msg = ""
      patch = None
    elif str(focus).strip().lower() == "market" and not market_finalize_proposed:
      # Target Market is model-interpreted every turn (structured patch), not router-parsed.
      action = "continue_chat"
      router_msg = ""
      patch = None
    else:
      intent = route_intent(
        consult_type="unified",
        user_message=message,
        baseline_json=baseline_json,
        shared_context=shared_context_for_router,
        recent_messages=recent_messages,
        confirm_question_override=confirm_override,
        active_focus=focus,
      )

      action = str(intent.get("action") or "").strip()
      router_msg = sanitize_fact_template(str(intent.get("assistant_message") or "").strip())
      patch = intent.get("patch") if isinstance(intent.get("patch"), dict) else None

    if (
      str(focus).strip().lower() == "ops"
      and action == "confirm_proceed"
      and not ops_finalize_proposed
      and not pending_ops_milestone
      and not competitive_intent_override
      and not milestone_intent_override
    ):
      inferred_ops_patch = _extract_ops_proposal_patch(
        last_assistant=last_assistant,
        route_intent=route_intent,
        ops_json=ops_json,
        shared_context=shared_context,
        recent_messages=recent_messages,
      )
      if isinstance(inferred_ops_patch, dict) and inferred_ops_patch:
        action = "edit_patch"
        patch = inferred_ops_patch

    if str(focus).strip().lower() == "financials" and action == "confirm_proceed":
      try:
        active_stage = str(current_financials_stage or "").strip()
        stage_spec = _financials_stage_spec(active_stage)
        if active_stage and bool(stage_spec.get("confirmable_baseline")):
          default_patch = _financials_stage_default_patch(
            stage_name=active_stage,
            shared_context=shared_context,
            financials_year1_json=financials_year1_json,
            business_facts=business_facts,
            conn=conn,
          )
          if isinstance(default_patch, dict) and default_patch:
            action = "edit_patch"
            patch = {f"financials.{k}": v for k, v in default_patch.items()}
      except Exception:
        pass

    if (
      str(focus).strip().lower() == "ops"
      and pending_ops_milestone
      and not _has_confirmed_milestone(ops_json)
      and not milestone_intent_override
      and action != "edit_patch"
    ):
      action = "confirm_clarify"
      router_msg = (
        "What is one concrete goal you want to hit in about the next 12 months, and by when?"
      )
      patch = None

    milestone_patch_from_user: Optional[List[Dict[str, Any]]] = None
    if action == "edit_patch" and isinstance(patch, dict):
      patch = _normalize_unscoped_patch(patch, focus=focus)
      if str(focus or "").strip().lower() == "financials":
        normalized_financials_patch = _normalize_financials_router_patch(
          patch=patch,
          active_stage=current_financials_stage,
          financials_json=financials_json,
          financials_year1_json=financials_year1_json,
          last_assistant=last_assistant,
          user_message=user_text,
        )
        if isinstance(normalized_financials_patch, dict) and normalized_financials_patch:
          patch = {f"financials.{k}": v for k, v in normalized_financials_patch.items()}
      candidate = patch.get("milestones")
      if candidate is None:
        candidate = patch.get("ops.milestones")
      if isinstance(candidate, str):
        try:
          candidate = json.loads(candidate)
        except Exception:
          candidate = None
      if isinstance(candidate, list):
        milestone_patch_from_user = [m for m in candidate if isinstance(m, dict)]

    if milestone_patch_from_user:
      existing_milestones = _parse_milestones((ops_json or {}).get("milestones"))
      if existing_milestones:
        milestone_patch_from_user = None

    # Only accept milestone patches when we are explicitly in the milestone-capture step.
    # This keeps Ops sequencing stable (competitive advantage second-to-last, milestone last)
    # and prevents earlier turns from accidentally persisting a milestone out of order.
    if (
      str(focus).strip().lower() == "ops"
      and pending_ops_milestone
      and not _has_confirmed_milestone(ops_json)
    ):
      if milestone_patch_from_user:
        ops_json["milestones"] = milestone_patch_from_user
        _enrich_milestones_timing(ops_json, reference_date=current_date)
        shared_context["operating_model"] = ops_json
        pending_ops_milestone = False

    # Sections can only advance after the explicit final confirmation has been proposed.
    finalize_flags = {
      "ops": ops_finalize_proposed,
      "market": market_finalize_proposed,
      "people": people_finalize_proposed,
    }
    if action == "confirm_proceed" and focus in finalize_flags and not finalize_flags.get(focus):
      action = "continue_chat"

    # If the intake is fully complete, "continue" should guide the user to submission.
    if focus == "done" and action == "continue_chat":
      assistant_text = 'Final review is complete and the facts line up well enough to proceed.\n\nClick "Submit intake" to finish.'
      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
        marketing_model_json=_refresh_marketing_model(),
        active_focus="done",
        business_facts=business_facts,
      )
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": "done",
          "awaiting_confirmation": False,
          "done": True,
          "action": "ready_to_submit",
          "assistant_message": assistant_text,
        }
      )

    if action == "edit_patch" and patch:
      patch = _normalize_unscoped_patch(patch, focus=focus)

      # Target Market: after we generate a marketing_plan_summary, we present it for
      # confirmation. If the client counters with edits, keep them in this proposal
      # step and re-show the updated marketing_plan_summary (do not restart the
      # full Target Market consult).
      if (
        str(focus or "").strip().lower() == "market"
        and market_finalize_proposed
        and isinstance(patch, dict)
        and ("market.marketing_plan_summary" in patch)
      ):
        business_facts, ops_json, market_json, people_json, financials_json, fulfillment_json = _apply_scoped_patch(
          patch,
          business_facts=business_facts,
          ops_json=ops_json,
          market_json=market_json,
          people_json=people_json,
          financials_json=financials_json,
          fulfillment_json=fulfillment_json,
        )
        assistant_text = sanitize_fact_template(
          str((market_json or {}).get("marketing_plan_summary") or "").strip()
        )
        assistant_text = _strip_acs_codes(assistant_text)
        assistant_text = f"{assistant_text}\n\n{MARKET_CONFIRM_QUESTION}".strip()
        append_messages(
          conn,
          draft_id=str(draft_id).strip(),
          new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
          target_market_json=market_json,
          marketing_model_json=_refresh_marketing_model(),
          active_focus="market",
          business_facts=business_facts,
          flat_fields=_finalize_flag_field("market", True),
        )
        return jsonify(
          {
            "status": "ok",
            "draft_id": str(draft_id).strip(),
            "client_id": client_id,
            "active_focus": "market",
            "awaiting_confirmation": True,
            "done": False,
            "action": "continue",
            "assistant_message": assistant_text,
          }
        )

      people_patch_applied = bool(
        str(focus or "").strip().lower() == "people"
        or any(str(k).strip().lower().startswith("people.") for k in patch.keys())
      )
      baseline_people_json = json.loads(json.dumps(people_json)) if people_json else {}
      business_facts, ops_json, market_json, people_json, financials_json, fulfillment_json = _apply_scoped_patch(
        patch,
        business_facts=business_facts,
        ops_json=ops_json,
        market_json=market_json,
        people_json=people_json,
        financials_json=financials_json,
        fulfillment_json=fulfillment_json,
      )
      marketing_patch_touched = any(
        str(key or "").strip() in {
          "marketing_total_year1",
          "marketing_percent_of_revenue",
          "financials.marketing_total_year1",
          "financials.marketing_percent_of_revenue",
        }
        for key in patch.keys()
      )
      if marketing_patch_touched:
        financials_json = _sync_marketing_field_family(
          financials_json=financials_json,
          financials_year1_json=financials_year1_json,
          marketing_model_json=marketing_model_json,
        )
      # Keep capacity compatibility coherent (especially monthly/contract cadence).
      ops_json = _normalize_ops_capacity_compat(ops_json)
      try:
        shared_context = dict(shared_context or {})
        shared_context["operating_model"] = ops_json
        shared_context["target_market"] = market_json
        shared_context["people_capability"] = people_json
        shared_context["financials"] = financials_json

        # Persist ops.business_description_summary rendered (no {{fact:...}} placeholders),
        # even when ops is updated via edit patches after finalization.
        try:
          try:
            from fact_templates import render_fact_template  # type: ignore
          except Exception:
            from client_intake_and_finmo.fact_templates import render_fact_template  # type: ignore

          if isinstance(ops_json, dict) and str(ops_json.get("business_description_summary") or "").strip():
            business_facts_for_render = {
              "name": str(business_facts.get("name") or "").strip(),
              "address": str(business_facts.get("address") or "").strip(),
              "start_date": str(business_facts.get("start_date") or "").strip(),
            }
            shared_ctx_for_render = {
              "operating_model": ops_json,
              "target_market": market_json,
              "people_capability": people_json,
              "financials": financials_json,
            }
            ops_json["business_description_summary"] = render_fact_template(
              str(ops_json.get("business_description_summary") or ""),
              shared_context=shared_ctx_for_render,
              business_facts=business_facts_for_render,
            ).strip()
            shared_context["operating_model"] = ops_json
        except Exception:
          pass

        base_year1 = assemble_financials_year1(shared_context, None)
        if _year1_drivers_conflict(financials_year1_json, base_year1):
          financials_year1_json = base_year1
        else:
          financials_year1_json = assemble_financials_year1(shared_context, financials_year1_json)
        financials_json, financials_year1_json = _sync_financials_consult_persistence_state(
          financials_json=financials_json,
          financials_year1_json=financials_year1_json,
          marketing_model_json=marketing_model_json,
        )
        shared_context["financials"] = financials_json
        if isinstance(financials_year1_json, dict) and financials_year1_json:
          shared_context["financials_year1_json"] = financials_year1_json
        revenue_math_line = build_revenue_math_line(
          financials_year1_json,
          unit_name=str((ops_json or {}).get("unit_name") or "").strip() or None,
        )
        revenue_constraints_snippet = build_revenue_constraints_snippet(
          shared_context,
          financials_year1_json,
          business_start_date=str(business_facts.get("start_date") or "").strip() or None,
        )
        guardrail_signals = build_revenue_guardrail_signals(
          shared_context,
          financials_year1_json,
          business_start_date=str(business_facts.get("start_date") or "").strip() or None,
          fulfillment_context=fulfillment_json,
        )
        driver_signature = build_revenue_driver_signature(financials_year1_json)
        guardrail_acknowledged = (
          get_acknowledged_signature(str(draft_id).strip()) == driver_signature
        )
        guardrail_triggered = bool(guardrail_signals.get("triggered")) and not guardrail_acknowledged
      except Exception:
        pass
      def _coerce_wage(value: Any) -> Optional[float]:
        try:
          return float(value)
        except Exception:
          return None

      def _people_key(item: Dict[str, Any]) -> str:
        name = str(item.get("full_name") or "").strip().lower()
        title = str(item.get("role_title") or "").strip().lower()
        if name or title:
          return f"{name}::{title}".strip(":")
        return ""

      def _role_key(item: Dict[str, Any]) -> str:
        return str(item.get("role_title") or "").strip().lower()

      def _build_wage_map(items: List[Dict[str, Any]], key_fn) -> Dict[str, Optional[float]]:
        mapping: Dict[str, Optional[float]] = {}
        for it in items:
          if not isinstance(it, dict):
            continue
          key = key_fn(it)
          if not key:
            continue
          mapping[key] = _coerce_wage(it.get("annual_wage"))
        return mapping

      def _mark_client_overrides(
        updated_items: List[Dict[str, Any]],
        baseline_map: Dict[str, Optional[float]],
        key_fn,
      ) -> None:
        for it in updated_items:
          if not isinstance(it, dict):
            continue
          key = key_fn(it)
          if not key:
            continue
          new_wage = _coerce_wage(it.get("annual_wage"))
          if new_wage is None:
            continue
          old_wage = baseline_map.get(key)
          if old_wage is None or abs(new_wage - old_wage) > 0.01:
            it["wage_source"] = "client_override"

      try:
        baseline_people_list = (
          baseline_people_json.get("people") if isinstance(baseline_people_json, dict) else []
        )
        baseline_roles_list = (
          baseline_people_json.get("inferred_roles") if isinstance(baseline_people_json, dict) else []
        )
        if isinstance(people_json, dict):
          updated_people_list = people_json.get("people")
          updated_roles_list = people_json.get("inferred_roles")
          if isinstance(updated_people_list, list) and isinstance(baseline_people_list, list):
            _mark_client_overrides(
              updated_people_list, _build_wage_map(baseline_people_list, _people_key), _people_key
            )
          if isinstance(updated_roles_list, list) and isinstance(baseline_roles_list, list):
            _mark_client_overrides(
              updated_roles_list, _build_wage_map(baseline_roles_list, _role_key), _role_key
            )
      except Exception:
        pass

      # People/HR confirm stage: if the client counters/edits the People review, we apply
      # the patch, acknowledge briefly, and advance to Financials WITHOUT re-showing
      # roles/people again (noise). This keeps behavior scoped to People only.
      if (
        str(focus or "").strip().lower() == "people"
        and bool(people_finalize_proposed)
        and isinstance(patch, dict)
        and any(str(k).strip().lower().startswith("people.") for k in patch.keys())
      ):
        # Refresh derived People fields after edits (keeps SQL internally consistent).
        try:
          from people_roles import format_roles_summary  # type: ignore

          if isinstance(people_json, dict):
            roles_now = people_json.get("inferred_roles")
            roles_now = roles_now if isinstance(roles_now, list) else []
            people_json["inferred_roles_summary"] = format_roles_summary(roles_now)
        except Exception:
          pass

        # Render People fact templates (no {{fact:...}} placeholders) for persisted JSON.
        try:
          try:
            from fact_templates import render_fact_template  # type: ignore
          except Exception:
            from client_intake_and_finmo.fact_templates import render_fact_template  # type: ignore

          if isinstance(people_json, dict):
            business_facts_for_render = {
              "name": str(business_facts.get("name") or "").strip(),
              "address": str(business_facts.get("address") or "").strip(),
              "start_date": str(business_facts.get("start_date") or "").strip(),
            }
            shared_ctx_for_render = {
              "operating_model": ops_json,
              "target_market": market_json,
              "people_capability": people_json,
              "financials": financials_json,
            }
            ppl = people_json.get("people")
            if isinstance(ppl, list):
              for p in ppl:
                if not isinstance(p, dict):
                  continue
                for fk, fv in list(p.items()):
                  if isinstance(fv, str) and "{{fact:" in fv:
                    p[fk] = render_fact_template(
                      fv, shared_context=shared_ctx_for_render, business_facts=business_facts_for_render
                    ).strip()
            roles = people_json.get("inferred_roles")
            if isinstance(roles, list):
              for r in roles:
                if not isinstance(r, dict):
                  continue
                for fk, fv in list(r.items()):
                  if isinstance(fv, str) and "{{fact:" in fv:
                    r[fk] = render_fact_template(
                      fv, shared_context=shared_ctx_for_render, business_facts=business_facts_for_render
                    ).strip()
            shared_context["people_capability"] = people_json
        except Exception:
          pass

        next_focus = "financials"
        start_instruction = _start_instruction_for_focus(next_focus)
        turn_messages = [*messages, user_msg, {"role": "user", "content": start_instruction}]
        intake_context_next: Dict[str, Any] = {
          "client_id": client_id,
          "draft_id": str(draft_id).strip(),
          "business_name": business_facts.get("name"),
          "business_start_date": business_facts.get("start_date"),
          "address": business_facts.get("address"),
          "current_date": current_date_iso,
          "business_stage_hint": business_stage_hint,
          "shared_context": shared_context,
          "operating_model_json": ops_json,
          "target_market_json": market_json,
          "people_json": people_json,
          "financials_json": financials_json,
          "fulfillment_json": fulfillment_json,
        }
        intake_context_next["financials_year1_json"] = financials_year1_json
        intake_context_next["revenue_math_line"] = revenue_math_line
        intake_context_next["revenue_constraints_snippet"] = revenue_constraints_snippet
        intake_context_next["revenue_driver_patch"] = revenue_driver_patch
        intake_context_next["revenue_guardrail_triggered"] = guardrail_triggered
        intake_context_next["revenue_guardrail_context_signals"] = guardrail_signals.get("context_signals") or []
        intake_context_next["revenue_guardrail_product_signals"] = guardrail_signals.get("product_signals") or []

        financials_turn, financials_json = _build_financials_live_turn(
          conn=conn,
          intake_context=intake_context_next,
          conversation_messages=turn_messages,
          shared_context=shared_context,
          financials_json=financials_json,
          financials_year1_json=financials_year1_json,
          guardrail_triggered=guardrail_triggered,
        )
        next_assistant = str(financials_turn.get("assistant_message") or "").strip()
        assistant_text = f"Got it - updated.\n\nGreat, let's move on to Financials.\n\n{next_assistant}".strip()
        assistant_text = sanitize_fact_template(str(assistant_text or "").strip())
        assistant_text = _append_constraints_snippet(
          assistant_text,
          revenue_constraints_snippet,
          messages,
          force=True,
        )

        append_messages(
          conn,
          draft_id=str(draft_id).strip(),
          new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
          confirmations={"people": True},
          marketing_model_json=_refresh_marketing_model(),
          active_focus=next_focus,
          business_facts=business_facts,
          people_json=people_json,
          financials_json=financials_json,
          financials_year1_json=financials_year1_json,
          flat_fields=_finalize_flag_field("people", False),
        )
        return jsonify(
          {
            "status": "ok",
            "draft_id": str(draft_id).strip(),
            "client_id": client_id,
            "active_focus": next_focus,
            "awaiting_confirmation": False,
            "done": False,
            "action": "confirm_proceed",
            "assistant_message": assistant_text,
          }
        )
      business_type_touched = False
      if isinstance(patch, dict):
        business_type_touched = "ops.business_type" in patch
      try:
        try:
          from business_type_naics import get_naics_from_business_type  # type: ignore
        except Exception:
          from client_intake_and_finmo.business_type_naics import (  # type: ignore
            get_naics_from_business_type,
          )
        if business_type_touched:
          bt_candidates = ops_json.get("business_type_candidates")
          if not isinstance(bt_candidates, list):
            bt_candidates = []
          ops_json["business_type"] = _normalize_business_type_from_candidates(
            ops_json.get("business_type"),
            bt_candidates,
          )
        if business_type_touched:
          if ops_json.get("business_type"):
            ops_json["business_naics_6"] = get_naics_from_business_type(
              conn, ops_json.get("business_type")
            )
          else:
            ops_json["business_naics_6"] = None
          logger.warning(
            "business_type_persisted business_type=%r business_naics_6=%r",
            ops_json.get("business_type"),
            ops_json.get("business_naics_6"),
          )
        elif ops_json.get("business_type") and not ops_json.get("business_naics_6"):
          bt_candidates = ops_json.get("business_type_candidates")
          if not isinstance(bt_candidates, list):
            bt_candidates = []
          ops_json["business_type"] = _normalize_business_type_from_candidates(
            ops_json.get("business_type"),
            bt_candidates,
          )
          ops_json["business_naics_6"] = get_naics_from_business_type(
            conn, ops_json.get("business_type")
          )
      except Exception:
        if business_type_touched and "business_naics_6" not in ops_json:
          ops_json["business_naics_6"] = None
      try:
        _enrich_milestones_timing(ops_json, reference_date=current_date)
      except Exception:
        pass
      try:
        from people_roles import (  # type: ignore
          apply_oews_wages,
          apply_oews_wages_to_people,
          format_roles_summary,
        )

        people_list = people_json.get("people") if isinstance(people_json, dict) else None
        people_list = people_list if isinstance(people_list, list) else []
        if people_list:
          enriched_people = apply_oews_wages_to_people(
            conn,
            people=people_list,
            business_type=ops_json.get("business_type"),
            business_stage=ops_json.get("business_stage"),
            address_state=business_facts.get("address_state"),
            address=business_facts.get("address"),
            business_naics_6=ops_json.get("business_naics_6"),
          )
          people_json["people"] = enriched_people

        roles = people_json.get("inferred_roles") if isinstance(people_json, dict) else None
        roles = roles if isinstance(roles, list) else []
        if roles:
          enriched_roles = apply_oews_wages(
            conn,
            roles=roles,
            business_type=ops_json.get("business_type"),
            business_stage=ops_json.get("business_stage"),
            address_state=business_facts.get("address_state"),
            address=business_facts.get("address"),
            business_naics_6=ops_json.get("business_naics_6"),
          )
          people_json["inferred_roles"] = enriched_roles
          people_json["inferred_roles_summary"] = format_roles_summary(enriched_roles)
      except Exception:
        pass
      active_focus_out = focus
      status_out: str | None = None
      completed_out = False
      confirm_question_live = _detect_confirm_question(last_assistant)

      # People/HR: if we're on the People section-final confirmation step and the client
      # counters with edits, acknowledge the change and advance (do not re-show the full
      # People recap/wage proposal again).
      if (
        str(focus).strip().lower() == "people"
        and active_focus_out == focus
        and confirm_question_live == PEOPLE_CONFIRM_QUESTION
      ):
        next_focus = "financials"
        start_instruction = _start_instruction_for_focus(next_focus)
        turn_messages = [*messages, user_msg, {"role": "user", "content": start_instruction}]
        intake_context_next: Dict[str, Any] = {
          "client_id": client_id,
          "draft_id": str(draft_id).strip(),
          "business_name": business_facts.get("name"),
          "business_start_date": business_facts.get("start_date"),
          "address": business_facts.get("address"),
          "current_date": current_date_iso,
          "business_stage_hint": business_stage_hint,
          "shared_context": shared_context,
          "operating_model_json": ops_json,
          "target_market_json": market_json,
          "people_json": people_json,
          "financials_json": financials_json,
          "fulfillment_json": fulfillment_json,
        }
        intake_context_next["financials_year1_json"] = financials_year1_json
        intake_context_next["revenue_math_line"] = revenue_math_line
        intake_context_next["revenue_constraints_snippet"] = revenue_constraints_snippet
        intake_context_next["revenue_driver_patch"] = revenue_driver_patch
        intake_context_next["revenue_guardrail_triggered"] = guardrail_triggered
        intake_context_next["revenue_guardrail_context_signals"] = guardrail_signals.get("context_signals") or []
        intake_context_next["revenue_guardrail_product_signals"] = guardrail_signals.get("product_signals") or []

        financials_turn, financials_json = _build_financials_live_turn(
          conn=conn,
          intake_context=intake_context_next,
          conversation_messages=turn_messages,
          shared_context=shared_context,
          financials_json=financials_json,
          financials_year1_json=financials_year1_json,
          guardrail_triggered=guardrail_triggered,
        )
        next_assistant = str(financials_turn.get("assistant_message") or "").strip()
        next_assistant = sanitize_fact_template(str(next_assistant or "").strip())
        next_assistant = _append_constraints_snippet(
          next_assistant,
          revenue_constraints_snippet,
          messages,
          force=True,
        )
        assistant_text = f"Got it, updated.\n\nGreat, let's move on to Financials.\n\n{next_assistant}".strip()

        append_messages(
          conn,
          draft_id=str(draft_id).strip(),
          new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
          people_json=people_json,
          financials_json=financials_json,
          marketing_model_json=_refresh_marketing_model(),
          active_focus=next_focus,
          confirmations={"people": True},
          business_facts=business_facts,
          flat_fields=_finalize_flag_field("people", True),
        )
        return jsonify(
          {
            "status": "ok",
            "draft_id": str(draft_id).strip(),
            "client_id": client_id,
            "active_focus": next_focus,
            "awaiting_confirmation": False,
            "done": False,
            "action": "confirm_proceed",
            "assistant_message": assistant_text,
          }
        )

      # If the draft was already marked complete, edits must reopen the affected
      # section so the persisted SQL state stays authoritative again.
      if str(draft_status).strip().lower() == "completed" or focus == "done":
        status_out = "in_progress"
        patch_focus = next(
          (
            str(key).split(".", 1)[0].strip().lower()
            for key in (patch or {}).keys()
            if str(key).count(".") == 1
            and str(key).split(".", 1)[0].strip().lower() in {"ops", "market", "people", "financials"}
          ),
          "",
        )
        active_focus_out = patch_focus or ("financials" if focus == "done" else focus)

      # For edit patches, the intent router is used only to interpret intent and
      # produce the deterministic patch. The domain consultant generates the next
      # conversational turn. Showing both messages causes duplicated acknowledgements
      # and repeated questions.
      #
      # Exception: if the edit re-opens a completed intake into final review, keep the
      # router acknowledgement so the user clearly sees the update before the audit.
      assistant_text = router_msg if (confirm_question_live or active_focus_out != focus) else ""
      # If we're awaiting a section-final confirmation, re-ask the confirm question
      if confirm_question_live:
        assistant_text = f"{assistant_text}\n\n{confirm_question_live}".strip()
      else:
        # Otherwise, keep the intake moving: acknowledge the edit and then continue
        # with the next question for the current focus (no standstills).
        shared_context_live = dict(shared_context or {})
        shared_context_live["operating_model"] = ops_json
        shared_context_live["target_market"] = market_json
        shared_context_live["people_capability"] = people_json
        shared_context_live["financials"] = financials_json

        intake_context_followup = {
          "client_id": client_id,
          "draft_id": str(draft_id).strip(),
          "business_name": business_facts.get("name"),
          "business_start_date": business_facts.get("start_date"),
          "address": business_facts.get("address"),
          "address_street": payload.get("address_street"),
          "address_city": payload.get("address_city"),
          "address_state": payload.get("address_state"),
          "address_zip": payload.get("address_zip"),
          "address_country": payload.get("address_country"),
          "current_date": current_date_iso,
          "business_stage_hint": business_stage_hint,
          "shared_context": shared_context_live,
          "operating_model_json": ops_json,
          "target_market_json": market_json,
          "people_json": people_json,
          "financials_json": financials_json,
          "fulfillment_json": fulfillment_json,
        }
        intake_context_followup["financials_year1_json"] = financials_year1_json
        intake_context_followup["revenue_math_line"] = revenue_math_line
        intake_context_followup["revenue_constraints_snippet"] = revenue_constraints_snippet
        intake_context_followup["revenue_driver_patch"] = revenue_driver_patch
        intake_context_followup["revenue_guardrail_triggered"] = guardrail_triggered
        intake_context_followup["revenue_guardrail_context_signals"] = guardrail_signals.get("context_signals") or []
        intake_context_followup["revenue_guardrail_product_signals"] = guardrail_signals.get("product_signals") or []

        followup_focus = active_focus_out if active_focus_out != "done" else focus
        if followup_focus == "market":
          consumer_type = str((ops_json or {}).get("consumer_type") or "consumer").strip().lower()
          if consumer_type not in ("consumer", "b2b", "mixed"):
            consumer_type = "consumer"
          intake_context_followup["consumer_type"] = consumer_type

        if followup_focus == "ops":
          followup_turn = consultant_chat_turn(
            intake_context=intake_context_followup, conversation_messages=[*messages, user_msg]
          )
        elif followup_focus == "market":
          followup_turn = target_market_chat_turn(
            intake_context=intake_context_followup, conversation_messages=[*messages, user_msg]
          )
        elif followup_focus == "people":
          followup_turn = people_capability_chat_turn(
            intake_context=intake_context_followup, conversation_messages=[*messages, user_msg]
          )
        elif followup_focus == "financials":
          followup_turn, financials_json = _build_financials_live_turn(
            conn=conn,
            intake_context=intake_context_followup,
            conversation_messages=[*messages, user_msg],
            shared_context=shared_context,
            financials_json=financials_json,
            financials_year1_json=financials_year1_json,
            guardrail_triggered=guardrail_triggered,
          )
          if bool((followup_turn or {}).get("transition_to_done")):
            assistant_final = str((followup_turn or {}).get("assistant_message") or "").strip()
            _persist_intake_completion(
              new_messages=[user_msg, {"role": "assistant", "content": assistant_final}],
              ops_value=ops_json,
              market_value=market_json,
              people_value=people_json,
              financials_value=financials_json,
              financials_year1_value=financials_year1_json,
              marketing_value=_refresh_marketing_model(),
              confirmations_value={"financials": True},
              flat_fields_value=_finalize_flag_field("financials", True),
            )
            return jsonify(
              {
                "status": "ok",
                "draft_id": str(draft_id).strip(),
                "client_id": client_id,
                "active_focus": "done",
                "awaiting_confirmation": False,
                "done": True,
                "action": "intake_complete",
                "assistant_message": assistant_final,
              }
            )
        else:
          followup_turn = {"assistant_message": ""}

        if followup_focus == "ops":
          ops_json = _apply_model_ops_patch(
            ops_json, followup_turn.get("patch") if isinstance(followup_turn, dict) else None
          )
          try:
            shared_context["operating_model"] = ops_json
          except Exception:
            pass

        followup_text = sanitize_fact_template(str(followup_turn.get("assistant_message") or "").strip())
        if focus == "market":
          followup_text = _strip_acs_codes(followup_text)
        if followup_focus == "financials":
          followup_text = _append_constraints_snippet(
            followup_text,
            revenue_constraints_snippet,
            messages,
            force=True,
          )
        if followup_focus == "ops" and not followup_text:
          followup_text = _fallback_ops_followup_question(ops_json)
        if followup_focus == "ops":
          followup_finalize_ready = bool(followup_turn.get("finalize_ready", False))
          followup_attempts_finalize = (
            followup_finalize_ready
            or (OPS_CONFIRM_QUESTION.lower() in str(followup_text or "").lower())
          )
          if followup_attempts_finalize:
            if not str((ops_json or {}).get("competitive_advantage") or "").strip():
              confirmed_restatement = _extract_confirmed_restatement(messages)
              proposed_advantage = _propose_ops_competitive_advantage(
                ops_json=ops_json,
                business_facts=business_facts,
                shared_context=shared_context,
                confirmed_restatement=confirmed_restatement,
              )
              proposed_advantage = sanitize_fact_template(str(proposed_advantage or "").strip())
              assistant_text = (
                f"{COMPETITIVE_ADVANTAGE_PREFIX} {proposed_advantage}\n\n"
                f"{COMPETITIVE_ADVANTAGE_QUESTION}"
              ).strip()
              append_messages(
                conn,
                draft_id=str(draft_id).strip(),
                new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
                operating_model_json=ops_json,
                marketing_model_json=_refresh_marketing_model(),
                active_focus="ops",
                business_facts=business_facts,
                pending_ops_milestone_json=pending_ops_milestone,
                flat_fields=_finalize_flag_field("ops", False),
              )
              return jsonify(
                {
                  "status": "ok",
                  "draft_id": str(draft_id).strip(),
                  "client_id": client_id,
                  "active_focus": "ops",
                  "awaiting_confirmation": True,
                  "done": False,
                  "action": "continue",
                  "assistant_message": assistant_text,
                }
              )

            if (
              str((ops_json or {}).get("competitive_advantage") or "").strip()
              and not _has_confirmed_milestone(ops_json)
              and not pending_ops_milestone
            ):
              assistant_text = OPS_MILESTONE_QUESTION
              pending_ops_milestone = True
              append_messages(
                conn,
                draft_id=str(draft_id).strip(),
                new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
                operating_model_json=ops_json,
                marketing_model_json=_refresh_marketing_model(),
                active_focus="ops",
                business_facts=business_facts,
                pending_ops_milestone_json=True,
                flat_fields=_finalize_flag_field("ops", False),
              )
              return jsonify(
                {
                  "status": "ok",
                  "draft_id": str(draft_id).strip(),
                  "client_id": client_id,
                  "active_focus": "ops",
                  "awaiting_confirmation": False,
                  "done": False,
                  "action": "continue",
                  "assistant_message": assistant_text,
                }
              )

            business_type_candidates = ops_json.get("business_type_candidates")
            if not isinstance(business_type_candidates, list):
              business_type_candidates = []
            intake_context_followup["business_type_candidates"] = business_type_candidates
            final_messages = [*messages, user_msg, {"role": "assistant", "content": followup_text}]
            final_obj = consultant_finalize(
              intake_context=intake_context_followup, conversation_messages=final_messages
            )
            for k, v in list(final_obj.items() if isinstance(final_obj, dict) else []):
              if isinstance(v, str):
                final_obj[k] = sanitize_fact_template(v)
            existing_advantage = str((ops_json or {}).get("competitive_advantage") or "").strip()
            if (
              existing_advantage
              and isinstance(final_obj, dict)
              and not str(final_obj.get("competitive_advantage") or "").strip()
            ):
              final_obj["competitive_advantage"] = existing_advantage
            try:
              try:
                from business_type_naics import get_naics_from_business_type  # type: ignore
              except Exception:
                from client_intake_and_finmo.business_type_naics import (  # type: ignore
                  get_naics_from_business_type,
                )
              if final_obj.get("business_type"):
                final_obj["business_naics_6"] = get_naics_from_business_type(
                  conn, final_obj.get("business_type")
                )
            except Exception:
              if "business_naics_6" not in final_obj:
                final_obj["business_naics_6"] = None
            try:
              _enrich_milestones_timing(final_obj, reference_date=current_date)
            except Exception:
              pass

            ops_json = final_obj
            try:
              shared_context = dict(shared_context or {})
              shared_context["operating_model"] = ops_json
              shared_context["target_market"] = market_json
              shared_context["people_capability"] = people_json
              shared_context["financials"] = financials_json
            except Exception:
              pass

            next_focus = "market"
            start_instruction = _start_instruction_for_focus(next_focus)
            turn_messages = [*messages, user_msg, {"role": "user", "content": start_instruction}]
            intake_context_next: Dict[str, Any] = {
              "client_id": client_id,
              "draft_id": str(draft_id).strip(),
              "business_name": business_facts.get("name"),
              "business_start_date": business_facts.get("start_date"),
              "address": business_facts.get("address"),
              "current_date": current_date_iso,
              "business_stage_hint": business_stage_hint,
              "shared_context": shared_context,
              "operating_model_json": ops_json,
              "target_market_json": market_json,
              "people_json": people_json,
              "financials_json": financials_json,
              "fulfillment_json": fulfillment_json,
            }
            consumer_type = str((ops_json or {}).get("consumer_type") or "consumer").strip().lower()
            if consumer_type not in ("consumer", "b2b", "mixed"):
              consumer_type = "consumer"
            intake_context_next["consumer_type"] = consumer_type
            market_turn = target_market_chat_turn(
              intake_context=intake_context_next, conversation_messages=turn_messages
            )
            next_assistant = str((market_turn or {}).get("assistant_message") or "").strip()
            assistant_text = f"Great, let's move on to Target Market.\n\n{next_assistant}".strip()
            assistant_text = _strip_acs_codes(sanitize_fact_template(str(assistant_text or "").strip()))

            append_messages(
              conn,
              draft_id=str(draft_id).strip(),
              new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
              operating_model_json=ops_json,
              target_market_json=market_json,
              marketing_model_json=_refresh_marketing_model(),
              active_focus=next_focus,
              confirmations={"ops": True},
              business_facts=business_facts,
              flat_fields=_finalize_flag_field("ops", True),
            )
            return jsonify(
              {
                "status": "ok",
                "draft_id": str(draft_id).strip(),
                "client_id": client_id,
                "active_focus": next_focus,
                "awaiting_confirmation": False,
                "done": False,
                "action": "confirm_proceed",
                "assistant_message": assistant_text,
              }
            )
        if followup_text:
          if assistant_text:
            assistant_text = f"{assistant_text}\n\n{followup_text}".strip()
          else:
            assistant_text = followup_text
      assistant_text = sanitize_fact_template(str(assistant_text or "").strip())
      if focus == "market":
        assistant_text = _strip_acs_codes(assistant_text)
      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
        operating_model_json=ops_json,
        target_market_json=market_json,
        people_json=people_json if people_patch_applied else None,
        financials_json=financials_json,
        financials_year1_json=financials_year1_json,
        fulfillment_json=fulfillment_json,
        marketing_model_json=_refresh_marketing_model(),
        active_focus=active_focus_out,
        business_facts=business_facts,
        status=status_out,
        completed=completed_out,
        pending_ops_milestone_json=pending_ops_milestone
        if str(active_focus_out).strip().lower() == "ops"
        else None,
        flat_fields=_finalize_flag_field(focus, False),
      )

      action_out = "edit_patch"
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": active_focus_out,
          "awaiting_confirmation": bool(confirm_question_live),
          "done": bool(active_focus_out == "done"),
          "action": action_out,
          "assistant_message": assistant_text,
        }
      )

    if action == "confirm_proceed":
      confirmations: Dict[str, bool] = {focus: True}
      next_focus = _next_focus(focus)

      # Generate the first question for the next focus immediately.
      start_instruction = _start_instruction_for_focus(next_focus)
      turn_messages = [*messages, user_msg, {"role": "user", "content": start_instruction}]
      intake_context_next: Dict[str, Any] = {
        "client_id": client_id,
        "draft_id": str(draft_id).strip(),
        "business_name": business_facts.get("name"),
        "business_start_date": business_facts.get("start_date"),
        "address": business_facts.get("address"),
        "consumer_type": (ops_json or {}).get("consumer_type"),
        "current_date": current_date_iso,
        "business_stage_hint": business_stage_hint,
        "shared_context": shared_context,
      }
      intake_context_next["financials_year1_json"] = financials_year1_json
      intake_context_next["revenue_math_line"] = revenue_math_line
      intake_context_next["revenue_constraints_snippet"] = revenue_constraints_snippet
      intake_context_next["revenue_driver_patch"] = revenue_driver_patch
      intake_context_next["revenue_guardrail_triggered"] = guardrail_triggered
      intake_context_next["revenue_guardrail_context_signals"] = guardrail_signals.get("context_signals") or []
      intake_context_next["revenue_guardrail_product_signals"] = guardrail_signals.get("product_signals") or []

      if next_focus == "ops":
        next_assistant = consultant_chat_turn(
          intake_context=intake_context_next, conversation_messages=turn_messages
        )["assistant_message"]
      elif next_focus == "market":
        market_turn = target_market_chat_turn(
          intake_context=intake_context_next, conversation_messages=turn_messages
        )
        next_assistant = str((market_turn or {}).get("assistant_message") or "").strip()
      elif next_focus == "people":
        next_assistant = people_capability_chat_turn(
          intake_context=intake_context_next, conversation_messages=turn_messages
        )["assistant_message"]
      elif next_focus == "financials":
        financials_turn, financials_json = _build_financials_live_turn(
          conn=conn,
          intake_context=intake_context_next,
          conversation_messages=turn_messages,
          shared_context=shared_context,
          financials_json=financials_json,
          financials_year1_json=financials_year1_json,
          guardrail_triggered=guardrail_triggered,
        )
        next_assistant = str(financials_turn.get("assistant_message") or "").strip()
      else:
        next_assistant = "Continue."

      transition = ""
      if next_focus == "market":
        transition = "Great, let's move on to Target Market."
      elif next_focus == "people":
        transition = "Great, let's move on to Human Resources."
      elif next_focus == "financials":
        transition = "Great, let's move on to Financials."
      elif next_focus == "done":
        transition = ""
      if transition:
        next_assistant = f"{transition}\n\n{next_assistant}".strip() if next_assistant else transition

      next_assistant = sanitize_fact_template(str(next_assistant or "").strip())
      if next_focus == "market":
        next_assistant = _strip_acs_codes(next_assistant)
      if next_focus == "financials":
        next_assistant = _append_constraints_snippet(
          next_assistant,
          revenue_constraints_snippet,
          messages,
          force=True,
        )

      if next_focus == "done":
        next_assistant = str(next_assistant or "").strip() or "Intake complete."
        _persist_intake_completion(
          new_messages=[user_msg, {"role": "assistant", "content": next_assistant}],
          ops_value=ops_json,
          market_value=market_json,
          people_value=people_json,
          financials_value=financials_json,
          financials_year1_value=financials_year1_json,
          marketing_value=_refresh_marketing_model(),
          confirmations_value=confirmations,
          flat_fields_value=_finalize_flag_field(focus, False),
        )
        return jsonify(
          {
            "status": "ok",
            "draft_id": str(draft_id).strip(),
            "client_id": client_id,
            "active_focus": "done",
            "awaiting_confirmation": False,
            "done": True,
            "action": "intake_complete",
            "assistant_message": next_assistant,
          }
        )

      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": next_assistant}],
        confirmations=confirmations,
        operating_model_json=ops_json if next_focus == "done" else None,
        marketing_model_json=marketing_model_json if next_focus == "done" else _refresh_marketing_model(),
        active_focus=next_focus,
        business_facts=business_facts,
        target_market_json=market_json if next_focus in {"market", "done"} else None,
        people_json=people_json if next_focus == "done" else None,
        financials_json=financials_json if next_focus in {"financials", "done"} else None,
        financials_year1_json=financials_year1_json if next_focus == "done" else None,
        flat_fields=_finalize_flag_field(focus, False),
        status="completed" if next_focus == "done" else None,
        completed=bool(next_focus == "done"),
      )

      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": next_focus,
          "awaiting_confirmation": False,
          "done": bool(next_focus == "done"),
          "action": "confirm_proceed",
          "assistant_message": next_assistant,
        }
      )

    if action == "confirm_clarify":
      assistant_text = sanitize_fact_template(router_msg)
      if focus == "market":
        assistant_text = _strip_acs_codes(assistant_text)
      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
        target_market_json=market_json if focus == "market" else None,
        marketing_model_json=_refresh_marketing_model(),
        active_focus=focus,
        business_facts=business_facts,
        pending_ops_milestone_json=pending_ops_milestone if focus == "ops" else None,
        flat_fields=_finalize_flag_field(focus, False),
      )
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": focus,
          "awaiting_confirmation": bool(confirm_question),
          "done": False,
          "action": "confirm_clarify",
          "assistant_message": assistant_text,
        }
      )

    if action == "answer_readonly":
      assistant_text = sanitize_fact_template(router_msg)
      if focus == "market":
        assistant_text = _strip_acs_codes(assistant_text)
      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
        target_market_json=market_json if focus == "market" else None,
        marketing_model_json=_refresh_marketing_model(),
        active_focus=focus,
        business_facts=business_facts,
        pending_ops_milestone_json=pending_ops_milestone if focus == "ops" else None,
        flat_fields=_finalize_flag_field(focus, False),
      )
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": focus,
          "awaiting_confirmation": bool(confirm_question),
          "done": False,
          "action": "answer_readonly",
          "assistant_message": assistant_text,
        }
      )

    # continue_chat: run the current focus consult normally.
    intake_context = {
      "client_id": client_id,
      "draft_id": str(draft_id).strip(),
      "business_name": business_facts.get("name"),
      "business_start_date": business_facts.get("start_date"),
      "address": business_facts.get("address"),
      "address_street": payload.get("address_street"),
      "address_city": payload.get("address_city"),
      "address_state": payload.get("address_state"),
      "address_zip": payload.get("address_zip"),
      "address_country": payload.get("address_country"),
      "current_date": current_date_iso,
      "business_stage_hint": business_stage_hint,
      "shared_context": shared_context,
      "operating_model_json": ops_json,
      "target_market_json": market_json,
      "people_json": people_json,
      "financials_json": financials_json,
      "fulfillment_json": fulfillment_json,
    }
    intake_context["financials_year1_json"] = financials_year1_json
    intake_context["revenue_math_line"] = revenue_math_line
    intake_context["revenue_constraints_snippet"] = revenue_constraints_snippet
    intake_context["revenue_driver_patch"] = revenue_driver_patch
    intake_context["revenue_guardrail_triggered"] = guardrail_triggered
    intake_context["revenue_guardrail_context_signals"] = guardrail_signals.get("context_signals") or []
    intake_context["revenue_guardrail_product_signals"] = guardrail_signals.get("product_signals") or []
    if focus == "market":
      consumer_type = str((ops_json or {}).get("consumer_type") or "consumer").strip().lower()
      if consumer_type not in ("consumer", "b2b", "mixed"):
        consumer_type = "consumer"
      intake_context["consumer_type"] = consumer_type
    if focus == "ops":
      turn = consultant_chat_turn(
        intake_context=intake_context, conversation_messages=[*messages, user_msg]
      )
    elif focus == "market":
      turn = target_market_chat_turn(
        intake_context=intake_context, conversation_messages=[*messages, user_msg]
      )
    elif focus == "people":
      turn = people_capability_chat_turn(
        intake_context=intake_context, conversation_messages=[*messages, user_msg]
      )
    elif focus == "financials":
      turn, financials_json = _build_financials_live_turn(
        conn=conn,
        intake_context=intake_context,
        conversation_messages=[*messages, user_msg],
        shared_context=shared_context,
        financials_json=financials_json,
        financials_year1_json=financials_year1_json,
        guardrail_triggered=guardrail_triggered,
      )
    else:
      turn = {"assistant_message": "Continue.", "finalize_ready": False}

    assistant_text = sanitize_fact_template(str(turn.get("assistant_message") or "").strip())
    if focus == "market":
      assistant_text = _strip_acs_codes(assistant_text)
    if focus == "financials":
      assistant_text = _append_constraints_snippet(
        assistant_text,
        revenue_constraints_snippet,
        messages,
        force=True,
      )

    # Ops: apply model-produced structured patch immediately (no controller parsing).
    if str(focus).strip().lower() == "ops" and isinstance(turn, dict):
      ops_json = _apply_model_ops_patch(ops_json, turn.get("patch"))
      try:
        shared_context["operating_model"] = ops_json
      except Exception:
        pass

    # Target Market: apply model-produced structured patch immediately (no controller parsing).
    if str(focus).strip().lower() == "market" and isinstance(turn, dict):
      patch_obj = turn.get("patch")
      if isinstance(patch_obj, dict) and isinstance(market_json, dict):
        allowed_keys = {
          "consumer_type",
          "gender_age_intent",
          "income_intent",
          "b2b_industry_terms",
          "b2b_size_bands",
          "b2b_age_bands",
        }
        for k, v in patch_obj.items():
          key = str(k or "").strip()
          if not key:
            continue
          if key.startswith("market."):
            key = key.split(".", 1)[1].strip()
          if key in allowed_keys:
            # In strict json_schema, the model must always output every patch key.
            # We treat null values as "no change" to avoid wiping prior answers.
            if v is None:
              continue
            market_json[key] = v
        try:
          shared_context["target_market"] = market_json
        except Exception:
          pass

    # People: persist raw structured person facts incrementally during collection.
    if str(focus).strip().lower() == "people":
      try:
        people_progress_context = dict(intake_context)
        people_progress_context["existing_people_capability_json"] = people_json
        extracted_people = extract_people_collection_progress(
          intake_context=people_progress_context,
          conversation_messages=[
            *messages,
            user_msg,
            {"role": "assistant", "content": assistant_text},
          ],
        )
        extracted_people_list = (
          extracted_people.get("people") if isinstance(extracted_people, dict) else None
        )
        if isinstance(extracted_people_list, list) and extracted_people_list:
          next_people_json = dict(people_json or {})
          next_people_json["people"] = extracted_people_list
          next_people_json["business_naics_6"] = ops_json.get("business_naics_6")
          people_json = next_people_json
          try:
            shared_context["people_capability"] = people_json
          except Exception:
            pass
      except Exception:
        pass

    finalize_ready = bool(turn.get("finalize_ready", False))
    review_ready = bool(turn.get("review_ready", False))
    # Controller-owned restatement-confirmation state: only classify acceptance on the
    # client reply to the explicit restatement confirmation prompt.
    if (
      str(focus).strip().lower() == "ops"
      and bool(turn.get("is_restatement_confirmation_prompt", False))
      and not bool((ops_json or {}).get("business_type_candidates_locked"))
    ):
      if isinstance(ops_json, dict):
        ops_json["_ops_restatement_pending"] = True
        ops_json["_ops_restatement_text"] = assistant_text
      ops_restatement_meta_touched = True
    if str(focus).strip().lower() == "people" and review_ready and not finalize_ready:
      finalize_ready = True
    if str(focus).strip().lower() == "financials":
      finalize_ready = False

    if str(focus).strip().lower() == "ops" and assistant_text:
      question_count = assistant_text.count("?")
      if question_count > 1:
        first_part = assistant_text.split("?", 1)[0].strip()
        if first_part:
          assistant_text = f"{first_part}?"
        finalize_ready = False
      # If the Ops consultant produced the section-final confirm question in normal chat,
      # treat it as a finalize attempt so we can enforce milestone-first and then auto-advance.
      if OPS_CONFIRM_QUESTION.lower() in assistant_text.lower():
        finalize_ready = True

    ops_ready_for_wrap = False
    # Ops hard gate: do not allow the ops "finalize-ready" path (which triggers competitive
    # advantage/milestone injection and summary auto-skip) unless capacity has been captured.
    #
    # We avoid brittle heuristic phrase-matching by taking a structured snapshot via
    # consultant_finalize() and checking the numeric capacity fields directly.
    if str(focus).strip().lower() == "ops" and (finalize_ready or not assistant_text):
      try:
        gate_messages = [*messages, user_msg, {"role": "assistant", "content": assistant_text}]
        business_type_candidates = (ops_json or {}).get("business_type_candidates")
        if not isinstance(business_type_candidates, list):
          business_type_candidates = []
        gate_context = dict(intake_context)
        gate_context["business_type_candidates"] = business_type_candidates
        gate_obj = consultant_finalize(intake_context=gate_context, conversation_messages=gate_messages)

        def _missing_number(value: Any) -> bool:
          if value is None:
            return True
          if isinstance(value, bool):
            return True
          try:
            return float(value) <= 0
          except Exception:
            return True

        def _final_obj_missing_capacity(obj: Any) -> bool:
          if not isinstance(obj, dict):
            return True
          lob_models = obj.get("lob_models")
          products: List[Dict[str, Any]] = []
          if isinstance(lob_models, list):
            for lob in lob_models:
              if not isinstance(lob, dict):
                continue
              prods = lob.get("products")
              if not isinstance(prods, list):
                continue
              for p in prods:
                if isinstance(p, dict):
                  products.append(p)
          if products:
            for p in products:
              if _missing_number(p.get("units_per_period_capacity")) and _missing_number(
                p.get("units_per_week_capacity")
              ):
                return True
            return False
          return _missing_number(obj.get("units_per_period_capacity")) and _missing_number(
            obj.get("units_per_week_capacity")
          )

        def _final_obj_missing_utilization(obj: Any) -> bool:
          if not isinstance(obj, dict):
            return True
          lob_models = obj.get("lob_models")
          products: List[Dict[str, Any]] = []
          if isinstance(lob_models, list):
            for lob in lob_models:
              if not isinstance(lob, dict):
                continue
              prods = lob.get("products")
              if not isinstance(prods, list):
                continue
              for p in prods:
                if isinstance(p, dict):
                  products.append(p)
          if products:
            for p in products:
              if _missing_number(p.get("utilization_rate")):
                return True
            return False
          return _missing_number(obj.get("utilization_rate"))

        if _final_obj_missing_capacity(gate_obj):
          capacity_target = _find_missing_capacity_target(gate_obj, fallback_ops=ops_json)
          captured_capacity = False
          numeric_capacity_value = _extract_single_compact_number(message)
          if (
            capacity_target
            and numeric_capacity_value is not None
            and _looks_like_capacity_prompt(last_assistant)
          ):
            updated_gate_obj = _apply_capacity_target_value(
              gate_obj,
              capacity_target,
              float(numeric_capacity_value),
            )
            ops_json = _apply_capacity_snapshot_to_ops_json(
              ops_json,
              updated_gate_obj,
              capacity_target,
            )
            shared_context = dict(shared_context or {})
            shared_context["operating_model"] = ops_json
            intake_context = dict(intake_context or {})
            intake_context["shared_context"] = shared_context
            intake_context["operating_model_json"] = ops_json
            gate_context = dict(gate_context or {})
            gate_context["shared_context"] = shared_context
            gate_context["operating_model_json"] = ops_json
            try:
              business_type_candidates = (ops_json or {}).get("business_type_candidates")
              if isinstance(business_type_candidates, list):
                intake_context["business_type_candidates"] = business_type_candidates
            except Exception:
              pass
            follow_up_turn = consultant_chat_turn(
              intake_context=intake_context,
              conversation_messages=[*messages, user_msg],
            ) or {}
            assistant_text = sanitize_fact_template(
              str((follow_up_turn or {}).get("assistant_message") or "").strip()
            )
            finalize_ready = bool(follow_up_turn.get("finalize_ready"))
            captured_capacity = True
          if not captured_capacity:
            if capacity_target:
              assistant_text = _build_capacity_target_question(capacity_target)
            else:
              assistant_text = (
                "To make planning realistic, in a fully busy period, about how many units do you expect you can handle?"
              ).strip()
            finalize_ready = False
        elif _final_obj_missing_utilization(gate_obj):
          def _first_product_missing_utilization(obj: Any) -> Optional[Dict[str, Any]]:
            if not isinstance(obj, dict):
              return None
            lob_models = obj.get("lob_models")
            if isinstance(lob_models, list):
              for lob in lob_models:
                if not isinstance(lob, dict):
                  continue
                products = lob.get("products")
                if not isinstance(products, list):
                  continue
                for product in products:
                  if isinstance(product, dict) and _missing_number(product.get("utilization_rate")):
                    return product
            return obj if _missing_number(obj.get("utilization_rate")) else None

          missing_product = _first_product_missing_utilization(gate_obj) or {}
          util_label = str(
            missing_product.get("product_name")
            or missing_product.get("unit_name")
            or (ops_json or {}).get("unit_name")
            or "this offering"
          ).strip()
          assistant_text = (
            f"For Year 1 planning, what average utilization do you want to assume for {util_label} "
            "(for example, 70% of practical capacity)?"
          ).strip()
          finalize_ready = False
        else:
          missing_period_product = _first_contract_product_missing_periods(gate_obj)
          if missing_period_product:
            period_label = str(
              missing_period_product.get("product_name")
              or missing_period_product.get("unit_name")
              or (ops_json or {}).get("unit_name")
              or "this contract offering"
            ).strip()
            assistant_text = (
              f"For {period_label}, about how many times does one active slot typically turn over in a year? "
              "(For example, if one matter usually lasts about 3 months, that would be about 4 turns per year.)"
            ).strip()
            finalize_ready = False
          else:
            # Competitive advantage should be second-to-last and milestones last.
            # For multi-product ops, readiness must come from the product rows plus
            # the business-wide top-level fields, not placeholder top-level unit fields.
            if _ops_ready_for_wrap_from_gate_obj(gate_obj):
              ops_ready_for_wrap = True
              finalize_ready = True
            else:
              finalize_ready = False
      except Exception:
        # Best-effort: if gating fails, preserve existing behavior.
        pass

    if str(focus).strip().lower() == "ops" and not assistant_text and not finalize_ready:
      assistant_text = _fallback_ops_followup_question(ops_json)

    if (
      str(focus).strip().lower() == "ops"
      and finalize_ready
      and ops_ready_for_wrap
      and not str((ops_json or {}).get("competitive_advantage") or "").strip()
    ):
      confirmed_restatement = _extract_confirmed_restatement(messages)
      proposed_advantage = _propose_ops_competitive_advantage(
        ops_json=ops_json,
        business_facts=business_facts,
        shared_context=shared_context,
        confirmed_restatement=confirmed_restatement,
      )
      proposed_advantage = sanitize_fact_template(str(proposed_advantage or "").strip())
      if proposed_advantage:
        assistant_text = (
          f"{COMPETITIVE_ADVANTAGE_PREFIX} {proposed_advantage}\n\n"
          f"{COMPETITIVE_ADVANTAGE_QUESTION}"
        )
        finalize_ready = False

    if (
      str(focus).strip().lower() == "ops"
      and finalize_ready
      and ops_ready_for_wrap
      and str((ops_json or {}).get("competitive_advantage") or "").strip()
      and not _has_confirmed_milestone(ops_json)
      and not pending_ops_milestone
    ):
      # Ask for milestone once, after competitive advantage is set; use a pending flag so
      # the next user reply is interpreted as an ops.milestones patch.
      assistant_text = OPS_MILESTONE_QUESTION
      finalize_ready = False
      pending_ops_milestone = True

    # Safety: avoid dead-end assistant replies with no next question.
    # If GPT responded with an acknowledgement only (no question) and we're not finalizing,
    # immediately ask for the next single question so the user isn't forced to type "ok".
    if (not finalize_ready) and assistant_text and ("?" not in assistant_text):
      continue_instruction = (
        "Continue. Ask exactly ONE next question for the client to answer (do not bundle)."
      )
      followup_messages = [
        *messages,
        user_msg,
        {"role": "assistant", "content": assistant_text},
        {"role": "user", "content": continue_instruction},
      ]
      try:
        if focus == "ops":
          followup_turn = consultant_chat_turn(
            intake_context=intake_context, conversation_messages=followup_messages
          )
        elif focus == "market":
          followup_turn = target_market_chat_turn(
            intake_context=intake_context, conversation_messages=followup_messages
          )
        elif focus == "people":
          followup_turn = people_capability_chat_turn(
            intake_context=intake_context, conversation_messages=followup_messages
          )
        elif focus == "financials":
          followup_turn, financials_json = _build_financials_live_turn(
            conn=conn,
            intake_context=intake_context,
            conversation_messages=followup_messages,
            shared_context=shared_context,
            financials_json=financials_json,
            financials_year1_json=financials_year1_json,
            guardrail_triggered=guardrail_triggered,
          )
        else:
          followup_turn = {"assistant_message": ""}
        followup_text = sanitize_fact_template(str(followup_turn.get("assistant_message") or "").strip())
        if focus == "market":
          followup_text = _strip_acs_codes(followup_text)
        if focus == "financials":
          followup_text = _append_constraints_snippet(
            followup_text,
            revenue_constraints_snippet,
            messages,
            force=True,
          )
        if followup_text:
          # If the follow-up turn indicates the consult is complete, carry that
          # completion signal forward so we finalize immediately instead of
          # returning a dead-end statement that forces the user to type "ok".
          if bool(followup_turn.get("finalize_ready", False)):
            finalize_ready = True
            assistant_text = followup_text.strip()
          else:
            assistant_text = f"{assistant_text}\n\n{followup_text}".strip()
      except Exception:
        # Best-effort; if follow-up fails, keep the original reply.
        pass

    if str(focus).strip().lower() == "financials" and bool(turn.get("transition_to_done")):
      assistant_final = str(turn.get("assistant_message") or "").strip()
      _persist_intake_completion(
        new_messages=[user_msg, {"role": "assistant", "content": assistant_final}],
        ops_value=ops_json,
        market_value=market_json,
        people_value=people_json,
        financials_value=financials_json,
        financials_year1_value=financials_year1_json,
        marketing_value=_refresh_marketing_model(),
        confirmations_value={"financials": True},
        flat_fields_value=_finalize_flag_field("financials", True),
      )
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": "done",
          "awaiting_confirmation": False,
          "done": True,
          "action": "intake_complete",
          "assistant_message": assistant_final,
        }
      )
    if not finalize_ready:
      review_people = None
      if str(focus).strip().lower() == "people" and review_ready:
        review_people = people_capability_finalize(
          intake_context=intake_context,
          conversation_messages=[*messages, user_msg, {"role": "assistant", "content": assistant_text}],
        )
        for k, v in list(review_people.items() if isinstance(review_people, dict) else []):
          if isinstance(v, str):
            review_people[k] = sanitize_fact_template(v)
        try:
          from people_roles import (  # type: ignore
            apply_oews_wages,
            apply_oews_wages_to_people,
            format_roles_summary,
          )

          roles = review_people.get("inferred_roles") if isinstance(review_people, dict) else None
          roles = roles if isinstance(roles, list) else []
          people = review_people.get("people") if isinstance(review_people, dict) else None
          people = people if isinstance(people, list) else []
          enriched_people = apply_oews_wages_to_people(
            conn,
            people=people,
            business_type=ops_json.get("business_type"),
            business_stage=ops_json.get("business_stage"),
            address_state=business_facts.get("address_state"),
            address=business_facts.get("address"),
            business_naics_6=ops_json.get("business_naics_6"),
          )
          enriched_roles = apply_oews_wages(
            conn,
            roles=roles,
            business_type=ops_json.get("business_type"),
            business_stage=ops_json.get("business_stage"),
            address_state=business_facts.get("address_state"),
            address=business_facts.get("address"),
            business_naics_6=ops_json.get("business_naics_6"),
          )
          review_people["business_naics_6"] = ops_json.get("business_naics_6")
          review_people["people"] = enriched_people
          review_people["inferred_roles"] = enriched_roles
          review_people["inferred_roles_summary"] = format_roles_summary(enriched_roles)
        except Exception:
          if isinstance(review_people, dict):
            if "inferred_roles" not in review_people:
              review_people["inferred_roles"] = []
            if "inferred_roles_summary" not in review_people:
              review_people["inferred_roles_summary"] = ""
            if "business_naics_6" not in review_people:
              review_people["business_naics_6"] = None
      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
        operating_model_json=ops_json if str(focus).strip().lower() == "ops" else None,
        target_market_json=market_json if str(focus).strip().lower() == "market" else None,
        financials_json=financials_json if focus == "financials" else None,
        marketing_model_json=_refresh_marketing_model(),
        active_focus=focus,
        business_facts=business_facts,
        financials_year1_json=financials_year1_json if focus == "financials" else None,
        pending_ops_milestone_json=pending_ops_milestone if focus == "ops" else None,
        flat_fields=_finalize_flag_field(focus, False),
        people_json=review_people if review_ready else (people_json if str(focus).strip().lower() == "people" else None),
      )
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": focus,
          "awaiting_confirmation": False,
          "done": False,
          "action": "continue",
          "assistant_message": assistant_text,
        }
      )

    # Finalize the current focus into structured JSON, then ask for confirmation.
    final_messages = [*messages, user_msg, {"role": "assistant", "content": assistant_text}]

    if focus == "ops":
      business_type_candidates = ops_json.get("business_type_candidates")
      if not isinstance(business_type_candidates, list):
        business_type_candidates = []
      intake_context["business_type_candidates"] = business_type_candidates
      final_obj = consultant_finalize(intake_context=intake_context, conversation_messages=final_messages)
      for k, v in list(final_obj.items() if isinstance(final_obj, dict) else []):
        if isinstance(v, str):
          final_obj[k] = sanitize_fact_template(v)
      existing_advantage = str((ops_json or {}).get("competitive_advantage") or "").strip()
      if (
        existing_advantage
        and isinstance(final_obj, dict)
        and not str(final_obj.get("competitive_advantage") or "").strip()
      ):
        final_obj["competitive_advantage"] = existing_advantage
      if isinstance(final_obj, dict):
        lob_models = final_obj.get("lob_models")
        if isinstance(lob_models, list) and len(lob_models) == 1:
          products = lob_models[0].get("products") if isinstance(lob_models[0], dict) else None
          if isinstance(products, list) and len(products) == 1 and isinstance(products[0], dict):
            product = products[0]

            def _is_missing_number(value: Any) -> bool:
              if value is None:
                return True
              if isinstance(value, bool):
                return True
              try:
                return float(value) <= 0
              except Exception:
                return True

            def _maybe_set_text(field: str) -> None:
              if not final_obj.get(field) and product.get(field) is not None:
                final_obj[field] = product.get(field)

            def _maybe_set_number(field: str) -> None:
              if _is_missing_number(final_obj.get(field)) and product.get(field) is not None:
                final_obj[field] = product.get(field)

            _maybe_set_text("unit_name")
            _maybe_set_text("unit_description")
            _maybe_set_text("unit_cadence")
            _maybe_set_number("unit_price")
            _maybe_set_number("units_per_week_capacity")
            _maybe_set_number("units_per_period_capacity")
            _maybe_set_number("operating_periods_per_year")
            _maybe_set_number("utilization_rate")
      # Capacity compatibility: fill missing week/period fields deterministically.
      final_obj = _normalize_ops_capacity_compat(final_obj)
      try:
        try:
          from business_type_naics import get_naics_from_business_type  # type: ignore
        except Exception:
          from client_intake_and_finmo.business_type_naics import (  # type: ignore
            get_naics_from_business_type,
          )

        if final_obj.get("business_type"):
          final_obj["business_naics_6"] = get_naics_from_business_type(
            conn, final_obj.get("business_type")
          )
      except Exception:
        if "business_naics_6" not in final_obj:
          final_obj["business_naics_6"] = None
      try:
        _enrich_milestones_timing(final_obj, reference_date=current_date)
      except Exception:
        pass

      # Persist a rendered business_description_summary (no {{fact:...}} placeholders).
      # Keep the change scoped to this single field only.
      try:
        try:
          from fact_templates import render_fact_template  # type: ignore
        except Exception:
          from client_intake_and_finmo.fact_templates import render_fact_template  # type: ignore

        if isinstance(final_obj, dict) and str(final_obj.get("business_description_summary") or "").strip():
          business_facts_for_render = {
            "name": str(business_facts.get("name") or "").strip(),
            "address": str(business_facts.get("address") or "").strip(),
            "start_date": str(business_facts.get("start_date") or "").strip(),
          }
          shared_ctx_for_render = {
            "operating_model": final_obj,
            "target_market": market_json,
            "people_capability": people_json,
            "financials": financials_json,
          }
          final_obj["business_description_summary"] = render_fact_template(
            str(final_obj.get("business_description_summary") or ""),
            shared_context=shared_ctx_for_render,
            business_facts=business_facts_for_render,
          ).strip()
      except Exception:
        pass
      # Do not show the Ops summary for confirmation. Assume affirmative and
      # advance directly to Target Market after persisting the finalized ops_json.
      if not str((ops_json or {}).get("competitive_advantage") or "").strip():
        confirmed_restatement = _extract_confirmed_restatement(messages)
        proposed_advantage = _propose_ops_competitive_advantage(
          ops_json=ops_json,
          business_facts=business_facts,
          shared_context=shared_context,
          confirmed_restatement=confirmed_restatement,
        )
        proposed_advantage = sanitize_fact_template(str(proposed_advantage or "").strip())
        assistant_text = (
          f"{COMPETITIVE_ADVANTAGE_PREFIX} {proposed_advantage}\n\n"
          f"{COMPETITIVE_ADVANTAGE_QUESTION}"
        ).strip()
        append_messages(
          conn,
          draft_id=str(draft_id).strip(),
          new_messages=[user_msg, {"role": "assistant", "content": assistant_text}],
          operating_model_json=ops_json,
          marketing_model_json=_refresh_marketing_model(),
          active_focus="ops",
          business_facts=business_facts,
          pending_ops_milestone_json=pending_ops_milestone,
          flat_fields=_finalize_flag_field("ops", False),
        )
        return jsonify(
          {
            "status": "ok",
            "draft_id": str(draft_id).strip(),
            "client_id": client_id,
            "active_focus": "ops",
            "awaiting_confirmation": True,
            "done": False,
            "action": "continue",
            "assistant_message": assistant_text,
          }
        )

      ops_json = final_obj
      try:
        shared_context = dict(shared_context or {})
        shared_context["operating_model"] = ops_json
        shared_context["target_market"] = market_json
        shared_context["people_capability"] = people_json
        shared_context["financials"] = financials_json
      except Exception:
        pass

      next_focus = "market"
      start_instruction = _start_instruction_for_focus(next_focus)
      turn_messages = [*messages, user_msg, {"role": "user", "content": start_instruction}]
      intake_context_next: Dict[str, Any] = {
        "client_id": client_id,
        "draft_id": str(draft_id).strip(),
        "business_name": business_facts.get("name"),
        "business_start_date": business_facts.get("start_date"),
        "address": business_facts.get("address"),
        "current_date": current_date_iso,
        "business_stage_hint": business_stage_hint,
        "shared_context": shared_context,
        "operating_model_json": ops_json,
        "target_market_json": market_json,
        "people_json": people_json,
        "financials_json": financials_json,
        "fulfillment_json": fulfillment_json,
      }
      consumer_type = str((ops_json or {}).get("consumer_type") or "consumer").strip().lower()
      if consumer_type not in ("consumer", "b2b", "mixed"):
        consumer_type = "consumer"
      intake_context_next["consumer_type"] = consumer_type
      market_turn = target_market_chat_turn(
        intake_context=intake_context_next, conversation_messages=turn_messages
      )
      next_assistant = str((market_turn or {}).get("assistant_message") or "").strip()
      assistant_final = f"Great, let's move on to Target Market.\n\n{next_assistant}".strip()
      assistant_final = _strip_acs_codes(sanitize_fact_template(str(assistant_final or "").strip()))

      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": assistant_final}],
        operating_model_json=ops_json,
        target_market_json=market_json,
        marketing_model_json=_refresh_marketing_model(),
        active_focus=next_focus,
        confirmations={"ops": True},
        business_facts=business_facts,
        flat_fields=_finalize_flag_field("ops", True),
      )
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": next_focus,
          "awaiting_confirmation": False,
          "done": False,
          "action": "confirm_proceed",
          "assistant_message": assistant_final,
        }
      )
    elif focus == "market":
      consumer_type = str((ops_json or {}).get("consumer_type") or "consumer").strip().lower()
      mapping_rows: List[Dict[str, Any]] = []
      if consumer_type != "b2b":
        mapping_rows = _fetch_target_market_mapping_rows(conn)
      final_obj = target_market_finalize(
        intake_context={**intake_context, "consumer_type": consumer_type},
        conversation_messages=final_messages,
        mapping_rows=mapping_rows,
      )
      for k, v in list(final_obj.items() if isinstance(final_obj, dict) else []):
        if isinstance(v, str):
          final_obj[k] = sanitize_fact_template(v)
      if isinstance(final_obj, dict):
        final_obj.pop("target_market_summary", None)
        final_obj.pop("_pending_income_intent", None)
        final_obj.pop("_pending_capture_field", None)
        final_obj.pop("_pending_gender_focus", None)
        final_obj.pop("_pending_age_range", None)

      # Persist a rendered marketing_plan_summary (no {{fact:...}} placeholders).
      # Keep the change scoped to this single field only.
      try:
        try:
          from fact_templates import render_fact_template  # type: ignore
        except Exception:
          from client_intake_and_finmo.fact_templates import render_fact_template  # type: ignore

        if isinstance(final_obj, dict) and str(final_obj.get("marketing_plan_summary") or "").strip():
          business_facts_for_render = {
            "name": str(business_facts.get("name") or "").strip(),
            "address": str(business_facts.get("address") or "").strip(),
            "start_date": str(business_facts.get("start_date") or "").strip(),
          }
          shared_ctx_for_render = {
            "operating_model": ops_json,
            "target_market": final_obj,
            "people_capability": people_json,
            "financials": financials_json,
          }
          final_obj["marketing_plan_summary"] = render_fact_template(
            str(final_obj.get("marketing_plan_summary") or ""),
            shared_context=shared_ctx_for_render,
            business_facts=business_facts_for_render,
          ).strip()
      except Exception:
        pass
      market_json = final_obj

      # Show the finalized marketing_plan_summary to the client for confirmation/counter
      # before advancing. This replaces the older in-chat "promotion model" proposal.
      assistant_final = sanitize_fact_template(
        str((market_json or {}).get("marketing_plan_summary") or "").strip()
      )
      assistant_final = _strip_acs_codes(assistant_final)
      assistant_final = f"{assistant_final}\n\n{MARKET_CONFIRM_QUESTION}".strip()

      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": assistant_final}],
        target_market_json=market_json,
        marketing_model_json=_refresh_marketing_model(),
        active_focus="market",
        business_facts=business_facts,
        flat_fields=_finalize_flag_field("market", True),
      )
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": "market",
          "awaiting_confirmation": True,
          "done": False,
          "action": "continue",
          "assistant_message": assistant_final,
        }
      )
    elif focus == "people":
      final_obj = people_capability_finalize(intake_context=intake_context, conversation_messages=final_messages)
      for k, v in list(final_obj.items() if isinstance(final_obj, dict) else []):
        if isinstance(v, str):
          final_obj[k] = sanitize_fact_template(v)
      try:
        from people_roles import (  # type: ignore
          apply_oews_wages,
          apply_oews_wages_to_people,
          format_roles_summary,
        )

        roles = final_obj.get("inferred_roles") if isinstance(final_obj, dict) else None
        roles = roles if isinstance(roles, list) else []
        people_list = final_obj.get("people") if isinstance(final_obj, dict) else None
        people_list = people_list if isinstance(people_list, list) else []
        enriched_people = apply_oews_wages_to_people(
          conn,
          people=people_list,
          business_type=ops_json.get("business_type"),
          business_stage=ops_json.get("business_stage"),
          address_state=business_facts.get("address_state"),
          address=business_facts.get("address"),
          business_naics_6=ops_json.get("business_naics_6"),
        )
        enriched_roles = apply_oews_wages(
          conn,
          roles=roles,
          business_type=ops_json.get("business_type"),
          business_stage=ops_json.get("business_stage"),
          address_state=business_facts.get("address_state"),
          address=business_facts.get("address"),
          business_naics_6=ops_json.get("business_naics_6"),
        )
        final_obj["business_naics_6"] = ops_json.get("business_naics_6")
        final_obj["people"] = enriched_people
        final_obj["inferred_roles"] = enriched_roles
        final_obj["inferred_roles_summary"] = format_roles_summary(enriched_roles)
      except Exception:
        if "inferred_roles" not in final_obj:
          final_obj["inferred_roles"] = []
        if "inferred_roles_summary" not in final_obj:
          final_obj["inferred_roles_summary"] = ""
        if "business_naics_6" not in final_obj:
          final_obj["business_naics_6"] = None

      # People/HR: show a one-time review (key people + inferred roles) and ask for
      # confirmation. If the client counters, we acknowledge and advance without
      # re-showing this review again.
      if isinstance(final_obj, dict):
        final_obj.pop("key_people_summary", None)
      people_json = final_obj

      # Render People fact templates (no {{fact:...}} placeholders) for display + persistence.
      try:
        try:
          from fact_templates import render_fact_template  # type: ignore
        except Exception:
          from client_intake_and_finmo.fact_templates import render_fact_template  # type: ignore

        if isinstance(people_json, dict):
          business_facts_for_render = {
            "name": str(business_facts.get("name") or "").strip(),
            "address": str(business_facts.get("address") or "").strip(),
            "start_date": str(business_facts.get("start_date") or "").strip(),
          }
          shared_ctx_for_render = {
            "operating_model": ops_json,
            "target_market": market_json,
            "people_capability": people_json,
            "financials": financials_json,
          }
          ppl = people_json.get("people")
          if isinstance(ppl, list):
            for p in ppl:
              if not isinstance(p, dict):
                continue
              for fk, fv in list(p.items()):
                if isinstance(fv, str) and "{{fact:" in fv:
                  p[fk] = render_fact_template(
                    fv, shared_context=shared_ctx_for_render, business_facts=business_facts_for_render
                  ).strip()
          roles = people_json.get("inferred_roles")
          if isinstance(roles, list):
            for r in roles:
              if not isinstance(r, dict):
                continue
              for fk, fv in list(r.items()):
                if isinstance(fv, str) and "{{fact:" in fv:
                  r[fk] = render_fact_template(
                    fv, shared_context=shared_ctx_for_render, business_facts=business_facts_for_render
                  ).strip()
      except Exception:
        pass

      key_people_blocks: List[str] = []
      try:
        people_list = people_json.get("people") if isinstance(people_json, dict) else None
        people_list = people_list if isinstance(people_list, list) else []
        for p in people_list:
          if not isinstance(p, dict):
            continue
          para = p.get("paragraph")
          if isinstance(para, str) and para.strip():
            block = para.strip()
            wage_raw = p.get("annual_wage")
            try:
              wage_val = float(wage_raw)
            except Exception:
              wage_val = None
            if wage_val is not None and wage_val > 0:
              wage_fmt = f"${int(round(wage_val)):,.0f}"
              # Keep wage visible to the client, but embedded in the narrative (no standalone line).
              block = f"{block.rstrip()} Estimated annual wage: {wage_fmt}/year."
            key_people_blocks.append(block)
      except Exception:
        key_people_blocks = []

      inferred_roles_summary = str((people_json or {}).get("inferred_roles_summary") or "").strip()
      parts: List[str] = []
      has_people = bool(key_people_blocks)
      has_roles = bool(inferred_roles_summary)
      if has_people and has_roles:
        parts.append(
          "Review this draft (key people narrative + suggested year-1 roles with wages and timing) and tell me any changes."
        )
      elif has_people:
        parts.append("Review this draft (key people narrative) and tell me any changes.")
      elif has_roles:
        parts.append("Review these suggested year-1 roles (with wages and timing) and tell me any changes.")

      if has_people:
        parts.append("\n\n".join(key_people_blocks))
      if has_roles:
        parts.append(inferred_roles_summary)
      assistant_final = "\n\n".join([p for p in parts if p.strip()]).strip()
      if assistant_final:
        assistant_final = f"{assistant_final}\n\n{PEOPLE_CONFIRM_QUESTION}".strip()
      else:
        assistant_final = PEOPLE_CONFIRM_QUESTION

      append_messages(
        conn,
        draft_id=str(draft_id).strip(),
        new_messages=[user_msg, {"role": "assistant", "content": assistant_final}],
        people_json=people_json,
        marketing_model_json=_refresh_marketing_model(),
        active_focus="people",
        business_facts=business_facts,
        flat_fields=_finalize_flag_field("people", True),
      )
      return jsonify(
        {
          "status": "ok",
          "draft_id": str(draft_id).strip(),
          "client_id": client_id,
          "active_focus": "people",
          "awaiting_confirmation": True,
          "done": False,
          "action": "continue",
          "assistant_message": assistant_final,
        }
      )
    else:
      assistant_final = assistant_text

    assistant_final = sanitize_fact_template(str(assistant_final or "").strip())

    assistant_payload: Dict[str, Any] = {"role": "assistant", "content": assistant_final}

    append_messages(
      conn,
      draft_id=str(draft_id).strip(),
      new_messages=[user_msg, assistant_payload],
      operating_model_json=ops_json if focus == "ops" else None,
      target_market_json=market_json if focus == "market" else None,
      people_json=people_json if focus == "people" else None,
      financials_json=financials_json if focus == "financials" else None,
      financials_year1_json=financials_year1_json if focus == "financials" else None,
      marketing_model_json=_refresh_marketing_model(),
      active_focus=focus,
      business_facts=business_facts,
      flat_fields=_finalize_flag_field(focus, True),
    )

    return jsonify(
      {
        "status": "ok",
        "draft_id": str(draft_id).strip(),
        "client_id": client_id,
        "active_focus": focus,
        "awaiting_confirmation": True,
        "done": False,
        "action": "await_confirmation",
        "assistant_message": assistant_final,
      }
    )
  except Exception as exc:
    app.logger.exception("Failed intake consult: %s", exc)
    return (jsonify({"error": "server_error", "detail": str(exc)}), 500)
  finally:
    try:
      conn.close()
    except Exception:
      pass
